local config = {
  ui_story_5083_50830100_1_dialog_content = "악몽의 원리요...? 사실 저도 잘 모르겠어요.",
  ui_story_5083_50830100_2_dialog_content = "다만, 그 사람의 기억과 밀접한 관련이 있다는 건 확실해요.",
  ui_story_5083_50830100_3_dialog_content = "내려놓을 수 없는 아쉬움이나, 받아들이고 싶지 않은 과거의 일 같은...",
  ui_story_5083_50830100_4_dialog_content = "됐어, 들어도 뭔 소린지 모르겠으니까.\n자, 시작해 봐. 난 널 믿으니까, 네가 뭘 하든 상관없다고.",
  ui_story_5083_50830100_5_dialog_content = "그럼 누워서 긴장을 풀어 보세요... 지금부터 제 의식과 「공명」할 거니까요...",
  ui_story_5083_50830100_6_dialog_content = "음... 졸리군... 어이... 잠깐만, 그럼 나보고 악몽을 또 꾸라는 얘기 아냐...?",
  ui_story_5083_50830100_7_dialog_content = "뭐, 됐어... 애송이 네가 있으니까, 걱정 안 할란다...",
  ui_story_5083_50830100_8_dialog_content = "푹 잠들어서... 자신의 꿈과 마주하세요...",
  ui_story_5083_50830100_9_dialog_content = "<color=#e8d9bb>날카로운 호각 소리가 울려 퍼졌다──</color>",
  ui_story_5083_50830100_10_dialog_content = "「오늘도 총 메고 달린다!」",
  ui_story_5083_50830100_11_dialog_content = "「암귀를 모조리 때려잡자!」",
  ui_story_5083_50830100_12_dialog_content = "여긴...",
  ui_story_5083_50830100_13_dialog_content = "「훈련 개시!」",
  ui_story_5083_50830100_14_dialog_content = "「훈련 개시!」",
  ui_story_5083_50830100_15_dialog_content = "...훈련장이잖아? 옛날 생각나는 구호네.",
  ui_story_5083_50830100_16_dialog_content = "야, 바튼! 왜 뛰다 말고 섰어?!",
  ui_story_5083_50830100_17_dialog_content = "넌... 더그잖아...?",
  ui_story_5083_50830100_18_dialog_content = "뭐야? 잠 안 깼냐? 그럼 계속 그러고 있어.",
  ui_story_5083_50830100_19_dialog_content = "더그가 바튼을 추월했잖아?!",
  ui_story_5083_50830100_20_dialog_content = "아니, 바튼이 갑자기 멈춘 거야... 이거 재미있어질 것 같은데?",
  ui_story_5083_50830100_21_dialog_content = "바튼! 너 이 자식! 훈련 중인데 누가 멈춰도 좋다고 했냐!",
  ui_story_5083_50830100_22_dialog_content = "「군단의 귀감」이 되겠다던 놈은 어디 간 거냐! 게으름 피울 거면 꺼져!\n내 군단을 웃음거리로 만들지 말란 말이다!",
  ui_story_5083_50830100_23_dialog_content = "나머지는 계속 달려라!",
  ui_story_5083_50830100_24_dialog_content = "젠장, 군단장 저 망할 꼰대가... 누구보고 게으름 피운다는 거야?",
  ui_story_5083_50830100_25_dialog_content = "어디 따라잡을 수 있으면 해 보시지!",
  ui_story_5083_50830100_26_dialog_content = "「검을 뽑아라!」",
  ui_story_5083_50830100_27_dialog_content = "잘 봐라! 우오오오!",
  ui_story_5083_50830100_28_dialog_content = "신경 꺼라. 놈의 페이스에 휘말리지 말고 계속 달려!\n복창한다! 「강철 군도는 나의 사랑!」",
  ui_story_5083_50830100_29_dialog_content = "「강철 군도는 나의 사랑!」",
  ui_story_5083_50830100_30_dialog_content = "「탄환 장전도 잊지 마라──」",
  ui_story_5083_50830100_31_dialog_content = "<size=45>우오오오──!</size>",
  ui_story_5083_50830100_32_dialog_content = "바튼... 드디어 따라붙은 거냐.",
  ui_story_5083_50830100_33_dialog_content = "후, 후우── 처음 앞선 주제에 뻐기기는!",
  ui_story_5083_50830100_34_dialog_content = "숨이 많이 차는 모양이지? 마지막 한 바퀴는 내가 이기겠는데?",
  ui_story_5083_50830100_35_dialog_content = "후우... 하아... 그건 두고 보자고!",
  ui_story_5083_50830100_36_dialog_content = "저런 멍청한 놈들...",
  ui_story_5083_50830100_37_dialog_content = "<color=#e8d9bb>나란히 달려 나가는 두 사람은 제2군단의 나머지 병사들을 크게 따돌렸다.</color>",
  ui_story_5083_50830100_38_dialog_content = "<color=#e8d9bb>어느 쪽도 양보하려 하지 않고, 온 힘을 다해 1등의 자리를 두고 다투었다.</color>",
  ui_story_5083_50830100_39_dialog_content = "<color=#e8d9bb>그렇게 두 사람은 가속을 멈추지 않고, 계속해서── 점점 더 가속했다.</color>",
  ui_story_5083_50830100_40_dialog_content = "<size=45>우오오오오오!</size>",
  ui_story_5083_50830100_41_dialog_content = "<color=#e8d9bb>마침내 두 사람은 동시에 결승선에 도달했고, 너무 힘을 쓴 탓에 함께 땅에 쓰러졌다.</color>",
  ui_story_5083_50830100_42_dialog_content = "하...하아... 어, 어때? 인정할 거냐?",
  ui_story_5083_50830100_43_dialog_content = "난 힘 빼고 달렸는데도 따라잡았다고.",
  ui_story_5083_50830100_44_dialog_content = "흥... 초반엔 내가 체력을 아끼고 있었을 뿐이야... 너도 결국 못 이겼잖아?",
  ui_story_5083_50830100_45_dialog_content = "<color=#e8d9bb>두 사람 뒤에서 다른 병사들이 차례로 도착했고, 이윽고 호각 소리가 다시 울려 퍼졌다.</color>",
  ui_story_5083_50830100_46_dialog_content = "오늘 훈련은 여기까지다.\n이 먹고 놀기만 좋아하는 놈들, 빨리 식당으로 안 가고 뭐 하냐!",
  ui_story_5083_50830100_47_dialog_content = "어때? 아직 일어설 수 있겠어?",
  ui_story_5083_50830100_48_dialog_content = "그걸 말이라고, 가자!",
  ui_story_5083_50830100_49_dialog_content = "오늘 메뉴는 뭘까...",
  ui_story_5083_50830100_50_dialog_content = "저번의 그 압축 에너지바랑 오트밀만 아니면 좋겠는데 말이야.",
  ui_story_5083_50830100_51_dialog_content = "바튼, 저기 좀 봐... 9시 방향.",
  ui_story_5083_50830100_52_dialog_content = "왜 식당에 사람이 이렇게 몰려 있어...? 아니지, 저기서 다들 뭐 하는 거야?",
  ui_story_5083_50830100_53_dialog_content = "라인하르트 소위님, 어떻게 하면 소위님처럼 강해질 수 있습니까?",
  ui_story_5083_50830100_54_dialog_content = "그거야 물론 노력과 훈련만이 답이지.",
  ui_story_5083_50830100_55_dialog_content = "소위님, 그럼 저도 같이 훈련해도 되겠습니까?",
  ui_story_5083_50830100_56_dialog_content = "얼마든지. 내 훈련 강도를 따라올 수 있다면 말이야.",
  ui_story_5083_50830100_57_dialog_content = "소위님, 이쪽 한번 봐 주시겠어요? 웃어주세요──",
  ui_story_5083_50830100_58_dialog_content = "하하, 치즈!",
  ui_story_5083_50830100_59_dialog_content = "야, 쟤 뭐야?",
  ui_story_5083_50830100_60_dialog_content = "너랑 똑같이 2년 조기 졸업한 <color=#FFB400>특급 사관생도</color>라던 것 같은데.",
  ui_story_5083_50830100_61_dialog_content = "뭐, 너랑 성격이 달라서 그런 건지, 저 녀석 주변엔 늘 저렇게 사람들이 많더라고.",
  ui_story_5083_50830100_62_dialog_content = "...그나저나 저 녀석이 너랑 같은 성적을 낼 수 있다는 게 상상이 잘 안 된단 말이지.",
  ui_story_5083_50830100_63_dialog_content = "강적인가...",
  ui_story_5083_50830100_64_dialog_content = "호오? 재미있는 녀석이 있잖아...",
  ui_story_5083_50830100_65_dialog_content = "네?",
  ui_story_5083_50830100_66_dialog_content = "아무것도 아냐. 이제 지나가도 될까? 식당에 좀 들어갈게, 고마워.",
  ui_story_5083_50830100_67_dialog_content = "저도 같이 식사하고 싶습니다!",
  ui_story_5083_50830100_68_dialog_content = "저 녀석, 위원회가 뒷배라던데? 그러니까 아무 전공도 없는 신참을 저렇게들 떠받드는 거겠지.",
  ui_story_5083_50830100_69_dialog_content = "흥, 그래봤자 빛 좋은 개살구 아니겠어? 너랑 비교하면 한참 멀었어...\n내 라이벌이 될 자격도 없다고.",
  ui_story_5083_50830100_70_dialog_content = "빛...",
  ui_story_5083_50830100_71_dialog_content = "뭐?",
  ui_story_5083_50830100_72_dialog_content = "재미있네... 저 녀석, 몸에서 뭔가 눈을 뗄 수 없는 빛이 나는 느낌이야.",
  ui_story_5083_50830100_73_dialog_content = "갑자기 그런 예감이 들어. 훗날 대원수 자리를 두고 싸우게 될 건 녀석과 나뿐일 거라고.",
  ui_story_5083_50830100_74_dialog_content = "대원수가 그렇게 쉽게 정해지는 줄 알아?\n아니지... 설마 너까지 저런 인위적인 허상에 속은 거냐?",
  ui_story_5083_50830100_75_dialog_content = "...이런! 여기서 계속 막혀 있다간 맛있는 건 다 바닥나겠어!",
  ui_story_5083_50830100_76_dialog_content = "어이, 같이 가!",
  ui_story_5083_50830100_77_dialog_content = "겨우 과일맛 통조림 두 개라도 건졌네. 밥 한 끼 먹는 게 전쟁보다 힘들다니까.",
  ui_story_5083_50830100_78_dialog_content = "난 사과가 좋은데, 뭐 먹을 거냐?",
  ui_story_5083_50830100_79_dialog_content = "아무거나 상관없어. 남는 거로... 어?!",
  ui_story_5083_50830100_80_dialog_content = "어라?",
  ui_story_5083_50830100_81_dialog_content = "누군가 했네. 저번에 그 시합에서 널 탈탈 털었던 상대잖아?\n벌써 연구원장이 됐다고 들었는데.",
  ui_story_5083_50830100_82_dialog_content = "시끄러워! 통조림이나 이리 내!",
  ui_story_5083_50830100_83_dialog_content = "오오, 너 그때 그... 음... 어... 그때 즐거웠어!",
  ui_story_5083_50830100_84_dialog_content = "내 이름 따윈 기억도 안 하는 거냐?! 난 바튼이다!",
  ui_story_5083_50830100_85_dialog_content = "그치만 너무 쉽게 이긴 데다가, 내가 탈락시킨 사람이 너무 많단 말이야.",
  ui_story_5083_50830100_86_dialog_content = "쳇... 다음엔 반드시 제대로 승부를 내 주마. 잊지 마라, 그로누!",
  ui_story_5083_50830100_87_dialog_content = "두고 보라고... 다음엔 이 바튼 님이 본전도 못 찾게 이겨줄 테니까.",
  ui_story_5083_50830100_88_dialog_content = "그렇게 이를 갈면서 설거지하는 놈은 아마 너뿐일 거다. 오래 살았더니 이런 놈도 다 보는군.",
  ui_story_5083_50830100_89_dialog_content = "...군단장님! 오셨습니까!",
  ui_story_5083_50830100_90_dialog_content = "자난성 바닥에서 해라도 뜬 거냐? 네놈이 설거지를 느긋하게 하고 있다니,\n평소엔 대충 닦아서 치우고 훈련하러 가 놓고 말이야.",
  ui_story_5083_50830100_91_dialog_content = "뭐냐, 머리라도 다친 거냐?",
  ui_story_5083_50830100_92_dialog_content = "아닙니다!",
  ui_story_5083_50830100_93_dialog_content = "그럼 뭐가 어떻게 된 거냐.",
  ui_story_5083_50830100_94_dialog_content = "저도 잘 모르겠습니다! 왠지 오늘은 하루 쉬고 싶은 것 같습니다!",
  ui_story_5083_50830100_95_dialog_content = "뭐 「워라밸」인가 하는 그거냐? 아니면 「그 전투」에서 트라우마라도 생긴 거냐?",
  ui_story_5083_50830100_96_dialog_content = "아닙니다!",
  ui_story_5083_50830100_97_dialog_content = "그럼 성격이 바뀐 모양이군!\n뭐, 됐다. 머리를 다친 게 아니라면, 지금처럼 하는 것도 좋겠지... 흐아압!",
  ui_story_5083_50830100_98_dialog_content = "으억!",
  ui_story_5083_50830100_99_dialog_content = "허점도 잔뜩이고, 약해 빠졌어! 그러고도 우리 2군단의 귀감이라 할 수 있겠나!",
  ui_story_5083_50830100_100_dialog_content = "아닙니다! 신뢰하는 상대가 기습을 할 거라는 예상까진 못했을 뿐입니다!",
  ui_story_5083_50830100_101_dialog_content = "만약 내 말대로 늘 경계를 늦추지 않고 검을 뽑을 준비가 되어 있었다면,\n이렇게 쉽게 습격을 허용했을 것 같나?",
  ui_story_5083_50830100_102_dialog_content = "인정하기 싫은 모양이군. 하지만 이기는 수가 곧 좋은 수다.\n싸움은 오직 결과로만 말한다. 정면승부만이 답이 아니란 말이다!",
  ui_story_5083_50830100_103_dialog_content = "넌 「탄환」으로서 불합격이다. 아직도 더 갈고 닦아야만 한다.",
  ui_story_5083_50830100_104_dialog_content = "당장 훈련장으로 가라! 네 평소 강도대로 20바퀴 실시!",
  ui_story_5083_50830100_105_dialog_content = "...예!",
  ui_story_5083_50830100_106_dialog_content = "뭘 인상을 구기고 있어?! 가서 구호도 크게 외치면서 똑바로 달리란 말이다!",
  ui_story_5083_50830100_107_dialog_content = "예!",
  ui_story_5083_50830100_108_dialog_content = "「오늘도 총 메고 달린다!」",
  ui_story_5083_50830100_109_dialog_content = "더 크게!",
  ui_story_5083_50830100_110_dialog_content = "<size=45>「암귀를 모조리 때려잡자!」</size>",
  ui_story_5083_50830100_111_dialog_content = "뭐야...? 바튼 저 자식, 몰래 훈련하는 거야?",
  ui_story_5083_50830100_112_dialog_content = "나 몰래 더 강해지려고? 어림도 없다!",
  ui_story_5083_50830100_113_dialog_content = "어이, 바튼! 너 따라잡혔어!",
  ui_story_5083_50830100_114_dialog_content = "멍청아, 누가 너랑 시합한댔냐?",
  ui_story_5083_50830100_115_dialog_content = "내가 있는 한 몰래 1등이 될 생각은 꿈도 꾸지 말라고.",
  ui_story_5083_50830100_116_dialog_content = "아오! 저 머저리가!",
  ui_story_5083_50830100_117_dialog_content = "머저리는 너겠지!",
  ui_story_5083_50830100_118_dialog_content = "하, 하하하──",
  ui_story_5083_50830100_119_dialog_content = "라인하르트 소위님?",
  ui_story_5083_50830100_120_dialog_content = "저 둘... 참 재미있네.",
  ui_story_5083_50830200_1_dialog_content = "<color=#e8d9bb>날카로운 호각 소리가 울려 퍼졌다──</color>",
  ui_story_5083_50830200_2_dialog_content = "지금 즉시 복장을 착용하고 장비를 챙겨라!",
  ui_story_5083_50830200_3_dialog_content = "시간이 다 됐다!",
  ui_story_5083_50830200_4_dialog_content = "우오오오오오──",
  ui_story_5083_50830200_5_dialog_content = "으음...?",
  ui_story_5083_50830200_6_dialog_content = "셋, 둘, 하나!",
  ui_story_5083_50830200_7_dialog_content = "<color=#e8d9bb>얼음물이 바튼을 향해 뿌려졌고, 뼈를 찌르는 냉기는 순식간에 의식을 뚜렷하게 만들었다.</color>",
  ui_story_5083_50830200_8_dialog_content = "<size=45>으아아악!</size>",
  ui_story_5083_50830200_9_dialog_content = "전원 훈련 개시!\n이 게을러 빠진 놈들, 너흰 제대로 「연마」하지 않으면 어엿한 군인이 될 수 없다!",
  ui_story_5083_50830200_10_dialog_content = "기상과 장비 착용도 5초 안에 못 마친다면, 앞으로 전장에선 어떻게 싸울 셈이냐!",
  ui_story_5083_50830200_11_dialog_content = "자신을 「탄환」이라고 생각해라! 신속하고 치명적이게!\n자, 10초 안에 훈련장으로 이동해라! 늦는 놈은 훈련량을 2배로 늘린다!",
  ui_story_5083_50830200_12_dialog_content = "바튼, 넌 머리에 양동이 지고 뛰어라!",
  ui_story_5083_50830200_13_dialog_content = "그리고 더그가 두 바퀴 뛸 때까지 못 따라잡으면 1초 늦을 때마다 한 바퀴 추가다!",
  ui_story_5083_50830200_14_dialog_content = "아니... 얼음물 샤워에... 바지 벨트도 못 찼는데... 그것보다 왜 저만 물벼락을 맞은 겁니까?!",
  ui_story_5083_50830200_15_dialog_content = "맞아도 싸지! 내 말대로 늘 경계를 게을리하지 않고 검을 쥐고 있었으면 그렇게 됐겠냐!",
  ui_story_5083_50830200_16_dialog_content = "네놈이 밥 처먹고 목욕할 동안 암귀가 기다려 줄 것 같냐! 암귀는 언제든지 나타난다!\n어떤 순간에도 경계를 늦춰선 안 된단 말이다!",
  ui_story_5083_50830200_17_dialog_content = "물벼락을 뭘 어떻게 경계하냔 말입니다!",
  ui_story_5083_50830200_18_dialog_content = "물방울을 베겠다는 각오는 가질 생각도 못 해놓고 어떻게 군단의 귀감이 되겠다는 거냐!",
  ui_story_5083_50830200_19_dialog_content = "총이 있으면 됐지 뭘... 아니, 애초에 무슨 말도 안 되는 얘기를 하고 앉았어...",
  ui_story_5083_50830200_20_dialog_content = "제일 먼저 꺼내드는 게 총이어선 안 된다!\n그리고 언제까지 벨트나 만지작거릴 셈이냐! 빨리 뛰지 못해?!",
  ui_story_5083_50830200_21_dialog_content = "더그 저 자식, 더럽게 빠르네... 저거 일부러 저러지 또!",
  ui_story_5083_50830200_22_dialog_content = "흥, 어디 어떻게 따라잡는지 한번 보자고.",
  ui_story_5083_50830200_23_dialog_content = "내가 질 줄 알고! <size=45>간다!</size>",
  ui_story_5083_50830200_24_dialog_content = "<color=#e8d9bb>바튼은 포효하며 양동이를 내던졌고, 바지를 잡아 찢어 반바지로 만들더니\n병사들을 향해 미칠 듯한 속도로 달려갔다.</color>",
  ui_story_5083_50830200_25_dialog_content = "저 자식이 늦잠을 다 자다니, 바튼답지 않은데...",
  ui_story_5083_50830200_26_dialog_content = "<size=45>더그! 내가 왔다!</size>",
  ui_story_5083_50830200_27_dialog_content = "바튼, 이제야... 어이! 그 꼴은 또 뭐야?!",
  ui_story_5083_50830200_28_dialog_content = "옷도 엉망으로 입고, 바지도 아주 가관이네...\n너 무슨 광대냐? 2군단 개망신 주려고 작정했어?!",
  ui_story_5083_50830200_29_dialog_content = "시끄러워! 이런 핸디캡이 걸린 나한테 따라잡힌 주제에 뭘 잘났다고 지적질이야?",
  ui_story_5083_50830200_30_dialog_content = "네 꼴이 쪽팔려서 그런다!",
  ui_story_5083_50830200_31_dialog_content = "흥, 그냥 무서운 거겠지!",
  ui_story_5083_50830200_32_dialog_content = "<color=#e8d9bb>누군가의 모습이 마치 번개처럼 두 사람 곁을 스쳐 지나갔고,\n두 사람의 말싸움도 그와 동시에 중단되었다.</color>",
  ui_story_5083_50830200_33_dialog_content = "하나, 둘, 하나, 둘...",
  ui_story_5083_50830200_34_dialog_content = "......",
  ui_story_5083_50830200_35_dialog_content = "<color=#e8d9bb>두 사람은 약속이라도 한 듯이 입을 다물고는 있는 힘껏 속도를 높여 그 누군가를 뒤쫓았다.</color>",
  ui_story_5083_50830200_36_dialog_content = "하나, 둘, 하나, 둘...",
  ui_story_5083_50830200_37_dialog_content = "<color=#e8d9bb>세 사람의 속도는 갈수록 빨라졌고... 그들은 모든 병사들의 놀라움이 담긴 시선을 받으며\n결승선을 향해 달렸다.</color>",
  ui_story_5083_50830200_38_dialog_content = "질 순 없지──!",
  ui_story_5083_50830200_39_dialog_content = "<color=#e8d9bb>세 사람은 동시에 결승선을 통과했고, 마지막 힘을 다 쓴 바튼과 더그는 서서히 멈춰 섰다.\n그러나...</color>",
  ui_story_5083_50830200_40_dialog_content = "하나, 둘, 하나, 둘...",
  ui_story_5083_50830200_41_dialog_content = "<color=#e8d9bb>라인하르트는 속도를 줄였을 뿐, 여전히 멈추지 않고 달렸다.</color>",
  ui_story_5083_50830200_42_dialog_content = "저 녀석...",
  ui_story_5083_50830200_43_dialog_content = "흥, 우쭐대기는.",
  ui_story_5083_50830200_44_dialog_content = "저런 도발을 그냥 넘어갈 작정이야? 어이, 더 달릴 수 있겠어?",
  ui_story_5083_50830200_45_dialog_content = "당연하지, 지금 당...",
  ui_story_5083_50830200_46_dialog_content = "<color=#e8d9bb>호각 소리가 울리고, 병사들은 집합했다.</color>",
  ui_story_5083_50830200_47_dialog_content = "쳇, 가자고.",
  ui_story_5083_50830200_48_dialog_content = "저 녀석, 1군단 소속이지? 감히 우리 2군단 훈련장에 들어와서 우릴 도발하다니...",
  ui_story_5083_50830200_49_dialog_content = "뭐, 상관없어. 어차피 우리가 1군단 신참한테도 밀려선 안 될 일이잖아?",
  ui_story_5083_50830200_50_dialog_content = "푸웁──",
  ui_story_5083_50830200_51_dialog_content = "바튼 군은 나도 못 이기면서, 라인하르트를 따라잡겠다고? 무리야.",
  ui_story_5083_50830200_52_dialog_content = "또 너냐... 흥. 우쭐대지 마라. 나도 계속해서 강해지고 있으니까.",
  ui_story_5083_50830200_53_dialog_content = "어~? 바튼 군, 반박 안 하는 거야?",
  ui_story_5083_50830200_54_dialog_content = "너한테 진 건 사실이잖냐. 딱히 반박할 것도 없다고.",
  ui_story_5083_50830200_55_dialog_content = "그것보다... 지금은 훈련 시간인데 넌 왜 나무 밑에 숨어 있냐?!",
  ui_story_5083_50830200_56_dialog_content = "난 연구원장이야. 지금 난 내 「일」을 하고 있다구.",
  ui_story_5083_50830200_57_dialog_content = "「일」이라니... 그건 또 뭔 장난감이냐?",
  ui_story_5083_50830200_58_dialog_content = "어이, 바튼. 그만 떠들고 얼른 집합하러 가자.",
  ui_story_5083_50830200_59_dialog_content = "망할 꼰대 좀 기다리게 하는 게 뭐 어때서!",
  ui_story_5083_50830200_60_dialog_content = "이거 무시하면 안 돼. 이건 일루미나 군인의 운명을 바꿀 발명이라구!",
  ui_story_5083_50830200_61_dialog_content = "「차세대형 서포트 드론」! 이게 완성되면 병사들의 든든한 조력자가 돼 줄 수 있을 거야.",
  ui_story_5083_50830200_62_dialog_content = "오오! 설마 저번 왕좌 토너먼트 때보다 더 발전한 거냐?",
  ui_story_5083_50830200_63_dialog_content = "보는 눈이 있네! 봐, 이 구조만 해도 개발하는 데 한참 걸렸다니까.",
  ui_story_5083_50830200_64_dialog_content = "바튼!",
  ui_story_5083_50830200_65_dialog_content = "또 뭐?",
  ui_story_5083_50830200_66_dialog_content = "바튼! 더그! 이 게으른 머저리 놈들!",
  ui_story_5083_50830200_67_dialog_content = "가서 옷 갈아입고 「중앙 탑」 조명 아래 똑바로 서 있어! 하루 종일 한 발짝도 벗어나지 마!",
  ui_story_5083_50830200_68_dialog_content = "예?!",
  ui_story_5083_50830200_69_dialog_content = "<color=#e8d9bb>많은 사람들이 오가는 중앙 탑 앞, 이곳은 물자 수송의 중추이자 자난성의 심장이다.</color>",
  ui_story_5083_50830200_70_dialog_content = "<color=#e8d9bb>따라서 그 밝은 조명 아래에 선 두 사람의 모습은 한층 더 눈에 띄었다.</color>",
  ui_story_5083_50830200_71_dialog_content = "......",
  ui_story_5083_50830200_72_dialog_content = "......",
  ui_story_5083_50830200_73_dialog_content = "...미안하다.",
  ui_story_5083_50830200_74_dialog_content = "음?",
  ui_story_5083_50830200_75_dialog_content = "나 때문에 너까지...",
  ui_story_5083_50830200_76_dialog_content = "너 요 며칠 좀 이상해.",
  ui_story_5083_50830200_77_dialog_content = "저번의 「그 전투」 때문이야?",
  ui_story_5083_50830200_78_dialog_content = "너무 신경 쓰지 마. 전부 네 탓인 것도 아니잖아.",
  ui_story_5083_50830200_79_dialog_content = "뜻대로 잘 되지 않았을 뿐이야... 계속 기죽고 있지 말라고.\n지금처럼 맥 빠진 놈을 이겨봤자 의미도 없고 말이야.",
  ui_story_5083_50830200_80_dialog_content = "그리고 넌... 팡고 군단장님이 말씀하신, 우리 중에서 「가장 가망 있는 신참」이니까.",
  ui_story_5083_50830200_81_dialog_content = "하? 그 망할 꼰대가 뒤에서 날 칭찬했다고?",
  ui_story_5083_50830200_82_dialog_content = "거 참, 건방진 자식 아니랄까 봐...",
  ui_story_5083_50830200_83_dialog_content = "고마워.",
  ui_story_5083_50830200_84_dialog_content = "?!",
  ui_story_5083_50830200_85_dialog_content = "생각해 보니까 저번에 고맙단 말을 안 했더라고.",
  ui_story_5083_50830200_86_dialog_content = "제때 도우러 와 줘서 고맙다.",
  ui_story_5083_50830200_87_dialog_content = "...나도 그저 군단장님 명령을 수행했을 뿐이야.",
  ui_story_5083_50830200_88_dialog_content = "후... 날씨가 덥구만...",
  ui_story_5083_50830200_89_dialog_content = "<color=#e8d9bb>밝고 뜨거운 중앙 탑의 조명 아래, 두 군인은 땀을 흘리며 하루 종일 그 자리에 서 있었다.</color>",
  ui_story_5083_50830200_90_dialog_content = "<color=#e8d9bb>그 악마 군단장이 구겨진 표정으로 찾아와 두 사람을 데리고 돌아갈 때까지...</color>",
  ui_story_5083_50830200_91_dialog_content = "젠장... 자칫하면 「여명의 빛」에 익어버릴 뻔했잖아.",
  ui_story_5083_50830200_92_dialog_content = "더그가 식당에 갈 수 있어서 망정이지... 그럼 일단 목욕이나 좀 할까...",
  ui_story_5083_50830200_93_dialog_content = "삐빅──바, 튼, 발, 견.",
  ui_story_5083_50830200_94_dialog_content = "어? 드론인가...? 너 날 어떻게 알아?",
  ui_story_5083_50830200_95_dialog_content = "너 그로누가 만든 드론이냐?",
  ui_story_5083_50830200_96_dialog_content = "바튼 씨... 전 당신의 「조종사」예요.",
  ui_story_5083_50830200_97_dialog_content = "하아? 그게 무슨 소리야?",
  ui_story_5083_50830200_98_dialog_content = "제가 바튼 씨를 「인도」해 줄게요...",
  ui_story_5083_50830200_99_dialog_content = "이건 또 뭐야... 구형 모델처럼 생겼는데, 하는 짓은 꽤 귀엽네.",
  ui_story_5083_50830200_100_dialog_content = "...설마 군수사령부에서 보내준 건가?",
  ui_story_5083_50830200_101_dialog_content = "뭐, 아무튼 마음에 들어! 길 안내라면 따라주마.",
  ui_story_5083_50830200_102_dialog_content = "알겠습니다.",
  ui_story_5083_50830200_103_dialog_content = "삐빅, 바튼 씨... 제가...",
  ui_story_5083_50830200_104_dialog_content = "제가... 이...... 에서 벗어나게 해 줄게요...",
  ui_story_5083_50830301_1_dialog_content = "삐빅, 바튼 씨가... 목욕을 하고 싶다는 것을 감지했습니다...",
  ui_story_5083_50830301_2_dialog_content = "숙소에는 사람이 많습니다. 검색 중... 생활 구역의 목욕탕을 찾았습니다...\n경로를 탐색했습니다. 따라오세요.",
  ui_story_5083_50830301_3_dialog_content = "오오! 너 꽤 똑똑하잖아! 지금까지 봤던 드론 중에서 제일 똑똑하네.",
  ui_story_5083_50830301_4_dialog_content = "해체해서 속에 뭐가 있나 좀 봤으면 좋겠는데 말이야.",
  ui_story_5083_50830301_5_dialog_content = "삐빅! 아, 안 돼요──",
  ui_story_5083_50830301_6_dialog_content = "농담이야. 너 같은 기종은 나도 처음 보는 거라 멋대로 해체하면 조립도 못 할 거라고.",
  ui_story_5083_50830301_7_dialog_content = "삐빅... 목적지까지 380m 남았습니다.\n전방의 길목에서 엘리베이터를 타고 아래로 내려가세요.",
  ui_story_5083_50830301_8_dialog_content = "역시 길 안내가 있으니까 편하네. 자난성 길은 나도 가끔 너무 복잡하다 싶었거든.",
  ui_story_5083_50830301_9_dialog_content = "다른 지하성에도 너 같은 걸 보급하면 좋을 텐데.",
  ui_story_5083_50830301_10_dialog_content = "현재 위치는... 생활 구역의 9번 통로 상부입니다. 이제 곧 중앙 기념비를 지나갑니다──",
  ui_story_5083_50830301_11_dialog_content = "잠깐만.",
  ui_story_5083_50830301_12_dialog_content = "삐빅, 바튼 씨...?",
  ui_story_5083_50830301_13_dialog_content = "기념비라...",
  ui_story_5083_50830301_14_dialog_content = "여기서도 잘 보이는군.",
  ui_story_5083_50830301_15_dialog_content = "녀석들 이름도... 벌써 새겨진 건가.",
  ui_story_5083_50830301_16_dialog_content = "<color=#e8d9bb>「그 전투」── 그것은 바튼의 최근 기억 속에서 자신이 처음으로 지휘한 전투였다.</color>",
  ui_story_5083_50830301_17_dialog_content = "<color=#e8d9bb>하늘은 음울하게 흐렸고, 비까지 추적추적 내리고 있었다.</color>",
  ui_story_5083_50830301_18_dialog_content = "빨리! 모래주머니를 최전선까지 옮겨!",
  ui_story_5083_50830301_19_dialog_content = "오른쪽 2번 참호가 암귀로 가득 찼어! 가서 좀 뚫어 봐!",
  ui_story_5083_50830301_20_dialog_content = "부소대장님! 모래주머니가 부족합니다!",
  ui_story_5083_50830301_21_dialog_content = "...병력도 부족합니다. 진지 전체를 지키는 건 무리입니다.",
  ui_story_5083_50830301_22_dialog_content = "민간인 철수는 끝났어?",
  ui_story_5083_50830301_23_dialog_content = "아직입니다... 지하성의 「에너지 중추」가 고장 나 수송 기능이 마비된 탓에,\n철수도 좀처럼 속도가 나질 않습니다.",
  ui_story_5083_50830301_24_dialog_content = "부소대장님, 어떻게 하면 좋을까요?",
  ui_story_5083_50830301_25_dialog_content = "뭐라도 가져다 방어선부터 메우고, 나머지는 각자 되는 데까지 임무에 최선을 다해.",
  ui_story_5083_50830301_26_dialog_content = "바튼 소위님은 어디 계시지? 지금 상황에선 내가 멋대로 결정할 순 없어.\n바튼 소위님께 결정을 부탁하도록 해.",
  ui_story_5083_50830301_27_dialog_content = "소위님은 방금 막 전선에서 물러나 뒤쪽에서 휴식을 취하고 계십니다.",
  ui_story_5083_50830301_28_dialog_content = "정찰병! 놈들이 언제쯤 공격을 재개할 것 같지?",
  ui_story_5083_50830301_29_dialog_content = "금방 다시 시작될 겁니다! 놈들은 지금도 계속해서 병력을 보충하고 있습니다.",
  ui_story_5083_50830301_30_dialog_content = "통신병은 어디 있어? 통신 회로 복구는 아직인가? 군단장님 쪽은 어디쯤 오신 거야?!",
  ui_story_5083_50830301_31_dialog_content = "부소대장님... 통신반은 모두 당했습니다.",
  ui_story_5083_50830301_32_dialog_content = "이제 어떡합니까...?",
  ui_story_5083_50830301_33_dialog_content = "군단장님께선 반드시 오실 거야. 그때까지 버티기만 하면 돼.",
  ui_story_5083_50830301_34_dialog_content = "하지만 이번 전투에서 이미 6개의 지하성이 함락당했어.\n전방엔 우리보다 더 도움이 필요한 사람들이 있어.",
  ui_story_5083_50830301_35_dialog_content = "만약 군단장님 쪽이 전선에서 고전하고 계신다면...",
  ui_story_5083_50830301_36_dialog_content = "뭐, 우린 그들을 위해서라도 버텨야겠지.",
  ui_story_5083_50830301_37_dialog_content = "하지만 이제 뭘 어떻게 해야 하는 건가요... 전 가족이 있습니다...",
  ui_story_5083_50830301_38_dialog_content = "미안해... 내가 해줄 수 있는 말은 없어.",
  ui_story_5083_50830301_39_dialog_content = "우리 임무는 여길 사수하며 암귀가 가지 못하게 막는 거야.",
  ui_story_5083_50830301_40_dialog_content = "저 많은 일루미나의 동포들이 우리한테 등을 맡기고 있어...",
  ui_story_5083_50830301_41_dialog_content = "그러니까... 명예를 위해 끝까지 함께 싸워야 해.",
  ui_story_5083_50830301_42_dialog_content = "저, 전... 너무 무섭습니다... 집을 나설 때 어머니가 새로 짠 머플러를 감아 주셨는데...\n아니... 언제 다 타버린 거지...",
  ui_story_5083_50830301_43_dialog_content = "......",
  ui_story_5083_50830301_44_dialog_content = "...바튼 소위님께는 죄송하지만... 누가 가서 좀 깨워드려.",
  ui_story_5083_50830301_45_dialog_content = "지금은 소위님이 결단을 내려주셔야만 해.",
  ui_story_5083_50830301_46_dialog_content = "바튼 소위님... 소위님...",
  ui_story_5083_50830301_47_dialog_content = "뭐야? 지금 막 잠들었다고... 너희도 얼른 교대로 쉬어라.\n다음 공격이 또 언제 올지 모르니까.",
  ui_story_5083_50830301_48_dialog_content = "보고드립니다! 현재 통신반이 모두 당해서 군단 내 정보망과 단절된 상태입니다.",
  ui_story_5083_50830301_49_dialog_content = "대대장님 쪽도... 전부 방금 전 엄호 작전에서 전사하셨습니다.",
  ui_story_5083_50830301_50_dialog_content = "알겠어... 전시 규칙에 따라 내가 최고 지휘관이 됐다는 거잖아?",
  ui_story_5083_50830301_51_dialog_content = "지도 좀 보여줘.",
  ui_story_5083_50830301_52_dialog_content = "정찰병의 정보에 따르면 암귀들은 북쪽 고지에 모여 있고, 현재 원거리 타격은 불가능합니다.",
  ui_story_5083_50830301_53_dialog_content = "지하성의 기능 대부분도 조금 전 첫 공세 때 완전히 마비되어 버렸습니다.",
  ui_story_5083_50830301_54_dialog_content = "이제 군단장님이 어디 계시는지, 지원은 오시는지조차 정보가 없는 상황입니다.",
  ui_story_5083_50830301_55_dialog_content = "병사들 중엔... 저희도 여길 버리고 비전투인원들과 함께 철수해야 한다고\n생각하는 이들도 있습니다.",
  ui_story_5083_50830301_56_dialog_content = "하지만 그렇게 된다면 지하성 하나를 통째로 포기하게 되는 겁니다!",
  ui_story_5083_50830301_57_dialog_content = "병력은 얼마나 더 남았지?",
  ui_story_5083_50830301_58_dialog_content = "300명도 채 안 됩니다... 지하성을 지키긴 힘듭니다.",
  ui_story_5083_50830301_59_dialog_content = "...워게임보다 더 어려운 상황이군.",
  ui_story_5083_50830301_60_dialog_content = "그 망할 꼰대, 지하성 하나를 통째로 지키라고 맡기다니...\n우리가 죽을 각오로 싸워서 망정이지, 아니었으면 전부 지하에서 죽었을 거다.",
  ui_story_5083_50830301_61_dialog_content = "그럼 이제 길은 하나뿐이군...",
  ui_story_5083_50830301_62_dialog_content = "바튼 소위님! <size=45>전령병이 도착했습니다!</size>",
  ui_story_5083_50830301_63_dialog_content = "들어와. 좋은 소식을 가져왔나?",
  ui_story_5083_50830301_64_dialog_content = "군단장님께서 기습 작전을 성공시켜 이미 지하성 세 곳을 구하셨습니다.\n지금은 이쪽으로 오시는 중입니다!",
  ui_story_5083_50830301_65_dialog_content = "제시간에 오실 테니 계속해서 버텨 주십시오.",
  ui_story_5083_50830301_66_dialog_content = "뭐야? 너 지금 그걸 좋은 소식이라고 말하는 거냐? 우리 꼬라지 안 보여?",
  ui_story_5083_50830301_67_dialog_content = "그래도 버텨야 합니다... 어려운 일이라는 건 물론 군단장님께서도 알고 계십니다.\n하지만 여러분의 용맹과 희생이 없었다면 다른 지하성들도 이미 전멸했을 겁니다.",
  ui_story_5083_50830301_68_dialog_content = "부디 군단장님을 믿어 주십시오. 지원은 반드시 올 겁니다.",
  ui_story_5083_50830301_69_dialog_content = "바튼 소위님, 암귀 놈들이 움직임을 보였습니다. 이제 어떻게 하면 좋을까요?",
  ui_story_5083_50830301_70_dialog_content = "지하성 쪽 철수도 끝나지 않은 상황에서 저희가 안으로 퇴각한다면,\n암귀가 우릴 피해서 철수 행렬을 노릴 가능성도 배제할 수 없습니다...",
  ui_story_5083_50830301_71_dialog_content = "하지만 이 진지는 지금 허물어지기 직전입니다... 돌파당하지 않는다는 보장도 없습니다...",
  ui_story_5083_50830301_72_dialog_content = "우린 돌격한다.",
  ui_story_5083_50830301_73_dialog_content = "예?",
  ui_story_5083_50830301_74_dialog_content = "명령을 전달하라. 전군 돌격 준비에 착수하도록!",
  ui_story_5083_50830301_75_dialog_content = "언제까지 저 망할 놈들이 날뛰게 놔둘 생각이냐!",
  ui_story_5083_50830301_76_dialog_content = "우리 뒤에 있는 사람들, 자난성의 가족들을 생각해 보란 말이다...\n너흰 겁쟁이처럼 여기서 죽고 싶은 거냐?",
  ui_story_5083_50830301_77_dialog_content = "바튼 소위님, 진정하십시오. 군단장님의 수비 명령이 이미 내려지지 않았습니까!",
  ui_story_5083_50830301_78_dialog_content = "내가 진정이 될 것 같냐?! 우린 여기서 열흘을 죽도록 싸우면서 잠도 제대로 못 잤어...\n그런데도 나보고 쟤들을 여기 더 처박아 두라고?",
  ui_story_5083_50830301_79_dialog_content = "이놈들 전부 무서워하고 있는 거 모르겠어? 이대로 여기서 죽게 놔둘 순 없다고!",
  ui_story_5083_50830301_80_dialog_content = "우린 2군단이다. 숨지도 않고, 물러나지도 않는다!",
  ui_story_5083_50830301_81_dialog_content = "이래도 죽고 저래도 죽는다면, 돌격해서 죽겠다!",
  ui_story_5083_50830301_82_dialog_content = "바튼 소위님...!",
  ui_story_5083_50830301_83_dialog_content = "놈들을 박살 내! 더는 한 발짝도 전진하지 못하게 하라고!",
  ui_story_5083_50830301_84_dialog_content = "<size=45>전군 위치로! 무기를 들고──</size>",
  ui_story_5083_50830301_85_dialog_content = "<size=45>돌격!!!</size>",
  ui_story_5083_50830302_1_dialog_content = "<color=#e8d9bb>동트기 전 하늘은 잿빛 구름으로 뒤덮여 있었고, 돌격의 나팔 소리가 회색 하늘에 울려 퍼졌다.\n지하성을 태워 없애려는 맹렬한 화염을 앞에 두고, 가장 처참한 싸움이 시작됐다.</color>",
  ui_story_5083_50830302_2_dialog_content = "쏴라! 계속 쏴!",
  ui_story_5083_50830302_3_dialog_content = "놈들이 겁먹었다! 지금이 기회다──",
  ui_story_5083_50830302_4_dialog_content = "크오오!",
  ui_story_5083_50830302_5_dialog_content = "멈추지 마라! 저 고지를 점령하고 뒤의 녀석들한테 대포를 가져오라고 해!",
  ui_story_5083_50830302_6_dialog_content = "<color=#e8d9bb>나팔 소리는 계속해서 울렸고, 일루미나의 군인들은 발걸음을 멈추지 않고 나아갔다.</color>",
  ui_story_5083_50830302_7_dialog_content = "캬아아악!",
  ui_story_5083_50830302_8_dialog_content = "계속 돌격해!",
  ui_story_5083_50830302_9_dialog_content = "<color=#e8d9bb>나팔을 울리던 병사가 쓰러져도, 또 다른 병사가 그의 사명을 이어받았다.</color>",
  ui_story_5083_50830302_10_dialog_content = "포병은 어디 있냐! 빨리 따라와!",
  ui_story_5083_50830302_11_dialog_content = "<color=#e8d9bb>고기분쇄기 같은 전장 속, 바튼은 이미 피로 물들어 있었다.\n그러나 그는 여전히 군기를 손에 꽉 쥐고 가장 선두에서 달리고 있었다.</color>",
  ui_story_5083_50830302_12_dialog_content = "내가 엄호하겠다!",
  ui_story_5083_50830302_13_dialog_content = "<color=#e8d9bb>바튼은 한 손으로 군기를 잡고, 다른 손으로 쓰러진 전우의 기관총을 들어,\n고지대에서 파도처럼 밀려오는 암귀를 향해 쏘아댔다.</color>",
  ui_story_5083_50830302_14_dialog_content = "나한테서 이걸 뺏을 생각이라면, 꿈도 꾸지 마라!",
  ui_story_5083_50830302_15_dialog_content = "<color=#e8d9bb>바튼이 던진 군기는 투창처럼 암귀를 꿰뚫고 고지 정상에 꽂혔고,\n그 일루미나의 찬란한 빛은 병사들의 눈동자를 밝게 비추었다.</color>",
  ui_story_5083_50830302_16_dialog_content = "와라! 이 개자식들아! 다 덤비라고!",
  ui_story_5083_50830302_17_dialog_content = "바튼──!",
  ui_story_5083_50830302_18_dialog_content = "...뭐야... 더그?",
  ui_story_5083_50830302_19_dialog_content = "<color=#e8d9bb>여명이 하늘을 밝히며, 피로 물들어 있던 바튼의 시야를 열어주었고,\n지평선 위로 한 부대가 나타난 것이 보였다.</color>",
  ui_story_5083_50830302_20_dialog_content = "이 등신아... 거기서 돌격을 해?",
  ui_story_5083_50830302_21_dialog_content = "후, 진짜... 명령을 하달한다! 전원 돌격!",
  ui_story_5083_50830302_22_dialog_content = "그 어떤 대가를 치러서라도 저 고지를 사수한다!\n바튼 소위가 계속해서 제압사격을 할 수 있도록 지원하라!",
  ui_story_5083_50830302_23_dialog_content = "예!",
  ui_story_5083_50830302_24_dialog_content = "하하하하! 봤냐? 내 지원군이 왔다고! 망할 놈들, 이제 얌전히 뒈져!",
  ui_story_5083_50830302_25_dialog_content = "<color=#e8d9bb>나팔 소리가 하늘 아래를 메우며 하나둘씩 이어졌다.\n두려움 없는 병사들은 전진하며, 「검은 파도」을 빛 아래에서 지워나갔다.</color>",
  ui_story_5083_50830302_26_dialog_content = "<color=#e8d9bb>태양이 지평선을 떠나갈 무렵... 연이어 쓰러진 병사들의 시신은\n마치 방어벽처럼 등 뒤의 지하성을 지켜냈다.</color>",
  ui_story_5083_50830302_27_dialog_content = "바튼... 살았냐?",
  ui_story_5083_50830302_28_dialog_content = "크헉... 부르지... 마라... 안 죽은 것 같으니까... 뭐 어디 하나 날아간 곳도 없고...\n근데 피가 굳어서 눈이 안 떠져...",
  ui_story_5083_50830302_29_dialog_content = "...이 자식아...",
  ui_story_5083_50830302_30_dialog_content = "흥... 까딱하면 이런 데서 너랑 같이 전사할 뻔했잖아. 진짜 악몽이 따로없네...",
  ui_story_5083_50830302_31_dialog_content = "쉿! 조용히 해 봐. 저거 들려?",
  ui_story_5083_50830302_32_dialog_content = "<color=#e8d9bb>햇살이 점차 강해지며, 맹렬한 나팔 소리가 한 번 시작되더니 멈추지 않고 울려댔다.</color>",
  ui_story_5083_50830302_33_dialog_content = "본대 신호야... 망할 꼰대가 왔어...",
  ui_story_5083_50830302_34_dialog_content = "진짜... 왔잖아... 아주... 더럽게 딱 맞춰서들 오셨네... 염병할...",
  ui_story_5083_50830302_35_dialog_content = "더그! 바튼!",
  ui_story_5083_50830302_36_dialog_content = "...이 멍청한 새끼들 대체 어디 있냐고!",
  ui_story_5083_50830302_37_dialog_content = "<color=#e8d9bb>떨리는 목소리가 시체의 산과 피바다에 메아리쳤다.\n그 「철혈」의 군단장은 혈안이 되어 쓰러진 부하들의 시신을 하나하나 확인하고 있었다.</color>",
  ui_story_5083_50830302_38_dialog_content = "일루미나의 아이들이 전부...",
  ui_story_5083_50830302_39_dialog_content = "더그, 바튼──! 빌어먹을... 너희들까지... 안 돼...",
  ui_story_5083_50830302_40_dialog_content = "이놈들아...",
  ui_story_5083_50830302_41_dialog_content = "...뭐야?! 너 이 새끼들! 안 죽었잖아!",
  ui_story_5083_50830302_42_dialog_content = "군단장님... 보고드립니다... 임무를 무사히 완수했습니다.",
  ui_story_5083_50830302_43_dialog_content = "쳇... 지하성은 무사합니다... 기습을 당해서...\n좀 터진 곳이 몇 군데 있긴 합니다만...",
  ui_story_5083_50830302_44_dialog_content = "그래... 너흰 지하성을 지켜냈고, 심지어 암귀 부대를 전멸시켰다.\n덕분에 나머지 두 지하성은 기습을 받지 않았지... 너흰 승리했다.",
  ui_story_5083_50830302_45_dialog_content = "하지만 바튼... 네 첫 지휘의 교환비는 1 대 10에 근접했다...",
  ui_story_5083_50830302_46_dialog_content = "...<size=45>이 개같은 자식아!</size> 넌 네가 뭐라도 된 줄 알았냐?\n넌 그저 명령을 위반하고 영웅놀이에 빠진 놈일 뿐이야!",
  ui_story_5083_50830302_47_dialog_content = "네가 싸우다 뒈졌으면 그렇다 쳐도, 더그까지 죽게 만들 뻔했어!",
  ui_story_5083_50830302_48_dialog_content = "어쨌든 둘 다 살아 있잖습니까.",
  ui_story_5083_50830302_49_dialog_content = "내 말을 들었으면 이런 결과는 아니었을 거다!",
  ui_story_5083_50830302_50_dialog_content = "이번 건은 있는 그대로 기록해 주마. 네 이번 지휘는 실패다!",
  ui_story_5083_50830302_51_dialog_content = "예? 저희한테 불가능한 임무를 맡긴 건 군단장님입니다!\n제가 돌격해서 반격의 흐름을 만들지 않았다면, 방어선은 진작에 뚫렸을 거란 말입니다!",
  ui_story_5083_50830302_52_dialog_content = "군단장님! 가지 마시고 제대로 얘기 좀 하자고요! 잠깐만요! ...이런 망할!",
  ui_story_5083_50830302_53_dialog_content = "젠장... 여기 상황도 몰랐으면서 내 고과에 먹칠을 하겠다고...?\n누군 여기서 꼼짝도 못 하고 죽을 뻔했는데!",
  ui_story_5083_50830302_54_dialog_content = "성질부리지 마. 군단장님도 다 너 걱정해서 하신 얘기니까.",
  ui_story_5083_50830302_55_dialog_content = "네가 죽을 뻔했으니까 저렇게 화를 내셨던 거야.",
  ui_story_5083_50830302_56_dialog_content = "내가 먼저 온 것도 군단장님이 통신 두절을 확인하고 빨리 가서 도우라고 명령하신 덕분이라고.",
  ui_story_5083_50830302_57_dialog_content = "......",
  ui_story_5083_50830302_58_dialog_content = "자, 일어나. 이제 갈 시간이야...",
  ui_story_5083_50830302_59_dialog_content = "저희가... 이긴 건가요? ...이겼군요! 저... 살아남은 거네요...",
  ui_story_5083_50830302_60_dialog_content = "하지만... 부소대장님은...",
  ui_story_5083_50830302_61_dialog_content = "거의 다 죽어버렸다...",
  ui_story_5083_50830302_62_dialog_content = "온 부대의 전우들... 그리고 지원하러 온 녀석들까지...",
  ui_story_5083_50830302_63_dialog_content = "...일어서고 나니까 알겠어. 군단장님 목소리가 떨렸던 건...\n저 시체 더미 속에서 우릴 한참을 찾고 있으셨던 거야.",
  ui_story_5083_50830302_64_dialog_content = "더그... 내가 잘못한 거냐.",
  ui_story_5083_50830302_65_dialog_content = "너무 자책하지 마.",
  ui_story_5083_50830302_66_dialog_content = "놈들은 우리가 첫 정찰 때 파악한 것보다 수가 훨씬 많았어.",
  ui_story_5083_50830302_67_dialog_content = "어쨌든 넌 훌륭하게 임무를 완수했어.",
  ui_story_5083_50830302_68_dialog_content = "지하성을 지켜냈을 뿐만 아니라, 저 많은 수의 암귀를 처치했잖아.",
  ui_story_5083_50830302_69_dialog_content = "...너와 함께 싸운 모든 전우들이 영광을 가슴에 품고 목숨을 바친 거야.",
  ui_story_5083_50830302_70_dialog_content = "만약에... 내가 돌격하지 않았다면...",
  ui_story_5083_50830302_71_dialog_content = "지금보다 더 많이 살아남았을까.",
  ui_story_5083_50830302_72_dialog_content = "생각하지 마.",
  ui_story_5083_50830302_73_dialog_content = "바튼, 여긴 전장이야. 워게임이 아니라고. 그 무엇도 확신할 수 없어.",
  ui_story_5083_50830302_74_dialog_content = "아무리 뛰어난 지휘관도 앞으로의 전세가 전부 자기 명령대로 돌아갈 거라고 보장 못 해.",
  ui_story_5083_50830302_75_dialog_content = "게다가 지도나 사판에 우리 일루미나인의 두려움을 모르는 정신까지 담을 수 있는 건 아냐.",
  ui_story_5083_50830302_76_dialog_content = "반격으로 승리를 거둔 건 네 지휘를 통해 얻은 전공이야.",
  ui_story_5083_50830302_77_dialog_content = "「승리」라고...?",
  ui_story_5083_50830302_78_dialog_content = "어떻게 해야 더 나았을지, 더 많은 사람을 살렸을지...\n그런 건 아마 앞으로도 계속해서 생각하게 되겠지.",
  ui_story_5083_50830302_79_dialog_content = "어쩌면 다음엔 너도 다른 방법을 쓸지도 몰라.\n하지만 적어도 이번엔 이 결과를 받아들이는 수밖에 없어.",
  ui_story_5083_50830302_80_dialog_content = "그게 살아남은 우리가 반드시 짊어져야 할 의무야.",
  ui_story_5083_50830302_81_dialog_content = "결과를 받아들이고, 살아있는 모든 이들에게 승리를 선언하는 게...",
  ui_story_5083_50830302_82_dialog_content = "지휘관인 우리가 지금 할 수 있는 유일한 일인 거야.",
  ui_story_5083_50830400_1_dialog_content = "삐빅, 바튼 씨, 새로운 메시지가 도착했어요.",
  ui_story_5083_50830400_2_dialog_content = "다음 내용은 2군단장 팡고 님의 메시지입니다. 본 기계의 입장을 반영하지 않습니다──",
  ui_story_5083_50830400_3_dialog_content = "야, 너 이 자식 보나 마나 아직도 처자빠져 자고 있지? 어?!",
  ui_story_5083_50830400_4_dialog_content = "개인정비 날이라고 진짜로 늘어지게 돼 있냐?!",
  ui_story_5083_50830400_5_dialog_content = "빨리 생활 구역으로 가서 조사 임무를 수행해라!",
  ui_story_5083_50830400_6_dialog_content = "조사 내용은... 크흠, 생활 구역에서 물자를 밀매하는 놈이 있는지 찾아내!",
  ui_story_5083_50830400_7_dialog_content = "기한은 하루다. 못해도 상관없지만, 적어도 오늘 하루는 생활 구역에서 구르고,\n도중에 돌아오지 마라! 이상!",
  ui_story_5083_50830400_8_dialog_content = "좋았쓰!",
  ui_story_5083_50830400_9_dialog_content = "삐빅, 바튼 씨... 혼났는데 왜 기뻐하는 건가요?",
  ui_story_5083_50830400_10_dialog_content = "넌 모르겠지! 우린 평소에 생활 구역 위를 자주 지나다니지만,\n사실 군인들은 아무때나 생활 구역에 들어갈 수 있는 게 아니거든!",
  ui_story_5083_50830400_11_dialog_content = "매일마다 밑에 새 건물이 생기는 걸 보면서 늘 가 보고 싶었다고!",
  ui_story_5083_50830400_12_dialog_content = "삐빅, 바튼 씨, 절 흔들지 마세요...",
  ui_story_5083_50830400_13_dialog_content = "<size=45>아싸! 놀러 간다!</size>",
  ui_story_5083_50830400_14_dialog_content = "바튼! 오늘 때깔 좋은데? 생활 구역 간다면서?",
  ui_story_5083_50830400_15_dialog_content = "너네 뭐 갖고 싶은 거 있냐? 교환권 주면 배급부 가서 바꿔다 줄게.",
  ui_story_5083_50830400_16_dialog_content = "어어! 몰려오지 말고 줄 서! 교환권 찢어질라! 그리고 나 혼자 이걸 어떻게 다 바꿔오냐?!",
  ui_story_5083_50830400_17_dialog_content = "군단장님이 임무를 주신 모양이지? 근데 그거 그냥 핑계 삼아서 「휴가」 주신 거잖아.",
  ui_story_5083_50830400_18_dialog_content = "하? 그럴 리가, 설마 그 꼰대가 너처럼 배배 꼬였을라고.",
  ui_story_5083_50830400_19_dialog_content = "...휴가도 받았으면 상관 뒷담 까지 말고 얼른 꺼져!",
  ui_story_5083_50830400_20_dialog_content = "봐, 여기가 새로 생긴 배급 구역 거리야. 생활 구역에 접현한 보물 지대라고.",
  ui_story_5083_50830400_21_dialog_content = "삐빅, 바튼 씨... 「접현」이라는 단어 뜻을 잘못 알고 있는 것 같네요...\n그리고 같이 다니기 좀 창피해요.",
  ui_story_5083_50830400_22_dialog_content = "이 자식이 뭐라는 거야? 얼른 길 안내나 해. 쇼핑 시작이다!\n어디 주변에 재밌는 게 뭐가 있나 보자고!",
  ui_story_5083_50830400_23_dialog_content = "...임무는요?",
  ui_story_5083_50830400_24_dialog_content = "하, 더그가 그렇게 말했으면 맞는 거라고.",
  ui_story_5083_50830400_25_dialog_content = "그 자식은 어릴 때부터 꼰대 손에서 자랐으니까, 그 인간 생각은 누구보다 잘 알거든.",
  ui_story_5083_50830400_26_dialog_content = "아무튼 실컷 놀자고! 빨리 안내해!",
  ui_story_5083_50830400_27_dialog_content = "삐빅... 오른쪽 골목으로 들어가서 60m 직진하면 「비밀 게임센터」가 있어요.",
  ui_story_5083_50830400_28_dialog_content = "「게임」...? 배급 지역엔 그런 것까지 있는 건가? 지금은 전시인데...\n어떻게 된 건지 보러 가 보자고.",
  ui_story_5083_50830400_29_dialog_content = "이, 이건! 소문으로만 들었던 그 전설의 「전자오락」이잖아──!",
  ui_story_5083_50830400_30_dialog_content = "「비밀 게임센터」에 오신 것을 환영합니다. 전 여기 점원입니다.\n비록 전쟁 중이긴 하지만 그래도 휴가 중인 손님께서 즐거운 시간을 보내시길 바랍니다.",
  ui_story_5083_50830400_31_dialog_content = "가게의 게임은 모두 저희 「사장님」이 직접 제작한 겁니다.\n무료로 1번 체험해 보실 수 있습니다!",
  ui_story_5083_50830400_32_dialog_content = "만약 「해군왕」 체험 중 고득점에 성공하면 점수에 해당하는 경품을 드리겠습니다!",
  ui_story_5083_50830400_33_dialog_content = "중간에 실패해도 괜찮습니다.\n교환권을 동전으로 바꾸고 스테이지를 계속 진행하면 점수를 유지할 수 있으니까요!",
  ui_story_5083_50830400_34_dialog_content = "여기 사장 꽤 통이 크네! 그럼 이 몸이 노다이 클리어를 보여주지! 잘 보라고!",
  ui_story_5083_50830400_35_dialog_content = "「게임 종료, 점수는 5점입니다.」",
  ui_story_5083_50830400_36_dialog_content = "손님, 500점을 달성해야 「해군왕」 굿즈 티셔츠로 교환할 수 있고,\n1000점이면 이 게임기로 교환할 수 있는데요. 계속하시겠어요?",
  ui_story_5083_50830400_37_dialog_content = "계속해야지! 자, 교환권이다.",
  ui_story_5083_50830400_38_dialog_content = "잘 보라고──!",
  ui_story_5083_50830400_39_dialog_content = "「게임 종료, 점수는 40점입니다.」",
  ui_story_5083_50830400_40_dialog_content = "...어이, 그 「해군왕」 티셔츠, 그냥 사려면 교환권 몇 장 필요한데?",
  ui_story_5083_50830400_41_dialog_content = "하하... 고객님의 소비 금액은 이미 저희 가게 VIP 기준을 달성하셨습니다.\n교환권 100포인트만 받고 티셔츠를 드리도록 하죠. 어떠신가요?",
  ui_story_5083_50830400_42_dialog_content = "설마 바튼 군이 그런 티셔츠에 관심이 있을 줄은 몰랐네~",
  ui_story_5083_50830400_43_dialog_content = "네가 왜 여기 있냐?!",
  ui_story_5083_50830400_44_dialog_content = "여기 게임은 내가 개발한 거거든~ 드니에르랑 같이.",
  ui_story_5083_50830400_45_dialog_content = "거의 다 선배가 만든 거잖아. 난 게임엔 관심 없어.",
  ui_story_5083_50830400_46_dialog_content = "얘가 드니에르야. 내 후배.",
  ui_story_5083_50830400_47_dialog_content = "당신 알아, 바튼 맞지? 음... 나쁘지 않네.",
  ui_story_5083_50830400_48_dialog_content = "만나서 반가워... 어, 저기, 그로누. 네 게임기가 내 교환권을 많이 먹었는데 말이지...",
  ui_story_5083_50830400_49_dialog_content = "그중엔 전우들이 물건 사 달라고 맡긴 것도 있거든. 그래서 말인데...",
  ui_story_5083_50830400_50_dialog_content = "아하하! 나도 네가 그렇게 게임 허접일 줄은 몰랐지.\n그래도 내가 만든 게임이 마음에 들었나 보네. 고마워~",
  ui_story_5083_50830400_51_dialog_content = "역시 게임은 모두가 좋아할 수밖에 없다니까!",
  ui_story_5083_50830400_52_dialog_content = "그리고 여기서 테스트하길 잘했어. 경비도 회수하고 일석이조라구~",
  ui_story_5083_50830400_53_dialog_content = "...잠깐만, 너 설마 사적으로 가게를 연 거냐?",
  ui_story_5083_50830400_54_dialog_content = "그치만 원칙상 전부 무료로 플레이할 수 있는걸. 딱히 문제는 없지 않을까?",
  ui_story_5083_50830400_55_dialog_content = "문제가 없긴, 아주 많은데? 잡혀갈 때 내 이름 팔지나 마.",
  ui_story_5083_50830400_56_dialog_content = "기계 조립만 도와줬다고 할게!",
  ui_story_5083_50830400_57_dialog_content = "뭐야? 서, 선배가 「연구원장」 권한을 내세워서 일을 시킨 거였잖아!",
  ui_story_5083_50830400_58_dialog_content = "그치만 우리 드니에르도 즐거웠잖아?",
  ui_story_5083_50830400_59_dialog_content = "연구는... 확실히 즐겁긴 했지만.",
  ui_story_5083_50830400_60_dialog_content = "그치? 바튼 군도 관심 많지? 그럼 내 마음도 이해해 줄 수 있겠네?",
  ui_story_5083_50830400_61_dialog_content = "기계 만지는 건 확실히 재미있긴 한데...\n아무튼 교환권을 돌려주면 아무 일도 없었던 걸로 해 줄게.",
  ui_story_5083_50830400_62_dialog_content = "에이, 바튼 군 너무해. 좀 도와줄 수도 있는 거잖아.",
  ui_story_5083_50830400_63_dialog_content = "앞으로 내가 개발할 장비는 전부 너희 최전선 장병들을 위한 거라구.",
  ui_story_5083_50830400_64_dialog_content = "우릴 위해서...? 참, 이 드론 네 거야?",
  ui_story_5083_50830400_65_dialog_content = "어라? 얜 또 어디 갔어?",
  ui_story_5083_50830400_66_dialog_content = "무슨 드론?",
  ui_story_5083_50830400_67_dialog_content = "낡아빠진 드론인데, 자기가 「조종사」라고 하는 스마트 길 안내 드론이야.",
  ui_story_5083_50830400_68_dialog_content = "대화도 할 수 있고, 여기저기 안내도 해 줬다고.",
  ui_story_5083_50830400_69_dialog_content = "우와! 드니에르, 말만 들으면 엄청 최첨단 기술 같지 않아?",
  ui_story_5083_50830400_70_dialog_content = "응, 우리 일루미나엔 아직까지 그 정도의 첨단 스마트 드론은 없어.\n게다가 「낡아빠진」 드론이라니...",
  ui_story_5083_50830400_71_dialog_content = "뭐? 난 분명히 네가 만든 줄 알았는데... 그나저나 어딜 간 거야?\n뭐, 아무튼 길 안내 드론이니까 지가 길을 잃진 않겠지.",
  ui_story_5083_50830400_72_dialog_content = "다음에 기회 되면 나한테 좀 보여줘.",
  ui_story_5083_50830400_73_dialog_content = "나도 보고 싶어. 난... 「강한 미래」에 관심이 있거든.",
  ui_story_5083_50830400_74_dialog_content = "자, 교환권 돌려줄게, 바튼 군. 대신 오락실 비밀 지켜주는 거 잊지 말구.",
  ui_story_5083_50830400_75_dialog_content = "고맙다! 아, 그래. 어렵게 여기까지 왔고 일찍 돌아갈 생각도 없으니까,\n이참에 내가 밥 한 끼 산다. 어때?",
  ui_story_5083_50830400_76_dialog_content = "아싸! 바튼 군 최고!",
  ui_story_5083_50830400_77_dialog_content = "나도 연구원 식당 밥은 지겨웠거든... 고마워, 맛있으면 「언니」한테도 추천해 줘야지.",
  ui_story_5083_50830400_78_dialog_content = "아참, 바튼 군은 모를 수도 있겠네? 얘 언니가 바로 라인하르트야.",
  ui_story_5083_50830400_79_dialog_content = "어색하게 그런 얘긴 왜 하고 그래.",
  ui_story_5083_50830400_80_dialog_content = "전혀 몰랐어. 너네 언니는 막 번쩍번쩍해서 엄청 눈에 띄는 타입이잖아.",
  ui_story_5083_50830400_81_dialog_content = "...꼭 따라잡을 거야.",
  ui_story_5083_50830400_82_dialog_content = "그래? 뭐, 근데 난 지금 너도 나쁘지 않아 보이는데. 됐고, 밥이나 먹으러 가자.",
  ui_story_5083_50830400_83_dialog_content = "맛있어... 추천해 줘도 되겠어.",
  ui_story_5083_50830400_84_dialog_content = "으음... 아무리 봐도 너네 자매는 참 다르단 말이지.",
  ui_story_5083_50830400_85_dialog_content = "바튼 군은 라인하르트의 대단한 점은 이미 봤겠지만, 드니에르에 대해선 아직 잘 모르잖아?",
  ui_story_5083_50830400_86_dialog_content = "그러고 보니까 너 워게임 좋아하지 않았어? 우리 후배님이랑 한번 붙어볼래?",
  ui_story_5083_50830400_87_dialog_content = "뭐? 내가 다른 건 그냥 넘어가려고 했는데, 연구원이 나랑 전술로 겨루겠다고?\n재미있겠네. 어디 해 보자고!",
  ui_story_5083_50830400_88_dialog_content = "그로누 선배... 진짜 일 벌리는 재주가 있다니까.\n뭐, 좋아, 바튼 소위, 한 수 배워볼게. 대신 날 무시하진 않는 게 좋을 거야.",
  ui_story_5083_50830400_89_dialog_content = "<color=#e8d9bb>그로누의 비밀 가게로 돌아가자, 바튼과 드니에르는 사판 위에서 모의 전쟁을 시작했다.</color>",
  ui_story_5083_50830400_90_dialog_content = "<color=#e8d9bb>그리고 바튼의 예상은 크게 빗나갔다.\n사판 위의 연구원 드니에르는 바튼보다도 더 흉악한 야심을 드러낸 것이었다.</color>",
  ui_story_5083_50830400_91_dialog_content = "<color=#e8d9bb>드니에르는 손안의 말을 버려가면서까지 적진 깊숙이 파고들었다.\n그것은 바튼에겐 생각지도 못한 전술이었고, 깨달았을 때는 이미 패배 직전이었다.</color>",
  ui_story_5083_50830400_92_dialog_content = "(젠장, 이미 그로누한테도 졌는데, 쟤 친구한테까지 질 순 없잖아!)",
  ui_story_5083_50830400_93_dialog_content = "<color=#e8d9bb>얼굴이 새빨개진 바튼은 갑자기 말을 세게 내려놓기 시작했고,\n그 힘에 드니에르 쪽 보드가 엉망이 되었다.</color>",
  ui_story_5083_50830400_94_dialog_content = "<color=#e8d9bb>무너진 사판 앞에서 드니에르는 속수무책이었고, 바튼은 그사이에 공격을 가했다.</color>",
  ui_story_5083_50830400_95_dialog_content = "바튼 군, 너무 비겁해... 드니에르가 울 것 같잖아...",
  ui_story_5083_50830400_96_dialog_content = "전쟁에 비겁하고 말고가 어디 있냐! 이건 내 상관이 가르쳐 준 거다.\n무슨 수를 써서라도 이기라고!",
  ui_story_5083_50830400_97_dialog_content = "<color=#e8d9bb>말은 그렇게 했지만 이미 벌어진 격차는 메우기 힘들었다.\n말을 치우는 드니에르는 조금 곤혹스러워 보였지만, 전개는 오히려 침착했다.</color>",
  ui_story_5083_50830400_98_dialog_content = "<color=#e8d9bb>양동, 포위... 물량공세, 공멸 작전을 거듭한 끝에... 드니에르는 승리를 거두었다.</color>",
  ui_story_5083_50830400_99_dialog_content = "아하하! 바튼 군! 승부에서도 지고, 품위에서도 졌잖아?",
  ui_story_5083_50830400_100_dialog_content = "엄연한 일루미나군 소위가 그렇게 비겁할 줄은 몰랐어. 두고 봐...",
  ui_story_5083_50830400_101_dialog_content = "으윽... 잠깐만! 너희들! 괜히 엉뚱한 데 가서 말하지 마! 부탁이야!",
  ui_story_5083_50830400_102_dialog_content = "남들이 알기라도 했다간 개망신이라고! <size=45>부탁할게! 뭐든지 할 테니까!</size>",
  ui_story_5083_50830500_1_dialog_content = "<color=#e8d9bb>조금 침울해진 바튼이 크고 작은 짐을 든 채 병영 앞에 나타났다.\n그리고 이 순간, 「나」는 반드시 그에게 경고할 수밖에 없었다.</color>",
  ui_story_5083_50830500_2_dialog_content = "어? 너 어디 갔었냐...? 하루 종일 안 보이더니.",
  ui_story_5083_50830500_3_dialog_content = "삐빅, 바튼 씨, 위험해요──",
  ui_story_5083_50830500_4_dialog_content = "뭐? 여긴 우리 부대인데 뭐가... 어?",
  ui_story_5083_50830500_5_dialog_content = "<color=#e8d9bb>제2군단 훈련장 중앙, 그곳에는 창도끼를 든 라인하르트가 서 있었다.\n그녀는 이미 오랫동안 그가 돌아오기를 기다리고 있었다.</color>",
  ui_story_5083_50830500_6_dialog_content = "저 녀석, 살기가 장난이 아니잖아. 누가 시비라도 걸었나?",
  ui_story_5083_50830500_7_dialog_content = "......",
  ui_story_5083_50830500_8_dialog_content = "<size=45>바튼──!</size>",
  ui_story_5083_50830500_9_dialog_content = "감히 내 동생한테 비겁한 수를 써? 각오해라!",
  ui_story_5083_50830500_10_dialog_content = "걔 뭐 애기야?! 뭐 그런 것까지 자기 언니한테 고자질하냐고!",
  ui_story_5083_50830500_11_dialog_content = "삐빅! 바튼 씨, 제안합니다... 도망치세요.",
  ui_story_5083_50830500_12_dialog_content = "어이! 다들 자기 물건 알아서 챙겨! 나 간다!",
  ui_story_5083_50830500_13_dialog_content = "겁쟁이 녀석! 거기 서라!",
  ui_story_5083_50830500_14_dialog_content = "<color=#e8d9bb>라인하르트는 타오르는 창도끼를 휘둘러 어둠을 갈랐고, 바튼을 따라 돌진했다.</color>",
  ui_story_5083_50830500_15_dialog_content = "어이! 그쯤 하면 됐잖아! 계속 그러면 나도 가만히 안 있을 거라고!",
  ui_story_5083_50830500_16_dialog_content = "얼마든지 와 봐. 내 동생을 괴롭히고, 이젠 나한테도 덤빌 생각이야?",
  ui_story_5083_50830500_17_dialog_content = "창 휘두르면서 말하지 마!",
  ui_story_5083_50830500_18_dialog_content = "<color=#e8d9bb>바튼은 이리저리 도망쳤고, 라인하르트는 뒤에서 바짝 뒤쫓았다.\n두 사람은 거의 세 블록을 달렸다──</color>",
  ui_story_5083_50830500_19_dialog_content = "더는 못 참아! 받아라!",
  ui_story_5083_50830500_20_dialog_content = "...모래? 비겁하다!",
  ui_story_5083_50830500_21_dialog_content = "이기면 그만이지! 으랴앗!",
  ui_story_5083_50830500_22_dialog_content = "「<color=#FFB400>관통의 별</color>」!",
  ui_story_5083_50830500_23_dialog_content = "<color=#e8d9bb>두 사람은 거리에서 서로 주먹과 발길질을 주고받았고, 경보가 울렸다.\n병사들이 하나둘씩 모여들었지만, 아무도 이 싸움의 영문을 모르는 반응이었다.</color>",
  ui_story_5083_50830500_24_dialog_content = "받아라! 「파이프 검법」이다!",
  ui_story_5083_50830500_25_dialog_content = "걷어차 주겠어!",
  ui_story_5083_50830500_26_dialog_content = "하하하! 좋아! 더 해 보라고!",
  ui_story_5083_50830500_27_dialog_content = "<size=45>이런 망나니 새끼들!</size>",
  ui_story_5083_50830500_28_dialog_content = "장교들끼리 주먹다짐이라니, 어이가 없어서 웃음이 나올 지경이군...\n아주 힘이 남아돈다 이거냐? 좋아! 구보 100바퀴 실시! 당장 훈련장으로 꺼져!",
  ui_story_5083_50830500_29_dialog_content = "후... 다 너 때문이야. 나까지 뛰게 됐잖아.",
  ui_story_5083_50830500_30_dialog_content = "그러게 누가 후배를 괴롭히래?",
  ui_story_5083_50830500_31_dialog_content = "네 동생 전술도 나보다 뭐 떳떳할 것도 없었는데 말이야...\n너 그렇게 편들어주면 걔 버릇 나빠질 거다.",
  ui_story_5083_50830500_32_dialog_content = "이 얼간이들아! 누가 얘기하면서 뛰어도 된다고 했나! 더 빠르게!",
  ui_story_5083_50830500_33_dialog_content = "100바퀴를 다 뛰고도 서 있을 수 있으면 그땐 니들 마음대로 싸우든지 알아서 해라!",
  ui_story_5083_50830500_34_dialog_content = "휴우, 후...",
  ui_story_5083_50830500_35_dialog_content = "어이, 진심이냐? 갑자기 죽어라 뛰기는... 흥, 덕분에 나도 의욕이 생겼어! 간다!",
  ui_story_5083_50830500_36_dialog_content = "끝나고 다리나 풀리지 마! 뭐, 풀려도 봐줄 생각은 없지만 말이야.",
  ui_story_5083_50830500_37_dialog_content = "<color=#e8d9bb>두 젊은이는 힘차게 한 바퀴, 또 한 바퀴를 달렸다.\n그러나 시간이 지날수록 두 사람의 발걸음도 서서히 힘을 잃어갔다.</color>",
  ui_story_5083_50830500_38_dialog_content = "나쁘지 않네, 따라올 수 있을 줄이야... 계속해!",
  ui_story_5083_50830500_39_dialog_content = "<color=#e8d9bb>60바퀴, 70바퀴... 두 사람의 다리는 마치 납처럼 무거워졌고,\n페이스가 흐트러지면서 속도도 떨어지기 시작했다.</color>",
  ui_story_5083_50830500_40_dialog_content = "군단장님, 처벌이 조금 과한 거 아닙니까...?",
  ui_story_5083_50830500_41_dialog_content = "쓸데없는 소리, 밖에서는 놈들이 부린 난동을 지금도 수습하고 있단 말이다!",
  ui_story_5083_50830500_42_dialog_content = "지들이 잘났다고 생각하면서 서로 싸우기까지 하는 놈들은 쓴맛도 좀 볼 필요가 있는 거다.",
  ui_story_5083_50830500_43_dialog_content = "<color=#e8d9bb>80바퀴, 90바퀴... 훈련장을 달리는 두 사람의 모습은 금방이라도 쓰러질 듯 휘청거렸지만,\n지금은 오히려 서로를 부축하며 계속해서 달리고 있었다.</color>",
  ui_story_5083_50830500_44_dialog_content = "야... 아직 힘이 남았어?",
  ui_story_5083_50830500_45_dialog_content = "...그걸 말이라고, 네 창도끼 공격을... 어떻게 상대할지도... 이미 생각해 뒀다고.",
  ui_story_5083_50830500_46_dialog_content = "<color=#e8d9bb>99바퀴, 100바퀴── 서로 부축한 두 사람의 귓가에는 마침내 호각 소리가 들렸고,\n두 사람은 약속이라도 한 듯이 그대로 쓰러졌다.</color>",
  ui_story_5083_50830500_47_dialog_content = "...야... 안 죽었지?",
  ui_story_5083_50830500_48_dialog_content = "숨... 돌리고... 있다!",
  ui_story_5083_50830500_49_dialog_content = "더... 할 거냐? 언제든지... 일어설... 수 있다고...",
  ui_story_5083_50830500_50_dialog_content = "흥... 못 일어난다면... 이번엔... 봐줄 테니까 그런 줄 알아...\n다음엔... 어떤 대결이든... 받아줄 테니까...",
  ui_story_5083_50830500_51_dialog_content = "호오...? 아, 하하하... 콜록콜록...",
  ui_story_5083_50830500_52_dialog_content = "<color=#e8d9bb>라인하르트는 호쾌하게 웃기 시작했지만, 얼마 안 가 목이 막히고 말았다.\n그래도 라인하르트는 끝까지 일어섰고, 자신의 상대에게 손을 내밀었다.</color>",
  ui_story_5083_50830500_53_dialog_content = "콜록콜록... 인정하겠어. 넌 좋은 상대였어.",
  ui_story_5083_50830500_54_dialog_content = "너희 군단장님 말이 맞아. 우린 일루미나인이야. 경쟁할 순 있어도, 내분은 없어야 해.",
  ui_story_5083_50830500_55_dialog_content = "일루미나의 예법대로, 악수로 화해하자.",
  ui_story_5083_50830500_56_dialog_content = "넌 내가 필요한 걸 가지고 있어. 훗날 언젠가 내가 네 손을 빌리게 될 거야.",
  ui_story_5083_50830500_57_dialog_content = "너 말이야... 신참 주제에 생각보다 더 잘난 척이 심하네.",
  ui_story_5083_50830500_58_dialog_content = "뭐, 말해줘도 괜찮겠지. 지금 내 작은 목표는 「대원수」가 되는 거야.",
  ui_story_5083_50830500_59_dialog_content = "「작은 목표」라고? 거 재미있네...",
  ui_story_5083_50830500_60_dialog_content = "좋아, 믿어줄게! 넌 내가 상상한 것보다 더 빛나는 녀석이야.\n그런 기세는 꾸며낼 수 있는 게 아니거든.",
  ui_story_5083_50830500_61_dialog_content = "아무튼 오늘은 비긴 거니까 우쭐대지 마라. 앞으로도 우린 계속 경쟁하게 될 테니까.",
  ui_story_5083_50830500_62_dialog_content = "「잘 부탁해」.",
  ui_story_5083_50830500_63_dialog_content = "저 녀석 눈빛, 농담이 아니었어. 상관들보다도 더 강하게 빛나고 있잖아.",
  ui_story_5083_50830500_64_dialog_content = "흥, 미래의 일루미나는 우리 세대가 맡게 되는 건가... 꽤 재미있겠어!",
  ui_story_5083_50830500_65_dialog_content = "어이, 바튼! 뭘 혼자 중얼대고 있어? 빨리 와!",
  ui_story_5083_50830500_66_dialog_content = "지난번 전투에서 빠진 인원이 이제야 겨우 다 찼어. 관례대로 단체 사진을 찍어야지.",
  ui_story_5083_50830500_67_dialog_content = "너 오면 찍는다고 군단장님도 특별히 기다리셨는데... 너네가 싸우고 있을 줄 누가 알았겠냐고.\n빨리 와, 다들 한참 기다렸어.",
  ui_story_5083_50830500_68_dialog_content = "사진이라... 알겠어!",
  ui_story_5083_50830500_69_dialog_content = "이쪽으로 오십시오! 군단장님 옆에 자리를 비워 뒀습니다!",
  ui_story_5083_50830500_70_dialog_content = "고맙다!",
  ui_story_5083_50830500_71_dialog_content = "흥, 아직 걸을 수 있는 걸 보면 평소 훈련이 헛수고는 아니었군.",
  ui_story_5083_50830500_72_dialog_content = "전 아직 젊잖습니까. 군단장님처럼 늙은 몸이랑 같아서야 되겠습니까?",
  ui_story_5083_50830500_73_dialog_content = "서로 좋은 말로 하면 참 좋을 텐데... 군단장님, 다 모였습니다.",
  ui_story_5083_50830500_74_dialog_content = "흥!",
  ui_story_5083_50830500_75_dialog_content = "흥!",
  ui_story_5083_50830500_76_dialog_content = "...2군단의 전사들이여, 오늘 이렇게 모인 걸 기쁘게 생각한다.\n그리고 축하한다. 너흰 이 「망할 꼰대」의 훈련을 견뎌냈다!",
  ui_story_5083_50830500_77_dialog_content = "너흰 이제 잘 「연마」된 탄환이 되었다.\n앞으로 너흴 기다리고 있는 건 나보다도 수백 배는 더 악랄한 암귀다!",
  ui_story_5083_50830500_78_dialog_content = "그러나 우리는 결코 타협하거나 물러서지 않는다!\n촬영이 끝나면 전원 일찍 취침하고, 내일부터 3일간 휴가다!",
  ui_story_5083_50830500_79_dialog_content = "감사합니다! 군단장님!",
  ui_story_5083_50830500_80_dialog_content = "벌써부터 좋아하긴 이르다! 앞으로는 편해질 거라 생각하면 오산이다.\n제군들이 승리해서 돌아올 때까지, 나는 계속해서 제군들을 「연마」할 것이다! 이상!",
  ui_story_5083_50830500_81_dialog_content = "자자, 다들 웃으면서── 여명의 빛을 위하여!",
  ui_story_5083_50830500_82_dialog_content = "<size=45>여명의 빛을 위하여!</size>",
  ui_story_5083_50830600_1_dialog_content = "휴가라고 해서 네가 늘어지는 꼴을 봐 줄 것 같으냐!",
  ui_story_5083_50830600_2_dialog_content = "사격 훈련 열심히 하겠습니다!",
  ui_story_5083_50830600_3_dialog_content = "눈앞의 암귀를 쏘아 죽이면, 놈은 널 향해 쓰러질 거다.\n하지만 그때 뒤에서 다른 암귀가 달려든다면, 사격 각도를 어떻게 확보할 셈이지?",
  ui_story_5083_50830600_4_dialog_content = "아무리 총이 많아도, 결국엔 암귀한테 막힐 수 있다. 따라서 넌 검술을 더 익혀야 한다!",
  ui_story_5083_50830600_5_dialog_content = "냉병기는 결코 널 배신하지 않는다!\n그것만 잘 기억하고, 칼만 제때 뽑을 수 있다면, 넌 언제라도 위험에 처할 일은 없을 거다!",
  ui_story_5083_50830600_6_dialog_content = "......",
  ui_story_5083_50830600_7_dialog_content = "일루미나인은 죽음을 두려워하지 않는다!\n우린 아스트라를 구한다는 대의를 위해 「방어선」이 되었다.\n다만 결코 헛되이 죽어서는 안 된다!",
  ui_story_5083_50830600_8_dialog_content = "전장에서는 자신의 목숨부터 소중히 여겨야 한다. 알겠나!",
  ui_story_5083_50830600_9_dialog_content = "예, 군단장님!",
  ui_story_5083_50830600_10_dialog_content = "잘 쉬어라. 요 며칠처럼 얼빠지게 있지 말고!",
  ui_story_5083_50830600_11_dialog_content = "...게다가 우리 2군단 베테랑이 1군단 신참 하나 못 이겨서야 되겠냐?",
  ui_story_5083_50830600_12_dialog_content = "명심하겠습니다, 군단장님!",
  ui_story_5083_50830600_13_dialog_content = "더그 녀석 말이 맞았어. 저 꼰대, 역시 배배 꼬였다니까.",
  ui_story_5083_50830600_14_dialog_content = "다 큰 어른이 말을 꼭 저렇게 돌려서 해야 되냐고...\n속으론 그냥 내가 라인하르트 녀석을 제대로 밟아주길 바라는 거잖아.",
  ui_story_5083_50830600_15_dialog_content = "삐빅, 바튼 씨, 제가 보기엔 그런 뜻이 아닌 것 같은데요.",
  ui_story_5083_50830600_16_dialog_content = "하하! 너 기계 주제에 부끄럼도 많네. 남이 올 때마다 숨고 말이야.\n너 설마 내 전속 안내원이냐?",
  ui_story_5083_50830600_17_dialog_content = "...길 안내가 필요하신가요?",
  ui_story_5083_50830600_18_dialog_content = "아니, 오늘은 내가 알아서 갈 곳이 있거든. 따라와.",
  ui_story_5083_50830600_19_dialog_content = "삐빅, 바튼 씨는 휴가 때 박물관에 오시나요?",
  ui_story_5083_50830600_20_dialog_content = "군인이란 그런 거야. 전투도, 훈련도 없으면 뭘 할 수 있겠냐고.\n어차피 갑갑한 지하에 박혀 있는데, 어딜 가나 그게 그거지.",
  ui_story_5083_50830600_21_dialog_content = "...뭐, 집에 그로누가 만든 게임기라도 하나 있으면 좋겠지만 말이야.",
  ui_story_5083_50830600_22_dialog_content = "만약 정말로 평화가 찾아온다면, 게임을 평생 할 수도 있을 것 같아.",
  ui_story_5083_50830600_23_dialog_content = "바다를 탐색하는 해군도 만들고 싶고.",
  ui_story_5083_50830600_24_dialog_content = "하하... <color=#FFB400>평화</color>라... 상상 정도는 할 수 있겠지.",
  ui_story_5083_50830600_25_dialog_content = "...삐빅, 일루미나 박물관 해설 모드로 전환합니다.",
  ui_story_5083_50830600_26_dialog_content = "<color=#FFB400>80호 지하성</color>은 한때 영원한 밤의 땅 방위선에 가장 가까운 곳이었습니다.",
  ui_story_5083_50830600_27_dialog_content = "「그림자 전투」 때, 그 지하성은 물자 수송에 매우 큰 역할을 했습니다.",
  ui_story_5083_50830600_28_dialog_content = "꼰대도 그랬었지...\n그 지하성은 도살장 그 자체였고, 2군단은 거기서 거의 궤멸할 뻔했다고 말이야.",
  ui_story_5083_50830600_29_dialog_content = "우리 일루미나인은 어릴 때부터 박물관에 와서 교육을 받는다.\n그때 난 이곳의 전설적인 영웅들을 동경했지... 정말 멋있는 사람들이거든.",
  ui_story_5083_50830600_30_dialog_content = "하지만 이젠 저 「전설」들의 뒤에 얼마나 많은 희생이 있었는지 알고 있어...\n그래서 난 더는 누군가가 희생되는 건 보고 싶지 않아.",
  ui_story_5083_50830600_31_dialog_content = "다음은... 지금도 계속되고 있는 「어둠의 위기」의 시작이라고 여겨지는 사건입니다.\n2년 전 「헤븐즈 밸리」가 습격당했고... 아이테르 일족은 모두...",
  ui_story_5083_50830600_32_dialog_content = "...왜 그래? 갑자기 말이 없어지고...",
  ui_story_5083_50830600_33_dialog_content = "어이, 바튼.",
  ui_story_5083_50830600_34_dialog_content = "너 여기서 뭐 하는 거야?",
  ui_story_5083_50830600_35_dialog_content = "물론 역사 공부 중이지. 전쟁의 역사와 일루미나의 역사 말이야.",
  ui_story_5083_50830600_36_dialog_content = "...바튼. 넌 일루미나의 미래가 어떨 거라 생각해?",
  ui_story_5083_50830600_37_dialog_content = "뭐야? 갑자기 그런 걸 다 묻고...",
  ui_story_5083_50830600_38_dialog_content = "「신비한 아이테르」는 한 번의 습격에 멸망해 버렸고,\n지금의 오로리안들은 다시는 「안내자」가 없게 돼버렸지...",
  ui_story_5083_50830600_39_dialog_content = "하지만 <color=#FFB400>어둠의 위기</color>는 계속되고, 희생되는 전사는 늘어만 가고 있어 ...\n봐, 이 창문 너머로 기념비가 보이지?",
  ui_story_5083_50830600_40_dialog_content = "죽어간 전우들의 이름은 모두 기념비에 새겨졌어...\n하지만 저들의 목소리는 아직도 내 머릿속에 울려 퍼지고 있어.",
  ui_story_5083_50830600_41_dialog_content = "우린 어릴 때부터 여기서 역사를 배웠어...\n하지만 어른이 될수록 여기 적힌 것들이 점차 현실로 다가오고 있어.",
  ui_story_5083_50830600_42_dialog_content = "주변 사람들은 영광을 가슴에 품고 전사하고, 후배들이 반드시 배워야 할 역사가 되지...\n바튼, 난 이제 잘 모르겠어.",
  ui_story_5083_50830600_43_dialog_content = "모르겠다고?",
  ui_story_5083_50830600_44_dialog_content = "이토록 혼란스러운 아스트라를 위해 난 목숨을 바쳐야 해.\n하지만 그런데도 미래가 보이질 않아...",
  ui_story_5083_50830600_45_dialog_content = "그거 알아? 백야성은 지금도 내분 중이야.\n약속했던 협력은 아직도 실현되지 않았고, 물자 왕래도 멈췄어.",
  ui_story_5083_50830600_46_dialog_content = "온 아스트라 대륙이 혼란에 빠져 있고, 난 우리가 뭘 위해서 싸우고 있는 건지...\n이길 수는 있는 건지도 잘 모르겠어.",
  ui_story_5083_50830600_47_dialog_content = "너... 무서운 거냐?",
  ui_story_5083_50830600_48_dialog_content = "당연히 무섭지... 우리가 동포들의 시체 사이에서 일어설 수 있었던 건 순전히 운이었으니까.",
  ui_story_5083_50830600_49_dialog_content = "네가 그랬었지. 그건 살아남은 우리가 반드시 짊어져야 할 의무라고...\n난 이미 노력해서 적응하고 있어...",
  ui_story_5083_50830600_50_dialog_content = "위원회가 대원수님을 방해하고 있다는 거 알고 있어?\n저들은 지금까지도 전쟁을 계속할지 말아야할지 결정하지 못하고 있어.",
  ui_story_5083_50830600_51_dialog_content = "「그림자 전투」를 겪고 돌아온 사람들은 어쩌면 나보다 더 두려워하고 있을지도 몰라.",
  ui_story_5083_50830600_52_dialog_content = "지금 일루미나라는 큰 배엔 한 사람이라도 길을 제대로 볼 미래의 「조타수」가 없어.\n바튼, 넌 그런데도 안 무서운 거냐?",
  ui_story_5083_50830600_53_dialog_content = "그럼 내가 「조타수」가 되면 되잖아.",
  ui_story_5083_50830600_54_dialog_content = "너도 있고! 나도 있고! 그리고 제1군단의 그 신참, 「라인하르트」도 있고 말이야!",
  ui_story_5083_50830600_55_dialog_content = "설마 우린 말할 자격도 없는 거냐?",
  ui_story_5083_50830600_56_dialog_content = "미래를 이야기하면서 왜 우릴 빼놓는 건데? 그 미래에 맞서는 건 우리 같은 새로운 세대라고!",
  ui_story_5083_50830600_57_dialog_content = "남들이 뭐라 생각하든 난 절대 물러서지 않아.\n절대로 이 배가 암초 지대에서 가라앉게 만들진 않겠어!",
  ui_story_5083_50830600_58_dialog_content = "흥, 어떻게 해야 할지 잘 모르겠으면 네 목숨을 나한테 맡겨. 내가 이끌어 줄 테니까!",
  ui_story_5083_50830600_59_dialog_content = "네가...? 조타수? 맥주병 자식이 말은 잘도 하네.",
  ui_story_5083_50830600_60_dialog_content = "휴... 그래... 너조차도 그렇게 자신만만한데, 난 왜 혼자 고민하고 있는 거냐.",
  ui_story_5083_50830600_61_dialog_content = "바튼, 나도 「일루미나의 아이」야. 누가 미래의 「조타수」가 될지는 아직 모르는 거라고.",
  ui_story_5083_50830600_62_dialog_content = "그럼 나도 군단장님께 증명해 드리겠어. 나야말로 그분이 기대하는 신예라는 걸 말이야!",
  ui_story_5083_50830600_63_dialog_content = "그러든지 말든지, 어차피 난 꼰대한테 잘 보이려고 노력하진 않을 테니까.",
  ui_story_5083_50830600_64_dialog_content = "사실은 여기 오기 전에 신청서를 내고 왔어. 2군단에 「특별 돌격대」를 만들자고 말이야.",
  ui_story_5083_50830600_65_dialog_content = "지난번 싸움에서 깨달았어. 우리의 수비 일변도 전술은 암귀를 상대로 너무 뒤처졌어.",
  ui_story_5083_50830600_66_dialog_content = "그래서 <color=#FFB400>돌격대대</color>를 창설해서 적진 돌파에 특화된 훈련을 하자는 게 내 생각이야.\n이건 앞으로의 전투에 매우 중요한 역할을 하게 될 거야.",
  ui_story_5083_50830600_67_dialog_content = "백야성이 진심으로 우리와 협력할 생각이 있었다면,\n기마전 훈련도 할 수 있었을 텐데... 아쉽네.",
  ui_story_5083_50830600_68_dialog_content = "아마 미래엔 기갑부대가 승패를 결정짓는 관건이 되겠지...\n하지만 그렇다고 보병의 중요성을 간과할 순 없어.",
  ui_story_5083_50830600_69_dialog_content = "아직 기계 생산력이 충분하지 못한 지금은 더 그렇고 말이야.\n우린 길을 열고 공격을 저지하는 「날카로운 칼날」이 돼야 해.",
  ui_story_5083_50830600_70_dialog_content = "너 그 구상... 꽤 대단하네. 난 아직까지 그런 생각은 못 해 봤는데.",
  ui_story_5083_50830600_71_dialog_content = "더그, 넌 충분히 대단한데, 왜 그렇게 꼰대의 인정을 받으려고 하는 거야?\n왜 그렇게 애써 자기 「가치」를 증명하려고 안달이냔 말이야.",
  ui_story_5083_50830600_72_dialog_content = "그분은 우리 상관이고, 심혈을 다해서 우릴 훈련시켜 주시는 분이야. 이유는 그걸로 충분하잖아?",
  ui_story_5083_50830600_73_dialog_content = "그게 다가 아니겠지.",
  ui_story_5083_50830600_74_dialog_content = "바튼... 넌 「뇌까지 근육」인 녀석이지만, 직감은 오히려 날카롭단 말이지.",
  ui_story_5083_50830600_75_dialog_content = "...우리 아버지는 군단장님의 동료였어. 그래서 날 군단장님한테 맡겼고.",
  ui_story_5083_50830600_76_dialog_content = "군단장님은 날 길러 주셨고, 줄곧 돌봐주셨어. 나한테 군단장님은 「아버지」나 마찬가지야.",
  ui_story_5083_50830600_77_dialog_content = "군단장님의 아들은 내 「형」이고, 아내분은 내 「어머니」였지.",
  ui_story_5083_50830600_78_dialog_content = "뭐? 그 꼰대도 가정이 있었다고...? 무슨 일이 있었던 거야...?",
  ui_story_5083_50830600_79_dialog_content = "6년 전, 우리가 살던 지하성에 암귀가 침입했어.",
  ui_story_5083_50830600_80_dialog_content = "하지만 군단장님은 맡은 직무 때문에 전선에서 물러나지 않고 계속 자리를 지켰지.",
  ui_story_5083_50830600_81_dialog_content = "그때... 나랑 다른 비전투인원들을 대피시키기 위해 아내분과 아드님이 자신을 희생했어.",
  ui_story_5083_50830600_82_dialog_content = "군단장님은 아무 말씀도 안 하셨지만, 그 뒤로 곧바로 전출을 요청하셨어.\n그 뒤로 다시는 지하성 수비 지휘를 맡지 않게 되셨지.",
  ui_story_5083_50830600_83_dialog_content = "...분명히 무척 고통스럽고, 자책하셨을 거야.",
  ui_story_5083_50830600_84_dialog_content = "꼰대가 지하성이나 주둔지에 가만히 눌러앉질 못하는 게 그래서였어...?",
  ui_story_5083_50830600_85_dialog_content = "아무튼 그건 군단장님 잘못이 아니었어. 난 그저 이 말씀을 드리고 싶을 뿐이야.",
  ui_story_5083_50830600_86_dialog_content = "나도 이제 곧 「형」이랑 같은 나이가 돼... 그러니까 군단장님한테 알려드리고 싶어.\n여기 살아있는 아들이 또 있다고.",
  ui_story_5083_50830600_87_dialog_content = "하지만 내가 아무리 노력해도 군단장님은... 늘 너만 보셨어.",
  ui_story_5083_50830600_88_dialog_content = "가끔은 네가 정말 부러워, 바튼. 이건 내가 약한 탓일까?",
  ui_story_5083_50830600_89_dialog_content = "난... 어떻게든 「형」을 대신해서 군단장님의 「상처」를 치유해 드리고 싶어.",
  ui_story_5083_50830600_90_dialog_content = "근데 넌 그냥 너잖아... 더그, 네가 이렇게 변할 줄은 정말 몰랐어.",
  ui_story_5083_50830600_91_dialog_content = "너처럼 못난 놈은 아스트라 어디에도 없을 거다. 더그, 넌 남의 그림자가 아냐!",
  ui_story_5083_50830600_92_dialog_content = "꼰대도 분명히 같은 생각일 거라고. 그러니까 너한테 늘 그렇게 정색하는 거겠지.",
  ui_story_5083_50830600_93_dialog_content = "네가 그러니까 이제야 이해가 되네. 그 인간 진짜 배배 꼬인 게 맞아.\n그냥 너한테 차마 말을 못 하는 거라니까?",
  ui_story_5083_50830600_94_dialog_content = "너도 방금 그랬잖아. 너도 <color=#FFB400>아들</color>이라며.\n근데 어느 부모가 지 자식이 다른 자식의 대용품이 되는 걸 원하겠냐고.",
  ui_story_5083_50830600_95_dialog_content = "...바튼... 너...",
  ui_story_5083_50830600_96_dialog_content = "하...하하하하! 진짜 놀랐잖아. 너 진짜로 뇌가 싹 다 근육인 건 아니었구나?",
  ui_story_5083_50830600_97_dialog_content = "네가 그런 말을 하니까 진짜 이상하다니까? 너 같지가 않아.\n그래도 나한테 설교는 좀 아니지 않아? 어제까지만 해도 그렇게 걱정을 끼쳐놓고 말이야.",
  ui_story_5083_50830600_98_dialog_content = "더그, 나 지금 농담하는 거 아냐.",
  ui_story_5083_50830600_99_dialog_content = "고마워, 잘 생각해 볼게.",
  ui_story_5083_50830600_100_dialog_content = "더는 바보 같은 생각하지 말라고...",
  ui_story_5083_50830700_1_dialog_content = "<color=#e8d9bb>얼마 후, 제2군단 「돌격대대」가 정식으로 창설됐다. 더그는 소령 진급 후 대대장으로 취임했고, 바튼도 대위로 진급해 기계화보병대대의 부대대장이 되었다.</color>",
  ui_story_5083_50830700_2_dialog_content = "<color=#e8d9bb>그리고 더그의 우려는 틀리지 않았다. 얼마 후 어둠의 위기는 더 격화되기 시작했다.</color>",
  ui_story_5083_50830700_3_dialog_content = "<color=#e8d9bb>암귀 군단이 일루미나의 방위선을 뚫고, 자난성의 전초기지인\n13호와 19호 지하성을 포위한 것이었다.</color>",
  ui_story_5083_50830700_4_dialog_content = "<color=#e8d9bb>전투가 시작되자마자 통신이 두절되었고, 전령병이 포위를 돌파해 자난성에 도착했을 때는\n이미 수일이 경과한 뒤였다.</color>",
  ui_story_5083_50830700_5_dialog_content = "<color=#e8d9bb>자난성에서는 긴급회의가 열렸다. 그러나 상층부는 긴 논쟁에도 결론을 내리지 못하고 있었다.</color>",
  ui_story_5083_50830700_6_dialog_content = "더는 못 기다립니다! 우리가 이러는 동안에도 전방에선 수많은 사상자가 발생하고 있습니다!",
  ui_story_5083_50830700_7_dialog_content = "대원수님, 2군단은 이미 준비를 마쳤습니다. 명령만 내려주시면 바로 출병하겠습니다.",
  ui_story_5083_50830700_8_dialog_content = "전령병의 소식으로 본다면, 13호 지하성이 더 버틸 수 있는 건 길어야 하루다.",
  ui_story_5083_50830700_9_dialog_content = "19호 지하성 쪽 상황은 조금 더 낫겠지만,\n부대를 보내더라도 도착했을 때 보게 될 건 괴멸한 지하성뿐일 거다.",
  ui_story_5083_50830700_10_dialog_content = "팡고, 13호 지하성에 주둔 중인 지휘관은 네 전우다.\n그리고 넌 분명히 나보다 더 잘 알고 있겠지.",
  ui_story_5083_50830700_11_dialog_content = "그들처럼 영광스러운 전사들이라면, 지하성을 지킬 수 없다고 판단될 경우,\n즉시 지하성을 폭파할 거다!",
  ui_story_5083_50830700_12_dialog_content = "지하성의 물자와 교통망이 암귀 놈들에게 넘어가 자난성을 위험에 빠트리는 일이 없도록 말이지.",
  ui_story_5083_50830700_13_dialog_content = "물론 네 말은 맞다. 그 돌대가리들이라면 물론 그러고도 남겠지.",
  ui_story_5083_50830700_14_dialog_content = "하지만 내가 아는 그들은 불굴의 정신과 결코 뒤지지 않는 전투 능력이 있다!",
  ui_story_5083_50830700_15_dialog_content = "게다가 그 지하성엔 아직 비전투인원과 다수의 귀중한 자료도 있으니,\n그들은 반드시 목숨을 걸고 지킬 거다!",
  ui_story_5083_50830700_16_dialog_content = "그러니 지하성과 함께 죽는 선택은 마지막 순간까지 하지 않을 거다!\n반드시 우리의 지원을 기다리고 있을 거란 말이다!",
  ui_story_5083_50830700_17_dialog_content = "우리 3군단은 지금 절반의 병력이 어둠의 밑바닥에서 적과 대치하고 있다.\n너희 군단도 이제 막 신병을 보충한 참이고.",
  ui_story_5083_50830700_18_dialog_content = "1군단은 방위선 유지에 여념이 없지... 이런 상황에서 누굴 보내겠다는 거냐.",
  ui_story_5083_50830700_19_dialog_content = "그러다 암귀의 포위 공세가 시작되면 우리 병력으로는 수비조차 어려울 거다.\n그런데도 병력을 분산시킬 셈이냐?",
  ui_story_5083_50830700_20_dialog_content = "게다가 그 두 지하성과 자난성 간에는 지하 철도망도 구축되지 않았다.\n지원 병력을 파견하더라도 지상을 통해야 하지.",
  ui_story_5083_50830700_21_dialog_content = "통신도 두절된 상태에서 만에 하나 지원 병력이 포위되기라도 한다면 더 위험해진다!",
  ui_story_5083_50830700_22_dialog_content = "그럼 그 두 지하성은 위험하지 않기라도 하단 말이냐?!",
  ui_story_5083_50830700_23_dialog_content = "모데르, 그러니까 네놈은 냉혈한인 거다!",
  ui_story_5083_50830700_24_dialog_content = "팡고! 그 말 취소해라! 난 어둠의 밑바닥에서 놈들을 막으려고 그 많은 부하들을 잃었다!\n너만 부하들 목숨을 아끼는 줄 아는 거냐?!",
  ui_story_5083_50830700_25_dialog_content = "정말 못 들어주겠네...",
  ui_story_5083_50830700_26_dialog_content = "바튼!",
  ui_story_5083_50830700_27_dialog_content = "거기 있는 놈들은 우리의 방패가 되어주고 있습니다.\n근데 방패에 불 좀 붙었다고 지금 그걸 통째로 버리겠다는 겁니까?",
  ui_story_5083_50830700_28_dialog_content = "여긴 일개 초급장교가 자유롭게 발언해도 좋은 자리가 아니다.",
  ui_story_5083_50830700_29_dialog_content = "거 죄송하게 됐습니다! 안 그래도 나가려던 참이었습니다.\n여기 더 있다간 저까지 쪽팔릴 것 같으니 말입니다.",
  ui_story_5083_50830700_30_dialog_content = "누가 네놈한테 그따위로 행동해도 좋다고 했나!",
  ui_story_5083_50830700_31_dialog_content = "죄송합니다. 바튼 대위는 생각 없이 말하는 편입니다.",
  ui_story_5083_50830700_32_dialog_content = "더그, 지금 뭐 하는 거냐. 너 상대를 잘못 잡은 거 아니냐?",
  ui_story_5083_50830700_33_dialog_content = "말다툼은 끝났나?",
  ui_story_5083_50830700_34_dialog_content = "1군단은 지금도 전장에서 혈전을 벌이고 있다. 그 정도 싸웠으면 만족들 했겠지?",
  ui_story_5083_50830700_35_dialog_content = "두 젊은 장교, 너희는 자신의 군단장을 지지하는가?",
  ui_story_5083_50830700_36_dialog_content = "그거야 당연하죠, 대원수「님」.",
  ui_story_5083_50830700_37_dialog_content = "...저는 3군단장님 말씀에도 일리가 있다고 생각합니다.",
  ui_story_5083_50830700_38_dialog_content = "야, 너 돌았어?",
  ui_story_5083_50830700_39_dialog_content = "희생된 동포들의 목소리가 아직도 머릿속에서 울려대고 있어...\n조금만 잘못해도 우린 죽어간 자들을 볼 면목이 없게 될 거야.",
  ui_story_5083_50830700_40_dialog_content = "...먼저 나가 있어라.",
  ui_story_5083_50830700_41_dialog_content = "예! 군단장님, 대국을 생각해서 신중한 판단을 부탁드립니다. 위험을 무릅써선 안 됩니다.\n바튼, 너도 명심해라...",
  ui_story_5083_50830700_42_dialog_content = "일루미나의 아이들은 중앙 탑의 빛 아래에서 자랐다. 저들은 우리의 대의가 무엇인지 알고 있다!",
  ui_story_5083_50830700_43_dialog_content = "자난성 바깥에 주둔한다는 건 무엇을 의미하는지, 전우들은 진작에 각오가 되어 있을 것이다.",
  ui_story_5083_50830700_44_dialog_content = "팡고, 지금은 말싸움이나 하고 있을 시간이 없다. 우린 함께 자난성을 지켜야 한다.",
  ui_story_5083_50830700_45_dialog_content = "그들은 일루미나를 위해 죽음을 마다하지 않을 거다.\n그렇다면 난 저들에게 그 선택에 가치가 있었음을 반드시 가르쳐 줘야 한다.",
  ui_story_5083_50830700_46_dialog_content = "네가 안 간다면 내가 가겠다!",
  ui_story_5083_50830700_47_dialog_content = "안 된다, 팡고.",
  ui_story_5083_50830700_48_dialog_content = "모데르의 말에도 일리가 있다. 전황은 긴장 상태고, 추가적인 손실은 피해야 한다.\n게다가 1군단장도 지원에 동의하지 않았다.",
  ui_story_5083_50830700_49_dialog_content = "지금은 서로 의지할 때인데, 말다툼이나 하고 있을 순 없다.",
  ui_story_5083_50830700_50_dialog_content = "휘하의 장병들이 보면 뭐라고 생각하겠나. 군의 사기를 유지할 수 있을 것 같나?",
  ui_story_5083_50830700_51_dialog_content = "크윽...! 바튼, 가자!",
  ui_story_5083_50830700_52_dialog_content = "진지를 지키고, 제멋대로 행동하지 마라! 이건 명령이다!",
  ui_story_5083_50830700_53_dialog_content = "아무래도 회의가 잘 안 풀린 모양이군요.",
  ui_story_5083_50830700_54_dialog_content = "뭐냐, 1군단 망나니, 흥!",
  ui_story_5083_50830700_55_dialog_content = "잠깐만 시간을 내 주십시오. 전 <color=#FFB400>군령</color>을 전해 드리려고 온 겁니다.",
  ui_story_5083_50830700_56_dialog_content = "「제2군단은 지금 즉시 제1군단 라인하르트 소위의 부대와 함께 출격해\n두 지하성을 지원한다...」",
  ui_story_5083_50830700_57_dialog_content = "대충 이런 느낌인데, 어떠십니까?",
  ui_story_5083_50830700_58_dialog_content = "...지금 군령을 조작하겠다는 거냐?!",
  ui_story_5083_50830700_59_dialog_content = "상부에선 지원할 생각이 없다면, 우리가 가서 구하면 됩니다.",
  ui_story_5083_50830700_60_dialog_content = "제가 1군단의 일부 병력을 동원하겠습니다. 자난성 수비는 나머지 병력과 3군단이면 충분합니다.",
  ui_story_5083_50830700_61_dialog_content = "여긴 우리가 있든 없든 안전하겠지만, 저 두 지하성엔 생사가 달린 문제입니다.",
  ui_story_5083_50830700_62_dialog_content = "다만 제 부대만 가지고는 병력이 부족합니다. 따라서 2군단의 지원을 받을 수 있었으면 합니다.",
  ui_story_5083_50830700_63_dialog_content = "그런 짓을 벌이면 어떻게 될지도 물론 알고 있겠지?",
  ui_story_5083_50830700_64_dialog_content = "마음 써 주셔서 감사합니다. 하지만 전 사람들을 구하는 게 더 중요하다고 생각합니다.",
  ui_story_5083_50830700_65_dialog_content = "...일개 소위가 어디서 그런 용기가 생긴 거냐.",
  ui_story_5083_50830700_66_dialog_content = "팡고 군단장님과 2군단이라면 전우를 버리지 않을 거라고 믿기 때문입니다.",
  ui_story_5083_50830700_67_dialog_content = "군단장님, 아직도 망설이시는 겁니까? 전 라인하르트와 갈 겁니다.",
  ui_story_5083_50830700_68_dialog_content = "지금까진 무모하기만 했는데, 이젠 군령 조작이라니,\n라인하르트, 너 정말 간이 배 밖으로 나왔구나.",
  ui_story_5083_50830700_69_dialog_content = "그 말 하려고 여기까지 따라온 거야?",
  ui_story_5083_50830700_70_dialog_content = "네 그 말도 안 되는 야심을 내가 그냥 놔둘 것 같아?",
  ui_story_5083_50830700_71_dialog_content = "재밌군... 저들에게 불만이 있는 게 우리 둘만은 아니었던 모양이지?\n좋아, 그럼 이제부터 우리가 받을 명령은 우리가 내리자고!",
  ui_story_5083_50830700_72_dialog_content = "훗, 가장 위험한 13호 지하성은 나한테 맡겨.",
  ui_story_5083_50830700_73_dialog_content = "그럼 나도 대환영이야. 병력은 얼마나 데려갈 거야?",
  ui_story_5083_50830700_74_dialog_content = "지금은 가용 병력이 부족하니까, 1개 소대만 맡겨주면 충분해.",
  ui_story_5083_50830700_75_dialog_content = "1개 소대로 되겠어? 나도 부하들 데리고 같이 갈게!",
  ui_story_5083_50830700_76_dialog_content = "기다려라!",
  ui_story_5083_50830700_77_dialog_content = "모데르 저 망할 놈은 사람을 열받게 만들지만, 놈과 정보부가 파악한 정보는 틀릴 일이 없다.",
  ui_story_5083_50830700_78_dialog_content = "13호 지하성의 상황은 낙관할 수 없다... 시간상으로 본다면... 가망이 없는 건 사실이다.",
  ui_story_5083_50830700_79_dialog_content = "본대가 이동하면 오히려 전황에 휘말려 발을 뺄 수 없게 된다.",
  ui_story_5083_50830700_80_dialog_content = "알겠습니다... 그럼 레이스, 네가 소규모 부대로 가 줘.",
  ui_story_5083_50830700_81_dialog_content = "전투에 몰두하지 마. 산개전과 목표 구출 위주로 작전을 수행해.",
  ui_story_5083_50830700_82_dialog_content = "네 지휘는 필요 없어, 라인하르트. 넌 기다리고나 있어.\n내가 모두를 데리고 승리와 함께 돌아올 테니까.",
  ui_story_5083_50830700_83_dialog_content = "어이, 나도 같이 가! 난 부대대장이고, 내 병력을 꽤 동원할 수 있어.",
  ui_story_5083_50830700_84_dialog_content = "레이스한테 맡겨 둬. 난 녀석의 힘을 알아. 13호 지하성은 레이스가 가는 게 최선이야.",
  ui_story_5083_50830700_85_dialog_content = "19호 지하성은 13호보다 더 크다. 버텨낼 가능성도 더 높지.",
  ui_story_5083_50830700_86_dialog_content = "하지만 만에 하나, 13호 지하성이 이미 함락됐다면,\n19호도 동시에 공격을 받고 있을 가능성이 높다.",
  ui_story_5083_50830700_87_dialog_content = "바튼, 넌 멍청한 놈이지만, 그래도 내가 연마해 낸 「첨예탄」인 건 확실하다.",
  ui_story_5083_50830700_88_dialog_content = "이런 대형 전장에서의 싸움은 너와 우리의 기계화부대가 가장 적합하지.",
  ui_story_5083_50830700_89_dialog_content = "하지만 장비 구역의 경비병들은 최고 명령만을 따른다. 구두의 가짜 군령은 소용없을 거다.\n너흰 저들의 교대 시간을 노리고 장비를 빼앗아라.",
  ui_story_5083_50830700_90_dialog_content = "아니, 군단장님. 그럼 또 우리보고 19호 지하성을 지키라고 하시는 겁니까?",
  ui_story_5083_50830700_91_dialog_content = "바튼, 군단장님 말씀대로 하자. 자난성에서 2군단 전군을 동원하는 건 우리에겐 무리야.",
  ui_story_5083_50830700_92_dialog_content = "서둘러라. 저들이 눈치채기 전에 메인 엘리베이터를 타고 올라가라.\n그것만 해도 시간을 꽤 아낄 수 있을 거다!",
  ui_story_5083_50830700_93_dialog_content = "...거 위원회에 바로 체포되지나 마십쇼. 군단장님 본대를 기다리고 있을 테니 말입니다.",
  ui_story_5083_50830700_94_dialog_content = "기다려! 너희 정말 진심이야?",
  ui_story_5083_50830700_95_dialog_content = "군단장님, 바튼을 그렇게 부추기시면 일루미나를 배반하는 거나 다름없습니다!\n아끼시던 부하를 망치실 생각이십니까?",
  ui_story_5083_50830700_96_dialog_content = "상관에게 반항하고, 가짜 군령을 전하고, 일루미나를 배반한다면...\n대원수님께서 그냥 넘어가지 않으실 겁니다.",
  ui_story_5083_50830700_97_dialog_content = "......",
  ui_story_5083_50830700_98_dialog_content = "난 그딴 건 모르겠고, 더그, 딱 하나만 물어본다. 같이 갈 거야? 말 거야?",
  ui_story_5083_50830700_99_dialog_content = "난 네가 박물관에서 했던 말 아직 기억하고 있어.\n그런데도 네 입에서 저들을 구하러 안 가겠다는 말이 나와?",
  ui_story_5083_50830700_100_dialog_content = "나도 물론 그러고 싶어... 하지만...",
  ui_story_5083_50830700_101_dialog_content = "대원수님을 설득할 방법이 있을 거야. 내가 말씀드려 볼게...",
  ui_story_5083_50830700_102_dialog_content = "똑바로 서라, 더글라스! 네 짬에 어딜 대원수님한테 가서 입을 놀리겠다는 거냐.",
  ui_story_5083_50830700_103_dialog_content = "하지만 저흰 대원수님 동의 없이는 멋대로 움직일 수 없습니다...",
  ui_story_5083_50830700_104_dialog_content = "하나만 물으마. 갈 거냐, 말 거냐.",
  ui_story_5083_50830700_105_dialog_content = "대원수님의 동의 없이는 명령 위반입니다...\n전 절대 일루미나를 배반하는 그런 중죄를 지을 순 없습니다...\n그렇게 되면 결국 위원회에 약점을 잡히게 될 겁니다...",
  ui_story_5083_50830700_106_dialog_content = "진정으로 일루미나를 배반한 건 대원수와 상부다. 전우가 죽어 가는 걸 보고만 있다니──",
  ui_story_5083_50830700_107_dialog_content = "라인하르트 소위! 말을 삼가라! 내 부하놈 교육은 네가 참견할 일이 아니다.",
  ui_story_5083_50830700_108_dialog_content = "더그 네 생각도 잘 알겠다... 일단 부대로 돌아가라.",
  ui_story_5083_50830700_109_dialog_content = "마음에 망설임을 품은 탄환은 힘을 갖지 못한다. 너는 안 와도 된다.\n이게 옳지 않다고 생각한다면, 상부에 우릴 고발해도 좋다.",
  ui_story_5083_50830700_110_dialog_content = "아, 아닙니다... 군단장님, 명령만 내려 주십시오! 말씀만 하시면 어떻게 되든 저도 함께...",
  ui_story_5083_50830700_111_dialog_content = "네게 강요할 생각은 없다!",
  ui_story_5083_50830700_112_dialog_content = "더그, 진정해라. 넌 틀리지 않았다. 하지만 어떤 일들은 규칙만 가지고 되지 않는 법이다.",
  ui_story_5083_50830700_113_dialog_content = "자, 가자. 바튼, 라인하르트 소위.",
  ui_story_5083_50830700_114_dialog_content = "나중에라도 생각이 선다면 따라와.\n결심이 안 선다면 여기 남아서 우리가 돌아올 집을 잘 지키고 있어.",
  ui_story_5083_50830700_115_dialog_content = "부탁할게.",
  ui_story_5083_50830700_116_dialog_content = "바튼, 이 등신아... 정식 명령이 내려올 때까지... 절대 죽지 마라...",
  ui_story_5083_50830700_117_dialog_content = "<color=#e8d9bb>경비병 교대 시간을 노려, 라인하르트와 바튼은 부하들을 이끌고 장비 구역에 돌입했고,\n그들이 미처 반응하기도 전에 대량의 장비를 탈취했다.</color>",
  ui_story_5083_50830700_118_dialog_content = "<color=#e8d9bb>그들이 「반란」을 깨달았을 때는, 후미를 맡고 있던 바튼이 빗발치는 총탄을 피하며\n이미 마지막 장갑차에 기어오른 뒤였다.</color>",
  ui_story_5083_50830700_119_dialog_content = "서둘러! 통신은 끊었어. 놈들이 전원을 끄기 전에 엘리베이터로 가자!",
  ui_story_5083_50830700_120_dialog_content = "후... 위험했어. 진짜로 공격해 오다니...",
  ui_story_5083_50830700_121_dialog_content = "삐빅, 바튼 씨, 최고등급 중대 범죄를 저질러 버렸네요...",
  ui_story_5083_50830700_122_dialog_content = "하! 왜 너도 따라온 거냐?",
  ui_story_5083_50830700_123_dialog_content = "이러면 너도 「한배」를 타게 되는 거다.\n도망치고 싶다면 엘리베이터가 올라가기 전에 얼른 내리라고.",
  ui_story_5083_50830700_124_dialog_content = "삐빅, 바튼 씨...",
  ui_story_5083_50830700_125_dialog_content = "「조종사」는 절대로 바튼 씨를 포기하지 않아요──",
  ui_story_5083_50830801_1_dialog_content = "<color=#e8d9bb>어둠이 깔린 밤, 황야에는 암귀의 파도가 요동쳤다.\n놈들은 엄청난 기세로 19호 지하성의 입구로 모여들고 있었다.</color>",
  ui_story_5083_50830801_2_dialog_content = "<color=#e8d9bb>며칠간 포위된 지하성의 근접 방어 장비는 이미 파괴되거나 탄환이 소진되었고,\n병사들은 속수무책인 국면을 그저 지켜보는 수밖에 없었다.</color>",
  ui_story_5083_50830801_3_dialog_content = "<color=#e8d9bb>지하성의 유일한 출입구에서는 병사들이 지금도 계속 싸우고 있었다.\n총알이 바닥나면 도검을 뽑아 들고, 도검이 부러지면 주먹을 휘둘렀다──</color>",
  ui_story_5083_50830801_4_dialog_content = "<color=#e8d9bb>그들은 방패로서의 신념을 굳게 지키고, 일체의 잡념과 사고를 버린 채,\n그저 가슴에 희미한 희망의 빛을 품고 싸우고 있었던 것이다.</color>",
  ui_story_5083_50830801_5_dialog_content = "<color=#e8d9bb>「전령병이 포위를 돌파했다. 자난성은 우리를 절대 버리지 않을 것이다.」</color>",
  ui_story_5083_50830801_6_dialog_content = "<color=#e8d9bb>5일... 10일... 시간이 흐르면서 그 희미한 희망의 빛은 흔들리기 시작했다.\n그러나 마음이 얼어붙기 전, 신념을 품고 싸우던 이들은 마침내 볼 수 있었다.\n시산혈해의 너머에서 다가오는──</color>",
  ui_story_5083_50830801_7_dialog_content = "<size=45>다 날려버려!</size>",
  ui_story_5083_50830801_8_dialog_content = "틈이 생겼다! 서둘러라! 전투 병력은 돌입해서 방어 거점을 되찾는다!",
  ui_story_5083_50830801_9_dialog_content = "먼저 탄약부터 보충하고, 방어 장비도 점검해라.\n근접 방어 시스템은 쓸 수 있는 건 쓰고, 못 쓰는 건 해체해서 일회용으로라도 써먹어!",
  ui_story_5083_50830801_10_dialog_content = "입구는 우리가 지킨다. 라인하르트, 넌 안의 상황을 보고 와.",
  ui_story_5083_50830801_11_dialog_content = "쾰른, 수송장갑차를 몰고 와!",
  ui_story_5083_50830801_12_dialog_content = "우린 자난성에서 온 지원군이다! 최고 책임자는 어디 있지?",
  ui_story_5083_50830801_13_dialog_content = "대령님은 전사하셨다... 할 말이 있으면 내게 해라!",
  ui_story_5083_50830801_14_dialog_content = "기계화부대가 지상에서 적을 막고 있습니다. 즉시 올라와서 방어시설을 구축하십시오!",
  ui_story_5083_50830801_15_dialog_content = "비전투인원은 중요 물자와 함께 즉각 철수시키십시오. 저희 수송장갑차를 쓰시면 됩니다.",
  ui_story_5083_50830801_16_dialog_content = "너흰 어쩔 셈이지?",
  ui_story_5083_50830801_17_dialog_content = "저흰 이곳이 안전해질 때까지 모두와 함께 여길 지킬 겁니다!",
  ui_story_5083_50830801_18_dialog_content = "안심하십시오. 저흰 선발대일 뿐입니다. 곧 1개 군단 전 병력이 지원을 올 겁니다.",
  ui_story_5083_50830801_19_dialog_content = "모두가 단결하고 포기하지 않는다면, 분명히 지켜낼 수 있을 겁니다!",
  ui_story_5083_50830801_20_dialog_content = "<color=#e8d9bb>「어둠의 물결」이 끊임없이 밀려드는 가운데,\n바튼은 단 10여 대의 전차를 이끌고 종횡무진하며 전황을 타개하고자 했다.</color>",
  ui_story_5083_50830801_21_dialog_content = "<color=#e8d9bb>그러나 적의 압도적인 수 앞에서 전력의 차이는 분명했다.</color>",
  ui_story_5083_50830801_22_dialog_content = "큰일입니다! 궤도가 끊어졌습니다! 대형 암귀가...\n바튼 부대대장님, 먼저 가겠습니다.",
  ui_story_5083_50830801_23_dialog_content = "기다려! 내가 지금 바로...",
  ui_story_5083_50830801_24_dialog_content = "영광을 위하여!",
  ui_story_5083_50830801_25_dialog_content = "<color=#e8d9bb>움직일 수 없게 된 전차는 내부의 탄약과 함께 폭발했고,\n불길은 순식간에 주변의 암귀를 집어삼켰다.</color>",
  ui_story_5083_50830801_26_dialog_content = "<size=45>이 빌어먹을 괴물 새끼들아! 이거나 처먹어!</size>",
  ui_story_5083_50830801_27_dialog_content = "근접 방어포를 들어 올려! 탄약을 아끼지 마라! 놈들을 다 터트려 버리란 말이다!",
  ui_story_5083_50830801_28_dialog_content = "공세에 휩쓸리지 마라! 반드시 놈들을 몰아내야 한다!",
  ui_story_5083_50830801_29_dialog_content = "<size=45>우오오!</size>",
  ui_story_5083_50830801_30_dialog_content = "보고드립니다. 13호 지하성의 기능은 완전히 마비되었습니다.\n현 상황으로 본다면, 암귀는 약 20분 후 피난소에 들이닥칠 것입니다.",
  ui_story_5083_50830801_31_dialog_content = "통신은 여전히 끊긴 채고, 유격대도 상층으로 회로를 복구하러 오지 못하고 있습니다.\n지하성을 공격하던 <color=#FFB400>초대형 암귀</color>는 사라졌지만, 내부는 소형 암귀로 넘쳐나고 있습니다.",
  ui_story_5083_50830801_32_dialog_content = "에너지 센터도 파괴되었고, 아직 가동되고 있는 건 기밀 시설인 폭파 시스템뿐입니다...",
  ui_story_5083_50830801_33_dialog_content = "우리가 지하성과 함께 죽는 것은 상관없다. 그만한 각오는 모두 하고 있다.\n하지만 대량의 자료와 비전투인원이 아직 피난소에 있다...",
  ui_story_5083_50830801_34_dialog_content = "<color=#e8d9bb>대령은 입을 다문 채 은신처에서 지하성의 높은 곳을 바라보았다.\n어둠 속에서는 오직 파멸의 불길만이 타오르고 있었다──</color>",
  ui_story_5083_50830801_35_dialog_content = "아직도 싸우고 있는 놈들은 기껏해야 열일곱도 안 되는 애송이들이다.\n저들을 나 같은 늙은이들과 죽게 만드는 건... 불공평한 처사다.",
  ui_story_5083_50830801_36_dialog_content = "여긴 곧 암귀의 소굴로 변할 겁니다... 자난성에선 우릴 구하러 오지 않을 것이고 말입니다.\n대령님도 아시지 않습니까. 우린 자난성의 짐이 될 순 없습니다.",
  ui_story_5083_50830801_37_dialog_content = "...18분만 더 기다리자. 피난소가 뚫릴 것 같으면 즉시 지하성 전체를 폭파한다.\n적어도 암귀의 손에 죽는 것보다는 나을 테니.",
  ui_story_5083_50830801_38_dialog_content = "문을 두들기는 소리가 들려오면, 저들은 형용할 수 없는 공포를 느끼겠지요...\n저들에게 절망 속에서 18분을 더 살게 만드실 겁니까?",
  ui_story_5083_50830801_39_dialog_content = "아니, 난 18분만 더 희망을 품으라고 말하는 거다! 저들은 분명히 믿고 있을 것이다...\n문을 여는 건 우리 일루미나의 동포라고 말이다!",
  ui_story_5083_50830801_40_dialog_content = "...너무 잔인한 처사입니다... 전 이성적으로는 대령님의 뜻에 동의할 수 없습니다.\n우리는 자난성의 방패입니다. 영광을 위해 희생하도록 정해져 있단 말입니다──",
  ui_story_5083_50830801_41_dialog_content = "전 누가 우릴 구하러 오길 바라지 않습니다... 다른 사람들이 휘말리지 않길 바랍니다...\n하지만... 그저 믿는 것만이라면...",
  ui_story_5083_50830801_42_dialog_content = "희망의 빛이... 정말 우리에게 비칠 수 있는 겁니까?",
  ui_story_5083_50830801_43_dialog_content = "──입감 시 응답 바란다. 반복한다. 귀소 측, 통신 입감하였는지 응답 바란다.",
  ui_story_5083_50830801_44_dialog_content = "당소는 자난성에서 파견된 구출 부대의 지휘관이다.\n현재 상층에서 내부로 잠입 중이며, 통신 회로를 복구했다. 귀소 측, 생존자 수를 보고하라.",
  ui_story_5083_50830801_45_dialog_content = "......!",
  ui_story_5083_50830801_46_dialog_content = "안 됩니다! 응답하지 마십시오! 지하성 안은 암귀 천지입니다! 저들까지 끌어들일 순 없습니다!",
  ui_story_5083_50830801_47_dialog_content = "지금 지하성 상황은 제가 대령님보다 더 잘 알고 있습니다! 우린 가망이 없습니다!\n이제 곧 중앙 탑이 에너지 센터부터 무너지고, 우린 아무도 나갈 수 없을 겁니다!",
  ui_story_5083_50830801_48_dialog_content = "저들을 들여보내면 안 됩니다! 어서 지하성을 폭파해야 합니다!\n이대로면 여기서 모두가 끝장입니다... 저들이라도 살아야 재건의 희망이 있는 겁니다...",
  ui_story_5083_50830801_49_dialog_content = "총소리를 들었다. 교전 중이라는 것은 생존자가 있다는 뜻이겠지.\n피난소에 있는 건가? 통신이 힘든 상황인가?",
  ui_story_5083_50830801_50_dialog_content = "그것도 아니면... 지원군을 「길동무」로 삼고 싶지 않은 건가?",
  ui_story_5083_50830801_51_dialog_content = "대답 안 하시겠다? 정말 꽉 막힌 인간들뿐이라니까...\n이렇게 된 이상 뭔가 신호를 줄 수밖에 없겠어.",
  ui_story_5083_50830801_52_dialog_content = "라인하르트가 날 보낸 건 네가 충동적으로 나설지 걱정해서야.\n우리가 잘못 움직이면 지하성 전체의 암귀가 전부 이쪽으로 올 거야.",
  ui_story_5083_50830801_53_dialog_content = "침묵하는 정의로는 어둠을 깨트릴 수 없어.",
  ui_story_5083_50830801_54_dialog_content = "저들의 절망이 느껴지지 않아? 라인하르트였다면 분명히 이렇게 했을 거야!",
  ui_story_5083_50830801_55_dialog_content = "<color=#e8d9bb>13호 지하성은 몰락하고 있었다. 이미 만회할 수 없는 국면임을 누구나 알고 있었다.</color>",
  ui_story_5083_50830801_56_dialog_content = "<color=#e8d9bb>그러나 고요해진 절망의 땅에도 빛을 밝히는 신호탄이 있었다.\n자난성에서 온 뇌광이 모든 공포를 덮어버리기 시작했던 것이다.</color>",
  ui_story_5083_50830801_57_dialog_content = "<color=#e8d9bb>레이스는 일부러 장갑을 부딪혀 강렬한 빛과 소리를 발산했고,\n천둥소리가 울리자, 모든 암귀들이 레이스에게 주의를 돌렸다.</color>",
  ui_story_5083_50830801_58_dialog_content = "누가 못 구한대? 우리가 바로 저들의 마지막 희망이고! 마지막 구원이야!",
  ui_story_5083_50830801_59_dialog_content = "똑바로 들어. 지금부터 부대를 데리고 상부에서 심층부까지 치고 들어갈 거야.\n비전투인원들 피난 준비시켜.",
  ui_story_5083_50830801_60_dialog_content = "...당신 대체 누구야? 왜 이런 짓을 하는 거지?\n대원수님 쪽에서 구출에 동의하셨을 리가 없어!",
  ui_story_5083_50830801_61_dialog_content = "그럼 가르쳐 줄게, 나는 레이스── 미래의 일루미나 대원수가 될 사람이야!\n그 누구도 내 정의를 두고 뭐라 할 자격은 없어!",
  ui_story_5083_50830801_62_dialog_content = "<color=#e8d9bb>암귀들이 계단을 따라 몰아치자, 레이스는 홀로 선두에 서서 맞섰다.\n부유하는 칼날과 번개가 몰아치고, 피의 비를 쏟으며 그녀는 적의 무리를 뚫고 나아갔다.</color>",
  ui_story_5083_50830801_63_dialog_content = "봤나, 저게 바로 우리 일루미나의 신예... 우리가 힘들게 길러낸 「첨예탄」이다...",
  ui_story_5083_50830801_64_dialog_content = "...모두가 꿈꿔왔던 「계명성」 말입니까... 저 눈부신 빛은... 대체...",
  ui_story_5083_50830801_65_dialog_content = "저들은 우리의 꿈이다. 그 꿈을 깨트려서야 되겠나.",
  ui_story_5083_50830801_66_dialog_content = "...제 목숨을 걸고, 10분 안에 피난소 앞 통로를 확보하겠습니다.",
  ui_story_5083_50830801_67_dialog_content = "나는 부대를 이끌고 지원 부대와 호응하겠다. 나머지는 부탁한다.",
  ui_story_5083_50830801_68_dialog_content = "<color=#FFB400>여명의 빛</color>을... 어떻게든 모두에게 보여줄 것이다!",
  ui_story_5083_50830801_69_dialog_content = "<color=#e8d9bb>19호 지하성 주변에서는 전쟁의 불길이 3일간 이어지고 있었다.\n그러나 지원군의 모습은 여전히 보이지 않았다.</color>",
  ui_story_5083_50830801_70_dialog_content = "<color=#e8d9bb>증원을 통해 보급된 탄약도 이미 떨어졌고, 병사들은 다시 백병전을 펼치며 고전하고 있었다.</color>",
  ui_story_5083_50830801_71_dialog_content = "물러서지 마라! 진지를 지켜! 입구가 막히게 둬선 안 된다!",
  ui_story_5083_50830801_72_dialog_content = "크오오──!",
  ui_story_5083_50830801_73_dialog_content = "기습이 통할 것 같냐?!",
  ui_story_5083_50830801_74_dialog_content = "...하하, 좋아! 망할 꼰대... 아니, 군단장님 말이 맞았어.\n다수의 암귀 상대로는 무의식적으로 근접 무기를 쓰게 되잖아. 신기하게 약발이 좋단 말이지.",
  ui_story_5083_50830801_75_dialog_content = "새로운 깨달음이라도 얻었어? 전우.",
  ui_story_5083_50830801_76_dialog_content = "뭐, 그냥 악마 군단장한테 배워서 생긴 조건 반사일 뿐이라고.\n흥, 이 전장도 이제 점점 익숙해지고 있어.",
  ui_story_5083_50830801_77_dialog_content = "이대로는 우리도 위험해. 넌 차라리 부대를 데리고 포위를 돌파해.\n사람들을 최대한 많이 자난성으로 피신시키는 거야.",
  ui_story_5083_50830801_78_dialog_content = "그럼 넌 어쩔 거야? 여기 남을 거냐?",
  ui_story_5083_50830801_79_dialog_content = "말했잖아, 난 저들과 끝까지 싸우겠다고...\n죽어도 못 막게 된다면 지하성을 폭파하겠어. 암귀 놈들은 아무것도 얻을 수 없을 거다.",
  ui_story_5083_50830801_80_dialog_content = "안 돼! 난 반대야! 군단장님이 온다고 했어. 그 꼰대는 자기가 한 말은 반드시 지킨다고.",
  ui_story_5083_50830801_81_dialog_content = "...우린 아무 통신도 못 받았어. 새로 보낸 전령병도 돌아오지 않아...\n바튼, 그래도 그 사람을 믿어?",
  ui_story_5083_50830801_82_dialog_content = "꼰대가 성질은 더럽긴 해도, 한 번도 날 속인 적은 없어...\n물론 난 그 사람을 믿어. 너한테 등을 맡기듯이 말이야!",
  ui_story_5083_50830801_83_dialog_content = "좋아! 그럼 나도 거절할 이유가 없지.",
  ui_story_5083_50830801_84_dialog_content = "흥, 여명의 빛을 위해, 그리고 희생된 전우들을 위해서라도...\n난 절대 저놈들한테 항복하지 않고, 맥 빠지게 튀지도 않을 거다.",
  ui_story_5083_50830801_85_dialog_content = "그럼 서로 등을 맡기고, 죽기 전까지 싸워보자고!",
  ui_story_5083_50830801_86_dialog_content = "라인하르트, 대형 암귀가 접근한다! 저, 저게 놈들의 지휘관일 가능성이 높아!",
  ui_story_5083_50830801_87_dialog_content = "일루미나의 애송이들아── 나, 「파멸의 전조」 앞에 무릎 꿇고 복종하라!",
  ui_story_5083_50830801_88_dialog_content = "통용어를 쓰는 암귀냐? 아주 대단하시구만...\n근데 어쩌냐? 이 형님은 다리가 무거워서 무릎이 안 꿇리거든. 아니면 내 칼이랑 인사할래?",
  ui_story_5083_50830801_89_dialog_content = "더 지껄일 말은 없나? 우린 항복엔 재능이 없어서 말이야.\n대신 내 관통의 별이 가르쳐 줄 거다. 여명의 빛이 무엇인지 말이야!",
  ui_story_5083_50830801_90_dialog_content = "나는 일찍이 「어머니」께서 어둠 속 별들을 사냥하시는 것을 보았다.\n별의 의지는 무력했고, 그 무엇도 막을 수 없었지.",
  ui_story_5083_50830801_91_dialog_content = "나약한 너희 오로리안들은 심연 속에서 구차하게 목숨을 이어가는 것밖에 모르면서,\n감히 자신들이 특별하다 여기고 있군.",
  ui_story_5083_50830801_92_dialog_content = "이곳의 빛도 곧 사라질 것이다... 자난성 또한 마찬가지다.\n여명의 빛 따위... 가소로운 거짓말이다.",
  ui_story_5083_50830801_93_dialog_content = "어이, 라인하르트, 웬 시인이 오셨는데?",
  ui_story_5083_50830801_94_dialog_content = "아무리 고상한 말을 늘어놓아 봤자... 넌 아무것도 모른다.",
  ui_story_5083_50830801_95_dialog_content = "언젠가 반드시, 우리는 임시 「참호」에서 벗어나 아스트라의 지상으로 돌아간다.\n우리의 진정한 출발점에서 빛을 향해 계속 나아갈 거다.",
  ui_story_5083_50830801_96_dialog_content = "「일루미나」는 새벽을 깨는 여명! 검은 밤을 가르는 서광이다!\n그것은 우리 모두의 마음이고, 네놈들의 횡포를 저지하는 믿음이다!",
  ui_story_5083_50830801_97_dialog_content = "우리 모두가 불꽃이고... 우리가 바로 여명의 빛이다!\n네놈이 우리의 빛을 꺼트릴 수 있을 것 같으냐!",
  ui_story_5083_50830801_98_dialog_content = "말 잘한다! 어이, 거기 시인, 네 부하가 아무리 많아도, 우리의 기개를 꺾을 순 없다!",
  ui_story_5083_50830801_99_dialog_content = "건방진 일루미나의 애송이들, 그 대가를 치르게 해 주마! 가라!",
  ui_story_5083_50830801_100_dialog_content = "<color=#e8d9bb>콰아아앙!</color>",
  ui_story_5083_50830801_101_dialog_content = "<color=#e8d9bb>갑자기 날아온 포탄이 암귀의 몸에 맞자, 격렬한 폭발과 함께 녀석을 날려 보냈다.</color>",
  ui_story_5083_50830801_102_dialog_content = "<color=#e8d9bb>이윽고 나팔 소리가 울려 퍼졌고, 동시에 19호 지하성의 방송 소리도 따라서 퍼지기 시작했다.\n지원군의 도착을 알리는 신호가 모든 이의 마음을 다시 고무시킨 것이었다.</color>",
  ui_story_5083_50830801_103_dialog_content = "<color=#e8d9bb>피투성이가 되어 분전하던 병사들은 소리를 향해 고개를 돌렸다.\n지평선 너머에서는 하나의 군단이 햇살을 받으며 전진해 오고 있었다.</color>",
  ui_story_5083_50830801_104_dialog_content = "<color=#e8d9bb>제2군단의 깃발은 바람에 나부꼈고, 그것은 바로── 새벽을 깨는 힘이었다.</color>",
  ui_story_5083_50830801_105_dialog_content = "감히 내 몸에 상처를 입히다니... 용서할 수 없다!\n어리석은 오로리안들이여, 그 목숨으로 대가를 치르게 해 주마──",
  ui_story_5083_50830801_106_dialog_content = "그 전에 우리부터 넘어야 할 거다! 가자, 라인하르트!",
  ui_story_5083_50830802_1_dialog_content = "「계명성」... 안 돼! 넌 반드시 여기서 죽어야 한다!\n아스트라의 유일한 운명은 끝없는 고난뿐이다... 영원한 밤은 바뀌지 않을 것이다!",
  ui_story_5083_50830802_2_dialog_content = "하지만 수많은 고난을 이겨내는 건 예로부터 영웅 이야기의 변치 않는 주제였지.",
  ui_story_5083_50830802_3_dialog_content = "내가 실패했다고...? 내가 실패하다니! 안 돼──",
  ui_story_5083_50830802_4_dialog_content = "너희는 파멸을 막을 수 없다... 종은 이미 울리기 시작했으니...\n<color=#FFB400>종말</color>의 시간이 곧 도래할 것이다...",
  ui_story_5083_50830802_5_dialog_content = "내 형제들이 나의 숙업을 이어 나가리라... 아아! <color=#FFB400>어머니</color>시여...",
  ui_story_5083_50830802_6_dialog_content = "저놈 도대체 뭐라고 지껄이는 거야...? 어째 강적이 더 있다는 암시처럼 들리는데 말이지...",
  ui_story_5083_50830802_7_dialog_content = "글쎄... 하지만 우린 살아남았어. 지금은 그걸로 충분해.",
  ui_story_5083_50830802_8_dialog_content = "서둘러라! 3대대는 에너지 센터 구조 작전을 실시하고, 지하성의 각 선로를 복구하라.\n그리고 자난성에... 아니, 모든 지하성에 이 소식을 전하라!",
  ui_story_5083_50830802_9_dialog_content = "여긴 아직 가망이 있으니까 포기하지 말라고 전해!",
  ui_story_5083_50830802_10_dialog_content = "군단장님, 13호 지하성에서 통신 요청을 보내왔습니다. 받아 주십시오!",
  ui_story_5083_50830802_11_dialog_content = "...19호 지하성이 무사하다는 소식을 들었다. 팡고, 네가 구한 건가?",
  ui_story_5083_50830802_12_dialog_content = "미안하다, 친구... 널 구하러 갈 수가 없었다.",
  ui_story_5083_50830802_13_dialog_content = "훗, 무슨 소릴 하는 거냐. 너나 나나 똑같이 선택했을 최고의 방법 아니냐.\n19호 지하성을 잘 부탁한다. 절대 또 빼앗기지 마라.",
  ui_story_5083_50830802_14_dialog_content = "참, 그 레이스란 젊은이... 대단하더군. 지금 피난소에 있는 사람들을 데리고 떠나고 있다.",
  ui_story_5083_50830802_15_dialog_content = "뭐라고요? 군단장님, 저한테도 부대를 주십쇼. 제가 지원하러 가겠습니다!",
  ui_story_5083_50830802_16_dialog_content = "옳은 의견입니다. 지금 상황으로 본다면 13호 지하성도 구할 수 있을...",
  ui_story_5083_50830802_17_dialog_content = "조용! 입 다물고 듣기나 해.",
  ui_story_5083_50830802_18_dialog_content = "우린 이미 보름 내내 교전을 펼쳤다... 날 제외한 모든 지휘부가 전사했지.",
  ui_story_5083_50830802_19_dialog_content = "19호 지하성의 좋은 소식을 들으니 드디어 마음이 놓이는군.",
  ui_story_5083_50830802_20_dialog_content = "안 나올 셈이냐.",
  ui_story_5083_50830802_21_dialog_content = "지하성이 무너지고 있다. 누군가는 남아서 폭파해야 한다...\n자난성으로 향하는 길이 막히고 나면... 붕괴는 멈출 거다.",
  ui_story_5083_50830802_22_dialog_content = "언젠가는 13호 지하성도 재건될 날이 오겠지...\n난 이곳에서 그날을 기다릴 생각이다... 하지만...",
  ui_story_5083_50830802_23_dialog_content = "...남겠다는 녀석들이 더 있는 모양이군.",
  ui_story_5083_50830802_24_dialog_content = "아, 맞아. 내가 애써 갈고 닦은 정예들이지. 모두 훌륭한 「첨예탄」들이다.",
  ui_story_5083_50830802_25_dialog_content = "알겠다... 마침 이쪽은 전투가 계속 벌어지고 있다.\n「지원」을 요청할 테니 네 정예 병력을 빌려주길 바란다.",
  ui_story_5083_50830802_26_dialog_content = "이건 공식적인 명령이다.",
  ui_story_5083_50830802_27_dialog_content = "좋아... 그러면 녀석들은 네게 맡기마. 대신 약속해라. 쉽사리 희생시키지 마라.",
  ui_story_5083_50830802_28_dialog_content = "약속한다... 친구여.",
  ui_story_5083_50830802_29_dialog_content = "...작별이군, 팡고. 너무 빨리 만나러 오진 마라.",
  ui_story_5083_50830802_30_dialog_content = "그럼 난 명령을 내리러 가 보겠다... 여명의 빛을 위하여.",
  ui_story_5083_50830802_31_dialog_content = "여명의 빛을 위하여... 귀관에게 경의를 표한다.",
  ui_story_5083_50830802_32_dialog_content = "군단장님! 대체 왜 그러십니까?! 13호 지하성엔 아직 사람이 있습니다!\n그럼 아직 희망이 있는 건데, 대체 왜 그쪽 병력을 빌리겠다는...",
  ui_story_5083_50830802_33_dialog_content = "입 다물고 가서 쉬고나 있어라. 꼬라지를 보니 머리도 제대로 안 돌아가는 모양이군.",
  ui_story_5083_50830802_34_dialog_content = "하지만...!",
  ui_story_5083_50830802_35_dialog_content = "이건 명령이다! 바튼 부대대장, 자기 신분을 직시해라!",
  ui_story_5083_50830802_36_dialog_content = "...쳇!",
  ui_story_5083_50830802_37_dialog_content = "소중한 「탄환」들을 지키고 싶으신 겁니까.",
  ui_story_5083_50830802_38_dialog_content = "...우리 늙은이들은 오직 일루미나를 세우는 데에만 급급했다.\n하지만 오랜 세월 싸워 오면서, 아무래도 정말로 눈이 좀 어두워진 모양이야.",
  ui_story_5083_50830802_39_dialog_content = "새벽을 깨는 「탄환」은 오직 젊은이들일 수밖에 없다.\n더 날카로운 눈과 뚜렷한 두뇌를 가진 이들 말이다...",
  ui_story_5083_50830802_40_dialog_content = "하하... 내가 대원수와 함께 그림자 전투에 참여했을 때만 해도,\n너희보다 고작 몇 살 더 먹은 나이였는데 말이야.",
  ui_story_5083_50830802_41_dialog_content = "헌데 어쩐 일인지... 어느새 우리도 자기가 그렇게 싫어하던 모습으로 변해 있었다.",
  ui_story_5083_50830802_42_dialog_content = "...여명의 빛을 위하여. 군단장님께 경의를 표합니다.",
  ui_story_5083_50830802_43_dialog_content = "너도 가서 쉬도록 해라. 나 혼자 조용히... 벗을 배웅하고 싶다.",
  ui_story_5083_50830802_44_dialog_content = "삐빅, 바튼 씨의 심리 상태가 부정적으로 변화한 것을 감지했습니다... 절 따라오세요...",
  ui_story_5083_50830802_45_dialog_content = "?!",
  ui_story_5083_50830802_46_dialog_content = "뭘 그렇게 죽상이야? 아직 안 죽었잖아.",
  ui_story_5083_50830802_47_dialog_content = "놀라지 마. 너희가 보낸 전령병들은 이미 자난성으로 돌아갔어.\n19호 지하성에 가망이 있다니까 대원수님도 서둘러 지원을 명하셨고.",
  ui_story_5083_50830802_48_dialog_content = "그래서 우리도 「정식」으로 여기 보내진 거야.",
  ui_story_5083_50830802_49_dialog_content = "...너 괜찮아?",
  ui_story_5083_50830802_50_dialog_content = "젠장... 빌어먹을! 더럽게 늦었잖아!",
  ui_story_5083_50830802_51_dialog_content = "...또 얼마나 많은 전우들이 죽었는 줄 알아? 이 망할 자식아!",
  ui_story_5083_50830802_52_dialog_content = "무슨 말을 그렇게 하냐. 내 포격 아니었으면 너희 다 죽었어, 이 등신아.",
  ui_story_5083_50830802_53_dialog_content = "빌어먹을!!!",
  ui_story_5083_50830802_54_dialog_content = "그래서... 왜 그렇게 죽상인데? ...군단장님이 전우들을 「나 몰라라」해서 그래?",
  ui_story_5083_50830802_55_dialog_content = "13호 지하성엔 분명히 가망이 있었어. 여기처럼 버틸 수 있었다고...\n근데 이젠 터져서 폐허가 돼 버렸잖아.",
  ui_story_5083_50830802_56_dialog_content = "게다가 망할 꼰대가 거기 남은 마지막 병력까지 빌려 가 버렸어...\n병사들이 자기 상관 곁을 떠나게 만들었다고...",
  ui_story_5083_50830802_57_dialog_content = "그럼 넌 그 병사들도 같이 죽길 바란 거냐?",
  ui_story_5083_50830802_58_dialog_content = "사실 너도 내 질문의 답이 뭔진 알잖아...\n우리가 그 상황이었어도 군단장님 곁을 떠나고 싶진 않았겠지.",
  ui_story_5083_50830802_59_dialog_content = "반대로 네가 군단장님이면 어쩔 것 같아?\n우리 다리라도 부러트려서 후송 차량에 집어 던질 거냐?",
  ui_story_5083_50830802_60_dialog_content = "......",
  ui_story_5083_50830802_61_dialog_content = "군단장님까지 동의하신 거면, 그 외엔 정말 방법이 없었던 거야.",
  ui_story_5083_50830802_62_dialog_content = "폭파 임무 하나 때문에 그 많은 사람들이 죽을 필요는 없잖아...\n차라리 새로운 임무를 주는 게 살아갈 의지를 심어 줄 수 있는 거야.",
  ui_story_5083_50830802_63_dialog_content = "그게 바로 일루미나가 줄곧 고수해 온 이성적인 방식이야.",
  ui_story_5083_50830802_64_dialog_content = "이건 거짓말이 아냐. 19호 지하성은 앞으로 싸움을 계속해 나가야 해.\n그러니까 이번 일은... 그냥 선배님들의 암묵적인 규칙이라고 생각하자.",
  ui_story_5083_50830802_65_dialog_content = "어쨌든, 친구의 우스꽝스러운 「임무」를 수락해서라도...\n애써 육성한 정예들은 지켜내야 하는 거니까 말이야.",
  ui_story_5083_50830802_66_dialog_content = "왜 병사들의 의견은 안 묻는 건데?\n상관이 독단적으로 자신을 위해 희생하길 바랄 사람은... 없을 거라고...",
  ui_story_5083_50830802_67_dialog_content = "...그 병사들 모두가 그분들의 「자식」이자, 일루미나의 「자식」이니까.",
  ui_story_5083_50830802_68_dialog_content = "그러니까 그건 그분들의 마지막 노력인 거야...",
  ui_story_5083_50830900_1_dialog_content = "<color=#e8d9bb>연일 계속된 전투가 마침내 끝나고, 암귀 군단이 평원에서 사라지자,\n황폐해진 대지에는 무수한 상처가 남아 있었다.</color>",
  ui_story_5083_50830900_2_dialog_content = "<color=#e8d9bb>비록 19호 지하성은 지켜냈지만, 제2군단은 절반 이상의 병력 손실을 입었다.</color>",
  ui_story_5083_50830900_3_dialog_content = "<color=#e8d9bb>바튼은 쓰러진 전우들의 곁에 누워, 공허한 눈으로 온기가 없어 보이는 듯한 태양을 바라봤다.</color>",
  ui_story_5083_50830900_4_dialog_content = "일어나라, 이제 갈 시간이다.",
  ui_story_5083_50830900_5_dialog_content = "...군단장님?",
  ui_story_5083_50830900_6_dialog_content = "저도 일어나고 싶은데... 함께 사진을 찍었던 전우들이 전부 옆에 누워서 일어나질 않습니다.",
  ui_story_5083_50830900_7_dialog_content = "전 사람을 구하러 온 건데, 왜 제가 지휘할 때마다 전우들이 자꾸 줄어드는지 모르겠습니다...",
  ui_story_5083_50830900_8_dialog_content = "...받아라.",
  ui_story_5083_50830900_9_dialog_content = "묵직할 거다. 그들을 기억해라. 그 이름들과 과거를 잊지 마라.",
  ui_story_5083_50830900_10_dialog_content = "우린 살아남은 이상 반드시 앞으로 나아가야만 한다.",
  ui_story_5083_50830900_11_dialog_content = "너 이 자식, 아무래도 싸우다가 정신머리가 빠진 모양이군.\n넌 반드시 계속 나아가야 한다! 적어도 비석에 이름이 새겨진 전우들을 위해서라도 말이다!",
  ui_story_5083_50830900_12_dialog_content = "그걸 제가 몰라서 이러겠습니까?! 하지만...",
  ui_story_5083_50830900_13_dialog_content = "「하지만」이란 없다! 저들을 위해서라도, 우린 저들의 희생이 값진 것이었다고 확신해야 한다!\n멍청한 놈, 전우들의 희생을 부정할 셈이냐?",
  ui_story_5083_50830900_14_dialog_content = "...2군단장님 말씀이 맞아. 19호 지하성이 살아남은 건 하나의 신호가 될 거야.",
  ui_story_5083_50830900_15_dialog_content = "아직 교전 중인 최전선도 포함해서, 모든 지하성이 이 소식을 접하게 되겠지.",
  ui_story_5083_50830900_16_dialog_content = "그럼 다른 이들도 더 강한 신념을 갖게 될 거야...\n19호 지하성이 살아남았으니, 다른 모든 지하성도 생존할 희망이 있다고 말이야.",
  ui_story_5083_50830900_17_dialog_content = "분명히 언젠가는 아스트라도 이 어둠에서 해방될 수 있어.",
  ui_story_5083_50830900_18_dialog_content = "너무 깊이 생각하지 마. 적어도 지금 우린 희망의 불꽃을 지켜 냈잖아.\n이 모든 게 그 자체만으로도 의미가 있어.",
  ui_story_5083_50830900_19_dialog_content = "비록 그 대가가 끝없는 희생이고, 영혼을 내던져 불을 지펴야 한다 해도...\n그럴 가치는 충분해.",
  ui_story_5083_50830900_20_dialog_content = "흥... 내가 생각해 온 지휘엔 이렇게 많은 희생이란 전제는 없었다고.",
  ui_story_5083_50830900_21_dialog_content = "굳이 뭔가를 태워야 한다면... 차라리 날 태울 거다.\n분명히 더 세차고... 더 거세게 타오를 테니까...",
  ui_story_5083_50830900_22_dialog_content = "<color=#e8d9bb>19호 지하성이 구조되었다는 소식은 일루미나에 빠르게 퍼져 나갔고,\n지원 부대가 돌아오기도 전에 이미 자난성에 대대적으로 알려졌다.</color>",
  ui_story_5083_50830900_23_dialog_content = "<color=#e8d9bb>집단 속에서 소문은 갈수록 부풀려졌고, 어느새 바튼 일행은 차세대 영웅이자\n대원수가 파견한 정예 부대가 되어 있었다.</color>",
  ui_story_5083_50830900_24_dialog_content = "<color=#e8d9bb>결국 상황의 변화로 인해, 그들이 받기로 정해졌던 죄명과 처벌도 흐지부지 없던 일이 되었다.</color>",
  ui_story_5083_50830900_25_dialog_content = "일루미나의 강령이 뭐지? 팡고, 네가 말해 봐. 일루미나의 강령이 뭐냔 말이다!",
  ui_story_5083_50830900_26_dialog_content = "「하나는 우리, 우리는 하나」입니다.",
  ui_story_5083_50830900_27_dialog_content = "즉 「상관의 명령에 복종하고, 모든 것은 일루미나를 위해 행동한다」 아닌가?!",
  ui_story_5083_50830900_28_dialog_content = "네가 멋대로 행동한다고, 이젠 부하들까지 너처럼 안하무인으로 가르쳤나?",
  ui_story_5083_50830900_29_dialog_content = "이번엔 요행으로 19호 지하성을 구할 수 있었지만,\n아니었다면 그전까지 벌인 일들을 수습할 수 있었을 것 같나?",
  ui_story_5083_50830900_30_dialog_content = "그래서는 결국 자기 부하들을 다 죽게 만들 거란 말이다!",
  ui_story_5083_50830900_31_dialog_content = "대원수님, 저흰 요행이 아니라 큰 희생을 치르고...",
  ui_story_5083_50830900_32_dialog_content = "입 다물고 있어!",
  ui_story_5083_50830900_33_dialog_content = "너, 네가 바로 바튼인가? 이름 조금 날리더니 눈에 뵈는 게 없어도 되는 줄 아는 거냐?",
  ui_story_5083_50830900_34_dialog_content = "대원수님, 바튼 대위는 머리가 나쁠 뿐이지, 다른 의도는 없습니다!",
  ui_story_5083_50830900_35_dialog_content = "...너도 마찬가지다! 저들과 같이 사고를 치면 어떤 문제를 초래할지 몰랐...",
  ui_story_5083_50830900_36_dialog_content = "미안합니다, 실례하겠습니다.",
  ui_story_5083_50830900_37_dialog_content = "위원회의 비서? 누가 멋대로 들어와도 된다고 했지?",
  ui_story_5083_50830900_38_dialog_content = "위원회의 명령으로 전언을 전하러 왔습니다, 대원수님.",
  ui_story_5083_50830900_39_dialog_content = "구조 작전은 대성공을 거두었고, 영웅들에 대한 선전 역시 군의 사기를 크게 진작시켰습니다.\n따라서 위원회는 이번 작전의 영웅들을 매우 긍정적으로 평가하고 있습니다.",
  ui_story_5083_50830900_40_dialog_content = "흥, 긍정적? 너희들이?",
  ui_story_5083_50830900_41_dialog_content = "특히 위원회에서는 젊은 세대의 라인하르트 소위...\n그리고 바튼 대위를 타의 모범으로 삼을 필요가 있다고 생각합니다.",
  ui_story_5083_50830900_42_dialog_content = "지금은 전쟁 중이다. 그런 소꿉장난은 아서라.",
  ui_story_5083_50830900_43_dialog_content = "바로 그 이유로 위원회는 모두의 사기를 북돋고자 「여명의 신성」이 필요하다고 보는 겁니다.",
  ui_story_5083_50830900_44_dialog_content = "...너흰 대체 무슨 짓을 꾸미고 있는 거냐.",
  ui_story_5083_50830900_45_dialog_content = "그럴 거면 여기 우리 애부터 진급시켜 주지 그래?\n지위 역량은 그런대로 있는 편이라, 기보대대장을 맡을 자격 정도는 있다.",
  ui_story_5083_50830900_46_dialog_content = "물론입니다. 그 정도는 일도 아니지요.\n참, 라인하르트 소위, 당신에 대한 포상은 아직 논의 중이니, 따라오시죠. 지금 바로.",
  ui_story_5083_50830900_47_dialog_content = "알겠습니다.",
  ui_story_5083_50830900_48_dialog_content = "대원수님, 다른 일이 없으시다면 저희도 먼저 가보겠습니다.",
  ui_story_5083_50830900_49_dialog_content = "...가 봐라.",
  ui_story_5083_50830900_50_dialog_content = "군단장님... 방금 좀 이상하지 않았습니까? 더그, 안 그래?",
  ui_story_5083_50830900_51_dialog_content = "일개 위원회 비서가 대원수를 무시해도 되는 겁니까? 저보다 더 건방지던데...",
  ui_story_5083_50830900_52_dialog_content = "왜 다들 말이 없습니까? 저만 이상하게 생각하는 겁니까?\n그 사람, 대원수님도 제쳐 두고 절 진급시켜 주겠다고 했잖습니까.",
  ui_story_5083_50830900_53_dialog_content = "......",
  ui_story_5083_50830900_54_dialog_content = "그건 네가 상관할 일이 아니다.",
  ui_story_5083_50830900_55_dialog_content = "위원회 놈들이 군을 견제한다고 들었습니다...",
  ui_story_5083_50830900_56_dialog_content = "네가 상관할 일이 아니라고 했잖아! 그런 시시한 놈들 보고 배우지 마라, 바튼...\n위원회 생각은 더더욱 하지 말고.",
  ui_story_5083_50830900_57_dialog_content = "진급했으면 네 일이나 제대로 해. 가서 신병을 뽑고 훈련시켜서, 군단 인원을 보충해라...",
  ui_story_5083_50830900_58_dialog_content = "전투는 앞으로도 많을 거다. 정신 바짝 차려라.",
  ui_story_5083_50831000_1_dialog_content = "어이, 라인하르트. 잠깐 이야기 좀 할 수 있을까?",
  ui_story_5083_50831000_2_dialog_content = "2군단 녀석, 일이 이 지경이 됐는데 또 뭐 하러 왔어?\n이런 녀석이 찾아올 정도라니, 라인하르트 너도 진짜 한심하네. 나한테 맡겨.",
  ui_story_5083_50831000_3_dialog_content = "바튼 대대장은 내 친구야. 시비 걸러 온 건 아닐 테니까 걱정하지 마.",
  ui_story_5083_50831000_4_dialog_content = "...며칠간 벌어진 일이 하나도 이해가 안 돼서 말이야.\n라인하르트, 넌 진급은커녕 오히려 너네 군단장한테 징계를 받았어. 대체 어떻게 된 거야?",
  ui_story_5083_50831000_5_dialog_content = "자리부터 좀 옮기자.",
  ui_story_5083_50831000_6_dialog_content = "단도직입적으로 묻겠어. 라인하르트, 넌 위원회랑 무슨 관계야?",
  ui_story_5083_50831000_7_dialog_content = "난 바보가 아냐. 눈썰미만 있다면 너랑 위원회 사이에 뭔가 있다는 건 누구나 알아챌 거다.\n놈들은 너한테 과할 정도로 신경을 쓰고 있어.",
  ui_story_5083_50831000_8_dialog_content = "저번에 그 비서가 대원수님 회의실까지 들이닥친 것도 너 때문이었겠지.",
  ui_story_5083_50831000_9_dialog_content = "이유가 뭐야? 그리고 왜... 정작 널 계속 보호해 주지 않는 건데?",
  ui_story_5083_50831000_10_dialog_content = "넌 내 전우야. 사실 이번 일도 기회가 되면 말해주려던 참이었어.",
  ui_story_5083_50831000_11_dialog_content = "우선, 네 말이 맞아. 난 확실히 위원회의 특별 관리를 받고 있어.\n그 이유라면, 아마 그들이 날 선택했기 때문이겠지.",
  ui_story_5083_50831000_12_dialog_content = "나도 잘은 모르겠지만, 위원회는 뭔가 계획을 세우고 있는 것 같고,\n특별 훈련을 통해 내 전투 잠재력을 깨우고 싶은 모양이야.",
  ui_story_5083_50831000_13_dialog_content = "그들은 아마 자기들이 아끼는 새싹을 지키려고 나선 거겠지.",
  ui_story_5083_50831000_14_dialog_content = "그리고 날 계속 보호하지 않고, 강등 처분을 받게 내버려둔 건... 일종의 경고일지도 몰라.",
  ui_story_5083_50831000_15_dialog_content = "그게 무슨 소리야...? 그럼 넌 진짜 더그 말대로 뒷배가 있는 녀석인 거냐?",
  ui_story_5083_50831000_16_dialog_content = "라인하르트, 너 그런 시시한 녀석이었어?",
  ui_story_5083_50831000_17_dialog_content = "아니, 정 반대야. 난 그저 체스말에 불과할지도 몰라.",
  ui_story_5083_50831000_18_dialog_content = "위원회 상부에서 내 육성에 신경을 쓰는 건 맞지만...\n저들은 내가 자신들의 통제를 벗어나는 걸 원치 않아.",
  ui_story_5083_50831000_19_dialog_content = "바튼... 지금부터 하는 얘기를 계속 듣는다면, 넌 또 나와 「한배」를 타는 신세가 될 거야.",
  ui_story_5083_50831000_20_dialog_content = "그래도 계속 듣겠어?",
  ui_story_5083_50831000_21_dialog_content = "목숨까지 맡긴 적도 있는데, 거절할 이유가 있겠냐?",
  ui_story_5083_50831000_22_dialog_content = "전쟁은 갈수록 격해지고 있고, 모든 병사들은 승리의 불꽃을 위한 장작으로 쓰일 수 있어...\n특히 위원회 사람들 눈에는 말이야.",
  ui_story_5083_50831000_23_dialog_content = "지금 그들은 나와 내 동생, 그리고 내 절친한 친구를 계획의 재료로 삼았을 가능성이 있어...\n지금은 테스트 단계일 뿐이지만, 난 아무리 생각해도 느낌이 안 좋아.",
  ui_story_5083_50831000_24_dialog_content = "그 테스트는 누구나 버틸 수 있는 게 아니야. 어린애들이라면 더 힘들겠지...\n난 내가 직접 겪었기 때문에 그게 얼마나 잔혹한 일인지 알아.",
  ui_story_5083_50831000_25_dialog_content = "나조차도 알아챘을 정도인데, 위원회와 접촉하는 대원수가 아무것도 모를 리 없어...\n그런데도 그자는 이 모든 걸 묵인하고 있지.",
  ui_story_5083_50831000_26_dialog_content = "대원수는 분명히 싸울 의지가 있어. 그건 나도 의심하지 않아.\n하지만 그자의 눈엔 두려움과 고단함이 담겨 있었어. 싸울 의지만으로는 미래를 열 수 없어.",
  ui_story_5083_50831000_27_dialog_content = "...너, 전에 네 <color=#FFB400>작은 목표</color>는 대원수가 되는 거라고 했었지.",
  ui_story_5083_50831000_28_dialog_content = "그래, 어둠이 없는 일루미나의 대원수가 되겠어.",
  ui_story_5083_50831000_29_dialog_content = "바튼, 아마 누군가는 네게 「위원회에 대해 생각하지 말라」고 했을 거야.\n하지만 그렇다 해도 일루미나가 새로운 항해를 시작하려면, 위원회를 벗어나야만 해.",
  ui_story_5083_50831000_30_dialog_content = "어이, 너 그 「배」, 너무 큰 거 아냐? 설마 일루미나 전체를 한배에 태울 작정이냐?",
  ui_story_5083_50831000_31_dialog_content = "「알에서 빠져나오려면 하나의 세계를 파괴하지 않으면 안 된다」라는 말, 들어 봤어?\n앞을 향해 큰 걸음을 내디디려면, 우선 족쇄부터 풀어야 하는 법이야.",
  ui_story_5083_50831000_32_dialog_content = "우리가 진정한 출발점으로 돌아가, 아스트라를 해방시키기 위해선...\n일루미나를 막후의 실력자들이 채운 족쇄로부터 해방시켜 주는 게 우선이야.",
  ui_story_5083_50831000_33_dialog_content = "저항하고 싶다면 행동으로 옮겨야 해.",
  ui_story_5083_50831000_34_dialog_content = "그걸 해내려면 말만 가지곤 안 되겠지. 그럼 내가 뭘 도와주길 바라는 거냐?",
  ui_story_5083_50831000_35_dialog_content = "내 편이 돼서, 일루미나의 썩은 부분을 제거해 줘.",
  ui_story_5083_50831000_36_dialog_content = "지금 일루미나의 병사들은 온갖 속박을 받고 있어.\n그저 여기서 태어났다는 이유만으로, 희생의 의미도 모른 채 우릴 위해 목숨을 잃고 있다고.",
  ui_story_5083_50831000_37_dialog_content = "싸움을 두려워하는 자는 오히려 <color=#FFB400>집행자</color>의 추적을 받게 되지...\n우리 일루미나는 정녕 이렇게 타락할 수밖에 없는 거냔 말이야.",
  ui_story_5083_50831000_38_dialog_content = "사람은 자기가 태어날 곳을 선택할 수 없어.\n하지만 난 적어도 저들이 무엇을 위해 싸우고 죽는지는 알게 해 주고 싶어!",
  ui_story_5083_50831000_39_dialog_content = "너부터, 그리고 나부터, 신념을 짊어진 모든 이들부터 시작하는 거야!\n더럽고 썩은 것들을 정화하기 시작하면, 언젠가는 진정한 여명의 빛을 이룩할 수 있을 테니까.",
  ui_story_5083_50831000_40_dialog_content = "그 후에야 비로소 우린 아스트라를 구할 수 있어.\n그리고... 진정한 출발점에서 더 큰 꿈을 좇을 수 있게 되겠지.",
  ui_story_5083_50831000_41_dialog_content = "부패를 정화하고 싶다면, 최악의 경우엔 전쟁이 일어날 수도 있어.",
  ui_story_5083_50831000_42_dialog_content = "난 일루미나를 갉아먹는 그 우유부단한 권력자들에게 복종할 생각은 조금도 없어.",
  ui_story_5083_50831000_43_dialog_content = "오직 일루미나의 정의가 다시는 가려지지 않도록 앞길을 비춰 줄 수만 있다면...\n부득이한 경우엔 내 영혼을 불살라서 반격하겠어.",
  ui_story_5083_50831000_44_dialog_content = "어쩌면 앞으로 난 <color=#FFB400>반역</color>이라 불리는 싸움을 벌여야 할지도 몰라. 그래서 난 전우가 필요해!",
  ui_story_5083_50831000_45_dialog_content = "좋아! 라인하르트, 네가 본 그 빛을 굳게 믿는다면, 나도 네 배에 내 목숨을 맡기겠어!",
  ui_story_5083_50831000_46_dialog_content = "나도, 내 부대도 좋아. 마음껏 명령을 내리라고.",
  ui_story_5083_50831000_47_dialog_content = "근데...",
  ui_story_5083_50831000_48_dialog_content = "?",
  ui_story_5083_50831000_49_dialog_content = "훗... 하하하! 넌 지금 강등까지 당했는데, 대원수 자리까지 올라가려면 너무 힘들지 않겠어?",
  ui_story_5083_50831000_50_dialog_content = "이 바튼 님이 먼저 대원수가 될 수도 있으니까 조심하라고.",
  ui_story_5083_50831000_51_dialog_content = "네가 정말 대원수 자리에 오른다면 진심으로 축하해 줄게.",
  ui_story_5083_50831000_52_dialog_content = "중요한 건 지위가 아니니까.",
  ui_story_5083_50831000_53_dialog_content = "하, 그것도 그렇네.",
  ui_story_5083_50831000_54_dialog_content = "그리고 하나 더... 누가 뭐래도 날 이 자리까지 끌고 와 준 건 군단장님인 만큼,\n이런 일을 그분에겐 숨기고 싶지 않아.",
  ui_story_5083_50831000_55_dialog_content = "동료는 많을수록 좋은 법이고, 나도... 군단장님과 더그를 적으로 삼는 일만큼은 없었으면 해.",
  ui_story_5083_50831000_56_dialog_content = "그 사람들에겐 솔직해도 돼.",
  ui_story_5083_50831000_57_dialog_content = "네가 내게 등을 맡겼으니까, 나도 안심하고 내 목숨을 네게 맡길게.",
  ui_story_5083_50831000_58_dialog_content = "난 네 안목을 믿고, 네가 믿는 사람들을 믿어.",
  ui_story_5083_50831000_59_dialog_content = "그럼 뭘 더 기다려? 말 나온 김에 다들 같이 얘기해 보는 건 어때?",
  ui_story_5083_50831000_60_dialog_content = "식당에 맛이 좋은 새 메뉴가 나왔어. 배급 구역으로 불러서 이야기해 보자.",
  ui_story_5083_50831000_61_dialog_content = "<size=45>좋아!</size>",
  ui_story_5083_50831100_1_dialog_content = "다른 친구들한테 전해달라고 부탁했어.\n부르는 김에 드니에르도 연구소에서 좀 끄집어내달라고 했고... 우리 먼저 가자.",
  ui_story_5083_50831100_2_dialog_content = "아니면 나 먼저 부대에 돌아가서 보고부터 하는 건 어때?\n가는 김에 꼰대랑 더그도 불러오면 되지.",
  ui_story_5083_50831100_3_dialog_content = "괜찮아, 더그는 내 친구들이 불러줄 거야.\n하지만 팡고 님은 우리 또래들 사이에 있으면 분위기가 좀 어색할걸.",
  ui_story_5083_50831100_4_dialog_content = "게다가 나도 그분한테 여러 번 혼나서, 이런 이야기를 하려면 나도 준비가 좀 필요할 것 같고.",
  ui_story_5083_50831100_5_dialog_content = "하하! 너도 그 꼰대가 무서운 거냐.",
  ui_story_5083_50831100_6_dialog_content = "뭘 그런 걸 떠들고 있어? 얼른 가기나 해.",
  ui_story_5083_50831100_7_dialog_content = "그나저나 넌 좋아하는 음식이나 취미 같은 거 있어?",
  ui_story_5083_50831100_8_dialog_content = "겨우 밖에 나왔는데, 아니면 사람들 모이기 전에 좀 놀고 있지 그래?\n난 먼저 식당에 가서 자리 잡고 있을 테니까.",
  ui_story_5083_50831100_9_dialog_content = "그런 거 없어. 전투도 없는데 밖에서 싸돌아 다녀서 뭐 해?",
  ui_story_5083_50831100_10_dialog_content = "그럼 휴가 땐 부대에서 뭐 하는데?",
  ui_story_5083_50831100_11_dialog_content = "숙소에서 대기하거나, 혼자서 훈련하지.",
  ui_story_5083_50831100_12_dialog_content = "뭐야, 그냥 바보였잖아?",
  ui_story_5083_50831100_13_dialog_content = "뭔 소리야?! 그냥 평소엔 휴가 때 딱히 할 일이 없으니까 그런 거라고.",
  ui_story_5083_50831100_14_dialog_content = "게다가 밖은 아직 전쟁통이라 갈 만한 곳도 딱히 없잖아.",
  ui_story_5083_50831100_15_dialog_content = "적어도 난 휴가 땐 여동생이나 친구랑 같이 있는데,\n넌 그로누 선배랑 비슷하게 집에만 있는 모양이네.",
  ui_story_5083_50831100_16_dialog_content = "그건 절대 아냐, 나도 유행엔 꽤 빠삭한 편이거든.",
  ui_story_5083_50831100_17_dialog_content = "...이 근처에 있는 「비밀 게임센터」도 알고 있을 정도라고.",
  ui_story_5083_50831100_18_dialog_content = "하하하, 그래. 그럼 근처 좀 둘러보고 있어.\n난 자리 잡고 헬리오스랑 다른 사람들 데리고 올 테니까.",
  ui_story_5083_50831100_19_dialog_content = "아, 참! 헬리오스는 나랑 어릴 때부터 친하게 지냈어.\n성격도 좋은 친구니까 너랑도 둘이 잘 맞을 거야.",
  ui_story_5083_50831100_20_dialog_content = "...나가서 구경을 하래도 뭘 어딜 가야 될지 알아야 말이지......",
  ui_story_5083_50831100_21_dialog_content = "이럴 줄 알았으면 그냥 부대로 돌아가서 더그랑 먼저 얘기나 할 걸 그랬어.",
  ui_story_5083_50831100_22_dialog_content = "삐삑, 바튼 씨... 적어도 휴식 시간은 충분히 즐기세요.",
  ui_story_5083_50831100_23_dialog_content = "갈 곳도 모르겠는데 뭘 즐겨... 휴, 결국 또 그로누의 「비밀 게임센터」인가.",
  ui_story_5083_50831100_24_dialog_content = "그로누 녀석... 걔가 이런 일에 관심이 있을까?",
  ui_story_5083_50831100_25_dialog_content = "「우와! 일루미나의 미래! 완전 재미없어. 난 돌아가서 게임이나 할래!」\n이러고도 남을 애 아냐?",
  ui_story_5083_50831100_26_dialog_content = "내 비밀 게임센터 입구에서 뭘 알짱대고 있어? 또 「해군왕」에 도전하려고?",
  ui_story_5083_50831100_27_dialog_content = "잘도 갑자기 등장하네... 어라? 내 드론은 어디 갔어?\n...또 도망간 건가. 진짜 낯도 참 많이 가리는 녀석이라니까.",
  ui_story_5083_50831100_28_dialog_content = "모임이 있어서 데리러 온 거야. 다 같이 식당에 모여서 식사도 하고 이야기도 하자고.\n라인하르트 그 녀석 너한테 아직 연락 안 했냐?",
  ui_story_5083_50831100_29_dialog_content = "모임? 아직 아무 말도 못 들었는데... 근데 엄청 재미있을 거 같으니까 나도 갈래!",
  ui_story_5083_50831100_30_dialog_content = "...대신 「한배」에 안 타게 조심해라. 다시 내리긴 힘들 테니까.",
  ui_story_5083_50831100_31_dialog_content = "...식당에 거의 다 왔네. 넌 뭐 좋아하는 음식 있냐?",
  ui_story_5083_50831100_32_dialog_content = "응? 근데 바튼 군은 딱 봐도 뭐가 맛있는지도 모르는 애 같은걸.",
  ui_story_5083_50831100_33_dialog_content = "난 음식 투정할 시간 따윈 없어. 우린 일루미나의 군인이야.\n우리가 통조림 음식 맛을 따지기 시작한다면, 그거야말로 곤란할 거라고.",
  ui_story_5083_50831100_34_dialog_content = "그치만 우리도 전선에 있는 모두가 맛있게 먹을 수 있게 맛을 개량하려고 노력하고 있다구.",
  ui_story_5083_50831100_35_dialog_content = "「움브라톤 생선구이 맛 압축 식량」이나, 「초콜릿 맛 에너지바」 같은 거 말이야.\n너도 먹어보면 알 거야!",
  ui_story_5083_50831100_36_dialog_content = "...아무리 맛있어도 그렇지, 바튼 군 너무 많이 먹었잖아.\n이러다 이따 밥 못 먹는 거 아냐?",
  ui_story_5083_50831100_37_dialog_content = "냠냠... 흥, 이 몸은 식사량도 남다르다고.\n이건 훌륭한 병사가 되기 위해선 반드시 갖춰야 할 자질이야.",
  ui_story_5083_50831100_38_dialog_content = "후후, 아무래도 다음에 널 이기면 너한테 신제품 시식하라고 해야겠네.\n그럼 내가 직접 할 필요도 없잖아.",
  ui_story_5083_50831100_39_dialog_content = "어이, 바튼! 너 여기서 뭐 해?",
  ui_story_5083_50831100_40_dialog_content = "누가 널 찾으려면 여기로 가라던데... 지금 이게 무슨 상황이야? 너 뭘 그렇게 많이 먹었어?",
  ui_story_5083_50831100_41_dialog_content = "됐으니까 일단 이 「벚꽃 맛 압축 쿠키」나 좀 먹어 봐.",
  ui_story_5083_50831100_42_dialog_content = "뭐? 됐어. 한 입만 먹어도 배부를 것 같잖아.",
  ui_story_5083_50831100_43_dialog_content = "먹어 보라니까, 진짜 맛있다고.",
  ui_story_5083_50831100_44_dialog_content = "난 중요한 일 때문에 온 거니까 저리 치워... 어휴, 이 바보는 언제 철 드는 거야?!",
  ui_story_5083_50831100_45_dialog_content = "...맛은 괜찮네.",
  ui_story_5083_50831100_46_dialog_content = "하나 더 줘 봐.",
  ui_story_5083_50831100_47_dialog_content = "하하, 보채지 마. 너무 많이 먹으면 이따가 밥 못 먹는다고!\n자, 같이 라인하르트한테 가자.",
  ui_story_5083_50831100_48_dialog_content = "너희 대체 뭘 꾸미고 있는 거야...?",
  ui_story_5083_50831100_49_dialog_content = "아주 재미있는 일이야! 네 몫도 준비해 뒀으니까, 먹고 나면 도망칠 생각하지 마.",
  ui_story_5083_50831100_50_dialog_content = "여기야! 구석에 자리 맡아 놨어! 빨리 와!",
  ui_story_5083_50831100_51_dialog_content = "가자. 참, 나 새로운 걸 많이 배웠거든. 조만간 너랑 또 겨뤄봐야겠어.",
  ui_story_5083_50831100_52_dialog_content = "너란 녀석은 정말...",
  ui_story_5083_50831100_53_dialog_content = "반갑다, 난 헬리오스라고 해.\n이번엔 너희 덕분에 라인하르트가 무사히 돌아올 수 있었어. 고맙다.",
  ui_story_5083_50831100_54_dialog_content = "여어, 난 바튼이고 이 녀석은 더그. 같은 일루미나인끼리 그렇게 격식 따질 거 없어.",
  ui_story_5083_50831100_55_dialog_content = "게다가 나도 라인하르트한테 도움을 많이 받았고 말이야.",
  ui_story_5083_50831100_56_dialog_content = "빨리 와! 식당 창구가 몰리기 시작했어!\n드니에르가 사람들 사이에 껴서 못 나오고 있어. 둘만 좀 와서 도와줘!",
  ui_story_5083_50831100_57_dialog_content = "뭔 음식이길래 저렇게 난리야?",
  ui_story_5083_50831100_58_dialog_content = "넌 원래 먹는 건 관심 없었잖아... 여기 신상은 전선부터 먼저 공급되거든.\n그래서 자난성에 들어오는 수량은 한정돼 있어.",
  ui_story_5083_50831100_59_dialog_content = "엄청 맛있다고 소문이 나서 매번 저렇게 줄을 선다니까.",
  ui_story_5083_50831100_60_dialog_content = "그럼 도와주러 가자고!",
  ui_story_5083_50831100_61_dialog_content = "정말 못 말린다니까, 라인하르트... 왜 수상하게 사람들을 모으나 했더니,\n식당 음식 때문에 그런 거였어?",
  ui_story_5083_50831100_62_dialog_content = "고작 음식 확보도 못 하면 1군단 체면이 안 살지! 다들 날 따라와! 라인하르트는 빼고!",
  ui_story_5083_50831100_63_dialog_content = "이야~ 젊은 애들은 참 열정이 넘친다니까~",
  ui_story_5083_50831100_64_dialog_content = "으음, 우린 여기서 음식만 기다리는 건가?",
  ui_story_5083_50831100_65_dialog_content = "후후, 저런 난리 통에 끼진 말자구~",
  ui_story_5083_50831100_66_dialog_content = "그로누 선배, 드니에르 쪽엔 선배가 제일 좋아하는 「푸딩」도 있어. 얼른 가지고 와!",
  ui_story_5083_50831100_67_dialog_content = "뭐어어어? 걱정 마. 내가 지금 당장 이 「던전」을 공략할 테니까!",
  ui_story_5083_50831100_68_dialog_content = "으아뜨뜨뜨거워! 사람이 너무 많아서 쟁반도 못 챙겼잖아!",
  ui_story_5083_50831100_69_dialog_content = "나한테 줘... 쓰읍!",
  ui_story_5083_50831100_70_dialog_content = "거 봐. 뜨겁다니까.",
  ui_story_5083_50831100_71_dialog_content = "다들 비켜! 잘 봐라, 바튼. 난 너보다 두 배는 더 가져왔다고.",
  ui_story_5083_50831100_72_dialog_content = "뭐야? 그 쟁반, 어디서 났어?",
  ui_story_5083_50831100_73_dialog_content = "이게 바로 정예 중의 정예, 돌격대대장의 능력이라고.",
  ui_story_5083_50831100_74_dialog_content = "사람들 사이에서 드니에르를 구출하는 데는 실패했지만, 음식은 가져왔어.",
  ui_story_5083_50831100_75_dialog_content = "음료 등장! 이럴 때 마실 게 없어서야 되겠어?",
  ui_story_5083_50831100_76_dialog_content = "마시기 대결할까?",
  ui_story_5083_50831100_77_dialog_content = "누가 겁낼 줄 알고?",
  ui_story_5083_50831100_78_dialog_content = "라인하르트... 너 뭔가 잊은 건 없어?",
  ui_story_5083_50831100_79_dialog_content = "하하, 드니에르랑 그로누 선배, 그리고 방금 보른이랑 애들도\n아직 디저트 창구에서 부대끼는 중이야.",
  ui_story_5083_50831100_80_dialog_content = "오려면 한참 걸릴 테니까, 신경 쓰지 말고 우리 먼저 한잔하자.",
  ui_story_5083_50831100_81_dialog_content = "그래도 내가 가 보는 게 좋겠어.",
  ui_story_5083_50831100_82_dialog_content = "조급해할 거 없어. 라인하르트가 저렇게까지 말하는데, 한 잔 마신다고 안 늦어.",
  ui_story_5083_50831100_83_dialog_content = "거참 영문을 모르겠네... 뭐, 그래도 맞는 말이야. 한 잔 마시고 가도 시간은 충분해.",
  ui_story_5083_50831100_84_dialog_content = "...그럼, 건배할까?",
  ui_story_5083_50831100_85_dialog_content = "건배!",
  ui_story_5083_50831100_86_dialog_content = "<color=#e8d9bb>「일루미나의 가장 밝게 빛나는 젊은 세대」가 식당 구석에서 웃음을 터트리며,\n즐겁게 그들의 첫 번째 모임을 가졌다.</color>",
  ui_story_5083_50831100_87_dialog_content = "<color=#e8d9bb>나는... 그 눈부신 빛에서 시선을 뗄 수 없었고,\n잠깐이라도 좋으니 그들의 모습을 두 눈에 남기고 싶었다.</color>",
  ui_story_5083_50831100_88_dialog_content = "노래 한 곡 어때? 더그, 네가 만든 군가를 얘들한테 들려줘.",
  ui_story_5083_50831100_89_dialog_content = "이거 놔 이 바보야, 부를 거면 혼자 부르라고!",
  ui_story_5083_50831100_90_dialog_content = "다들... 오래 걸리네.",
  ui_story_5083_50831100_91_dialog_content = "내 동생 걱정은 마. 나이가 몇 살인데, 길 잃고 그러진 않아...",
  ui_story_5083_50831100_92_dialog_content = "자, 한잔해! 그동안 우리의 즐거웠던 협력을 기념하자!",
  ui_story_5083_50831100_93_dialog_content = "누가 너랑 그런 걸 했다고...",
  ui_story_5083_50831100_94_dialog_content = "하하! 등 돌려도 소용없어. 「짠」은 내가 하면 되니까!",
  ui_story_5083_50831100_95_dialog_content = "<size=45>건배!</size>",
  ui_story_5083_50831200_1_dialog_content = "......",
  ui_story_5083_50831200_2_dialog_content = "솔직히 말하면, 네가 나랑 군단장님을 「한배」에 태우려고 할 줄은 몰랐어.",
  ui_story_5083_50831200_3_dialog_content = "바튼... 이 멍청한 자식, 너 지금 네가 뭔 소릴 하는지 알긴 하는 거냐?",
  ui_story_5083_50831200_4_dialog_content = "전 제가 할 말은 제대로 다 했습니다... 그리고 전 라인하르트를 믿습니다!",
  ui_story_5083_50831200_5_dialog_content = "...그 녀석, 미쳤군.",
  ui_story_5083_50831200_6_dialog_content = "진정해, 바튼. 잘 생각해 봐. 라인하르트는 지금 이미 밑바닥으로 강등당한 신세야.",
  ui_story_5083_50831200_7_dialog_content = "어쩌면 오기가 생겨서 널 이용하는 걸지도 몰라. 심지어 우리 2군단까지 말이야.",
  ui_story_5083_50831200_8_dialog_content = "하지만 난 그 녀석이랑 같이 며칠이나 19호 지하성을 지켰어.",
  ui_story_5083_50831200_9_dialog_content = "녀석은 그 사람들을 위해서 기꺼이 죽으려고 했어! 그런 녀석이 나쁜 뜻이 있다는 게 말이 돼?",
  ui_story_5083_50831200_10_dialog_content = "그들을 위해... 기꺼이 죽으려 했다고...?",
  ui_story_5083_50831200_11_dialog_content = "현재의 일루미나에 불만족스러운 점이 있는 건 사실이야...\n온건한 방식으론 그 수많은 문제를 단숨에 해결할 순 없겠지. 하지만...",
  ui_story_5083_50831200_12_dialog_content = "너희가 품은 그 뜻을 이루려면 너흰 대원수님, 그리고 네 친구들을 적으로 돌려야 해...",
  ui_story_5083_50831200_13_dialog_content = "암귀와의 전쟁은 아직도 계속되고 있어. 난... 네 생각에 동의 못 해.",
  ui_story_5083_50831200_14_dialog_content = "나도 절대로 동의 못 한다!",
  ui_story_5083_50831200_15_dialog_content = "난 일루미나를 위해 평생을 싸워 왔고, 일루미나의 모든 이들이 내 「혈육」처럼 친밀한 존재다.",
  ui_story_5083_50831200_16_dialog_content = "일루미나에 반기를 드는 자는 그 누구든 용납 못 한다!\n너흴 지지하는 건 더더욱 안 될 일이고 말이야!",
  ui_story_5083_50831200_17_dialog_content = "그렇습니까... 저도 군단장님은 절대 동의 안 하실 것 같았습니다.",
  ui_story_5083_50831200_18_dialog_content = "하지만 그래도 분명히 절 이해하실 거라 생각합니다.",
  ui_story_5083_50831200_19_dialog_content = "저흰 백야성처럼 되려는 게 아닙니다...\n그저 일루미나의 「기둥」이 되어, 일루미나를 지탱하고 싶을 뿐입니다.",
  ui_story_5083_50831200_20_dialog_content = "그래야만 변혁을...",
  ui_story_5083_50831200_21_dialog_content = "됐다! 더는 듣고 싶지 않다.",
  ui_story_5083_50831200_22_dialog_content = "......",
  ui_story_5083_50831200_23_dialog_content = "넌 내가 갈고 닦은 「탄환」이고, 난 내 안목을 믿는다.",
  ui_story_5083_50831200_24_dialog_content = "그리고 네가 네 목숨을 맡길 수 있는 그 라인하르트도 믿는다.",
  ui_story_5083_50831200_25_dialog_content = "...하지만 난 만에 하나라도 전우들이 서로 총칼을 겨누는 일은 없길 바란다...\n바튼, 내 손으로 네 목숨을 거두고 싶진 않단 말이다.",
  ui_story_5083_50831200_26_dialog_content = "난 오로리안이나 일루미나와 싸우라고 너흴 훈련시킨 게 아니다.",
  ui_story_5083_50831200_27_dialog_content = "저희도 당연히 그럴 생각은 없습니다! 저흰 그저 정의를 믿고, 미래를 향한 큰 걸음을...",
  ui_story_5083_50831200_28_dialog_content = "더 나불거렸다간 내 손으로 널 감옥에 집어넣어 주마.",
  ui_story_5083_50831200_29_dialog_content = "바튼, 진정해. 넌 아직 네가 뭘 해야 하는지 몰라.",
  ui_story_5083_50831200_30_dialog_content = "그러니까 돌아가서 다시 천천히 생각해 봐.",
  ui_story_5083_50831200_31_dialog_content = "뭘 「천천히 생각」하라는 거야? 결국 계속 참으라는 말이면서.",
  ui_story_5083_50831200_32_dialog_content = "중령까지 진급해서 대대장이 됐는데도 신병 훈련 임무밖에 없잖아.",
  ui_story_5083_50831200_33_dialog_content = "그런 건 아무 교관이나 데려다 놔도 할 수 있잖아! 내가 있어야 할 곳은 전선이라고!",
  ui_story_5083_50831200_34_dialog_content = "게다가 위원회가 계획한 그 촬영회는 또 뭐야... 내가 무슨 아이돌도 아니고.",
  ui_story_5083_50831200_35_dialog_content = "취재를 할 거면 전선에 있는 진짜 영웅들을 찾아가야지,\n안전지대에 있는 날 선전해 봐야 아무 의미도 없잖아.",
  ui_story_5083_50831200_36_dialog_content = "바튼 씨가 발산하는 빛은 아직 너무 일러요.",
  ui_story_5083_50831200_37_dialog_content = "하? 그게 무슨 뜻이야?",
  ui_story_5083_50831200_38_dialog_content = "미래에 동료들의 지지를 받아야, 바튼 씨는 비로소 진정한...",
  ui_story_5083_50831200_39_dialog_content = "...삐삑, 바튼 씨, 적어도 지금까진 아무 처벌도 받지 않았잖아요.",
  ui_story_5083_50831200_40_dialog_content = "「동료」라... 그래! 왜 그걸 생각 못 하고 있었지?",
  ui_story_5083_50831200_41_dialog_content = "나 혼자 여기서 뭘 쓸데없이 고민하고 있었던 거냐고. 역시 동료들과 상의해 보는 게 좋겠어.",
  ui_story_5083_50831200_42_dialog_content = "아쉽게도 더그 녀석은 내 말에 동의해 주지 않았지만...",
  ui_story_5083_50831200_43_dialog_content = "에라, 모르겠다. 라인하르트나 찾아가 봐야겠어. 너 라인하르트 어디 있는지 알아?",
  ui_story_5083_50831200_44_dialog_content = "삐삑, 바튼 씨... 절 따라오세요....",
  ui_story_5083_50831200_45_dialog_content = "뭐야, 왜 그로누네 가게로 온 건데...?\n뭐, 그로누는 그 자매랑 친하니까, 라인하르트가 어디 있는지 알고 있겠지.",
  ui_story_5083_50831200_46_dialog_content = "지금 누구랑 말하고 있는 거야? 선배는 지금 없어. 가게는 내가 대신 봐 주고 있고.\n무슨 일 있는 거면 나한테 말해.",
  ui_story_5083_50831200_47_dialog_content = "그것보다... 「일루미나의 프로파간다 영웅」 씨, 부대에 갇혀 있는 거 아니었어?",
  ui_story_5083_50831200_48_dialog_content = "몰래 빠져나왔다.",
  ui_story_5083_50831200_49_dialog_content = "...일단 그건 됐고, 라인하르트는? 어디 간 거야?",
  ui_story_5083_50831200_50_dialog_content = "특훈하러 갔어. 겸사겸사 일루미나 대원수가 되겠단 꿈도 좀 꾸고.",
  ui_story_5083_50831200_51_dialog_content = "너흰 평소엔 사이좋지 않았어? 어째 못마땅해 보이는데.",
  ui_story_5083_50831200_52_dialog_content = "내가 어떻게 알아.",
  ui_story_5083_50831200_53_dialog_content = "아마 언니도 점점 내 생각을 이해하기 어려워진 거겠지...",
  ui_story_5083_50831200_54_dialog_content = "비록 워게임에선 너한테 졌지만, 그래도 내가 이 정도 말은 해도 될 것 같다.",
  ui_story_5083_50831200_55_dialog_content = "넌 라인하르트가 될 수 없어. 너흰 다른 사람이니까.",
  ui_story_5083_50831200_56_dialog_content = "혹시라도 무슨 안 좋은 생각이 있는 거라면,\n늦기 전에 네가 사랑하는 언니한테 털어놓는 게 좋을 거다.",
  ui_story_5083_50831200_57_dialog_content = "라인하르트는 항상 너한테 마음을 써 왔어...\n어떤 말은 어색하다고 마음에 담아두고만 있으면, 상대가 알 수 없다고.",
  ui_story_5083_50831200_58_dialog_content = "...그래서 언니는 왜 찾는 건데?",
  ui_story_5083_50831200_59_dialog_content = "됐어. 당사자도 없는 이상 더 자세히 말해볼 수도 없을 테니까.\n혹시라도 라인하르트를 보게 되면 내가 찾는다고 말이나 전해 줘.",
  ui_story_5083_50831200_60_dialog_content = "알겠어.",
  ui_story_5083_50831200_61_dialog_content = "<color=#e8d9bb>드니에르의 약속을 받은 바튼은 그제서야 마음을 놓을 수 있었다.\n그는 다시 부대로 복귀했고, 처벌을 받은 후, 계속해서 위원회의 계획에 따라 움직였다.</color>",
  ui_story_5083_50831200_62_dialog_content = "<color=#e8d9bb>그렇지만 그는 결국 라인하르트에게서 아무 대답도 들을 수 없었다.</color>",
  ui_story_5083_50831200_63_dialog_content = "<color=#e8d9bb>자난성에서 한 연구소에 심각한 폭발 사건이 발생했다는 발표가 난 이후로,\n라인하르트 3인방과 그로누의 행방이 묘연해졌기 때문이었다.</color>",
  ui_story_5083_50831301_1_dialog_content = "<color=#e8d9bb>계절이 바뀌어도 어둠의 위기는 여전히 끝이 나지 않았다.\n암귀가 어디에서 나타나고, 어째서 개체 수가 자꾸 늘어나는지는 아무도 알지 못했다.</color>",
  ui_story_5083_50831301_2_dialog_content = "<color=#e8d9bb>그러나 모든 이들이 끝까지 싸울 이유는 충분했다.\n암귀들은 아직도 아스트라를 짓밟고, 이 대륙 위의 생명들을 앗아가고 있기 때문이었다.</color>",
  ui_story_5083_50831301_3_dialog_content = "<color=#e8d9bb>전황이 과열 양상을 치닫고 있을 때, 긴급 전보 한 통이 자난성으로 들어왔다.\n소규모 암귀 무리가 자난성 방어선 근처에 출몰했다는 소식이었다.</color>",
  ui_story_5083_50831301_4_dialog_content = "어떻게 된 거지? 13호 지하성은 자폭했고, 그쪽 통로는 우리가 저번에 이미 제대로 봉쇄했다.",
  ui_story_5083_50831301_5_dialog_content = "19호 지하성은 아직 잘 운용되고 있고, 그쪽에서 경보를 울리지도 않았으니,\n길목은 잘 지켜지고 있어야 맞다.",
  ui_story_5083_50831301_6_dialog_content = "방어선을 따라 위치한 지하성은 모두 안정적으로 돌아가고 있고, 어디서도 경보가 울리지 않았다.",
  ui_story_5083_50831301_7_dialog_content = "어쩌면 전처럼 소규모의 암귀가 산이나 지하 유적을 통해 흘러 들어왔을 수도 있겠지.",
  ui_story_5083_50831301_8_dialog_content = "으음, 이 암귀들을 소탕하고 나면 감시를 강화해야겠군. 실수는 절대 있어선 안 된다.",
  ui_story_5083_50831301_9_dialog_content = "부대를 하나 더 파견해 놈들의 흔적을 조사하도록.",
  ui_story_5083_50831301_10_dialog_content = "전황이 격화되고 있는 관계로, 주변 방어를 맡고 있는 1군단은 인원을 차출할 여유가 없습니다.",
  ui_story_5083_50831301_11_dialog_content = "암귀가 갑자기 땅에서 솟아날 리도 없지 않습니까!\n제대로 대비하지 않으면 우린 이 안일함 때문에 전부 죽게 될 겁니다!",
  ui_story_5083_50831301_12_dialog_content = "1군단에서 동원이 힘들다면, 추적 임무는 저희 군단에서 맡겠습니다.",
  ui_story_5083_50831301_13_dialog_content = "제 휘하엔 아직 2개 대대 규모의 병력이 남아 있습니다.\n마침 실전 경험도 쌓게 하면 좋지 않겠습니까.",
  ui_story_5083_50831301_14_dialog_content = "좋다. 대신 전황이 어려운 만큼, 조금의 손실도 있어서는 안 된다.",
  ui_story_5083_50831301_15_dialog_content = "죄송하지만 여러분은 제가 아직 여기 있다는 걸 잊으신 모양이군요.\n바튼 대대장과 휘하의 병사들은 반드시 위원회의 업무에 협조해야만 합니다. 이건 명령입니다.",
  ui_story_5083_50831301_16_dialog_content = "난 대원수님께 명령을 내려 달라고 청하는 중이다. 너희와는 아무 상관도 없단 말이다.",
  ui_story_5083_50831301_17_dialog_content = "실례했습니다. 하지만 위원회의 명령을 전달하고, 일루미나의 모든 걸 위원회에\n있는 그대로 보고하는 게 제 일입니다. 여러분의 회의를 비롯해서 말이지요.",
  ui_story_5083_50831301_18_dialog_content = "어이, 위원회 따까리, 자난성을 지키고 있는 건 우리다. 기어오르지 마라.",
  ui_story_5083_50831301_19_dialog_content = "...바튼과 더글라스가 위원회의 선전 활동에 협조해야 한다면,\n자난성을 떠나지 않는 게 좋겠군.",
  ui_story_5083_50831301_20_dialog_content = "팡고, 1개 대대와 네 직속 부대를 데리고 네가 직접 가 줬으면 한다.",
  ui_story_5083_50831301_21_dialog_content = "알겠습니다. 하지만 제 부관도 전사한 마당에, 우수한 부하 둘을 여기 두고 썩히라니,\n이게 말이 되는 처사입니까?!",
  ui_story_5083_50831301_22_dialog_content = "그러니 내가 진작에 경고하지 않았나... 팡고, 이게 그 결과다.",
  ui_story_5083_50831301_23_dialog_content = "...더글라스를 데려가라.\n녀석이 올린 증원 요청은 내가 직접 승인했으니, 그 정도쯤은 보장해 주마.",
  ui_story_5083_50831301_24_dialog_content = "이건 나 루거가 내리는 명령이다. 위원회의 비서, 내 말을 똑똑히 기록해 둬라.",
  ui_story_5083_50831301_25_dialog_content = "...그래서 이렇게 된 거다.\n아무래도 안심이 안 되니, 내가 직접 암귀들의 근원지를 조사하러 가야겠다.",
  ui_story_5083_50831301_26_dialog_content = "바튼, 이번엔 일단 남아라. 계속해서 병사들을 확실하게 훈련시켜라.",
  ui_story_5083_50831301_27_dialog_content = "그럴 순 없습니다. 아무래도 감이 안 좋습니다.",
  ui_story_5083_50831301_28_dialog_content = "「전위대의 두 방패」 역할을 하는 지하성 두 곳이 자기 사명을 다했는데,\n어떻게 이럴 때 자난성 근처에 암귀가 접근할 수 있다는 겁니까?",
  ui_story_5083_50831301_29_dialog_content = "전에도 종종 발생하던 일이야. 다만 지금은 평소보다 전황이 더 격화된 탓에,\n1군단이 미처 대응하지 못하는 틈을 암귀들이 노린 것뿐이겠지.",
  ui_story_5083_50831301_30_dialog_content = "그래서 넌 지금 돌아가는 상황이 안 이상해?",
  ui_story_5083_50831301_31_dialog_content = "위원회 놈들은 날 한참이나 자난성에 붙잡아 놓고, 작전에도 참여시키지 않고 있어.\n격전이 이어지는 와중에도 오히려 나 대신 군단장님과 더그 널 보내고 말이야.",
  ui_story_5083_50831301_32_dialog_content = "난 이젠 대원수님한테도 무슨 속셈이 있는 건 아닌지 걱정될 정도라고...",
  ui_story_5083_50831301_33_dialog_content = "말조심해라! 처박혀 있는 동안 더 멍청해지기라도 한 거냐?\n우리 일루미나의 신조마저 잊어버렸냔 말이다!",
  ui_story_5083_50831301_34_dialog_content = "네 눈은 지금 반역의 불꽃으로 가득 차 있다. 그게 네가 품고 있던 영광조차 싹 태워버린 거냐?",
  ui_story_5083_50831301_35_dialog_content = "당장 이리 와, 이 자식아!",
  ui_story_5083_50831301_36_dialog_content = "봐라! 저 빛을 똑바로 보란 말이다! 중앙 탑의 불은 단 한 번도 꺼진 적이 없었다.\n저 빛이 널 키웠다. 그러니 너도 저 빛을 지켜야만 하는 거다!",
  ui_story_5083_50831301_37_dialog_content = "네가 상부에 어떤 불만이 있든, 이거 하나는 기억해라. 넌 영원히 일루미나인이다.",
  ui_story_5083_50831301_38_dialog_content = "아니, 전 그저 군단장님이 걱정됐을 뿐이라고요...",
  ui_story_5083_50831301_39_dialog_content = "그럼 네 병사들이나 잘 훈련시켜라.\n네 개인의 불만을 일루미나의 대의보다 우선시하지 말란 말이다.",
  ui_story_5083_50831301_40_dialog_content = "일루미나의 대원수는 멍에가 씌워져 있고, 그래서 약해 보일 지도 모른다...\n그렇지만 전우를 팔아먹는 소인배는 절대 아니다.",
  ui_story_5083_50831301_41_dialog_content = "다시는 우리의 동포를 모욕하는 말을 하지 마라!",
  ui_story_5083_50831301_42_dialog_content = "그래도... 그럼 저라도 데려가십쇼! 도저히 마음이 안 놓이니 절 데려가시란 말입니다...",
  ui_story_5083_50831301_43_dialog_content = "그만해, 바튼. 군단장님도 원래는 그러려고 하셨을 거야.",
  ui_story_5083_50831301_44_dialog_content = "그래도 내가 같이 가니까 걱정하지 마.\n혹시라도 정말 교전이 발생하면, 바로 지원을 요청해서 널 부를 테니까.",
  ui_story_5083_50831301_45_dialog_content = "그럼 저쪽에서도 널 더 붙잡아 둘 순 없겠지.",
  ui_story_5083_50831301_46_dialog_content = "......",
  ui_story_5083_50831301_47_dialog_content = "네가 너보다 못난 것도 아닌데, 뭘 그렇게 걱정하고 있어? 휴...",
  ui_story_5083_50831301_48_dialog_content = "기다리고 있어, 바튼. 내가 언제까지 2인자만 하진 않을 거니까.\n너도 사람 무시하는 나쁜 버릇도 좀 고치고.",
  ui_story_5083_50831301_49_dialog_content = "젠장, 가슴이 답답해. 자꾸 무슨 일이 생길 것만 같다고.",
  ui_story_5083_50831301_50_dialog_content = "기분 더럽네 진짜. 이 불안감은 대체 뭐냔 말이야...",
  ui_story_5083_50831301_51_dialog_content = "삐삑, 바튼 씨, 새로운 메시지가 도착했어요.",
  ui_story_5083_50831301_52_dialog_content = "알 수 없는 발신자로부터 다음 메시지를 수신했습니다.\n「라인하르트가 연구소 사고에 휘말렸어. 사람들을 구하다 현장에서 정신을 잃고 쓰러졌다구.」",
  ui_story_5083_50831301_53_dialog_content = "......?",
  ui_story_5083_50831301_54_dialog_content = "「미안, 내가 너무 자만했어... 제공된 파라미터에 오류가 있을 줄은 몰랐어...\n□□□가... 위험...」",
  ui_story_5083_50831301_55_dialog_content = "「내가 책임질게... 치료하는 동안 □□□...\n라인하르트는 드니에르가 간호하고 있어... 걱정 마...」",
  ui_story_5083_50831301_56_dialog_content = "오류, 도청 시도가 감지되어 신호가 중단됐어요.",
  ui_story_5083_50831301_57_dialog_content = "그로누...? 뭐가 어떻게 된 거지? 대체 무슨 일이 벌어진 거야?",
  ui_story_5083_50831301_58_dialog_content = "메시지의 발신원이 여러 겹으로 암호화돼 있어 추적이 불가능해요.",
  ui_story_5083_50831301_59_dialog_content = "안 되겠어... 상황이 내가 이해할 수 없는 방향으로 흘러가고 있어.",
  ui_story_5083_50831301_60_dialog_content = "라인하르트는 무슨 일에 휘말린 거지? 그로누는 또 어떻게 된 거야?\n게다가 멀쩡한 통신이 왜 도청을 당하는 거냐고...",
  ui_story_5083_50831301_61_dialog_content = "내가 모르는 곳에서 지금 대체 무슨 일들이 벌어지고 있는 거지?\n빌어먹을, 심장을 쥐어짜는 불안감이 갈수록 심해지고 있어...",
  ui_story_5083_50831301_62_dialog_content = "삐삑, 바튼 씨, 지금 즉시 휴식을 취하고 감정을 가라앉히세요.",
  ui_story_5083_50831301_63_dialog_content = "아니, 지금은 쉴 때가 아냐!",
  ui_story_5083_50831301_64_dialog_content = "이대로 가만히 있을 순 없어.",
  ui_story_5083_50831301_65_dialog_content = "바튼 씨...",
  ui_story_5083_50831301_66_dialog_content = "지금 당장 출발해서 군단장님과 더그를 따라잡아야겠어.",
  ui_story_5083_50831301_67_dialog_content = "하지만 바튼 씨는 명령을 받지 않았어요.",
  ui_story_5083_50831301_68_dialog_content = "지금 그런 거 따질 때가 아니잖아!",
  ui_story_5083_50831301_69_dialog_content = "아무것도 하지 않을 바에야, 차라리 계속 잘못을 저지르는 게 나아!",
  ui_story_5083_50831301_70_dialog_content = "다 저놈의 빛 때문이라고... 망할 꼰대가! 우리는 반드시 저 빛이 빛나도록 지켜야 해...\n그러니까 이렇게 멍청하게 계속 앞으로 달려 나가는 거라고!",
  ui_story_5083_50831301_71_dialog_content = "무슨 일이 벌어지든 상관없어. 난 그 누구도 위험에 빠지게 둘 순 없으니까!",
  ui_story_5083_50831301_72_dialog_content = "병사들! 전원 집합!",
  ui_story_5083_50831301_73_dialog_content = "대대장님, 교전 흔적을 발견했습니다.\n군단장님은 연락이 끊기기 전까지 여기서 암귀와 전투를 치르신 것 같습니다.",
  ui_story_5083_50831301_74_dialog_content = "하지만 전장의 규모가 상당히 큰 것으로 보아, 소규모 암귀 무리일 가능성은 없습니다.\n군단장님은 퇴각하신 것으로 보입니다.",
  ui_story_5083_50831301_75_dialog_content = "서둘러! 흔적을 따라가! 지형을 파악하고 수송대가 움직일 수 있게 길을 확보해!",
  ui_story_5083_50831301_76_dialog_content = "아직 늦지 않았어... 분명히 괜찮을 거야...",
  ui_story_5083_50831302_1_dialog_content = "좀 어떠냐.",
  ui_story_5083_50831302_2_dialog_content = "안 됩니다. 통신이 아직도 먹통입니다.\n이건 암귀들이 다룰 법한 기술이 아닌데, 뭔가 이상합니다.",
  ui_story_5083_50831302_3_dialog_content = "군단장님, 아무래도 포위당한 것 같습니다.",
  ui_story_5083_50831302_4_dialog_content = "병사들은?",
  ui_story_5083_50831302_5_dialog_content = "...후미를 맡은 동포 200명 중 귀환한 건 20명뿐입니다.\n제 돌격대대도 병력의 3분의 1을 잃었습니다.",
  ui_story_5083_50831302_6_dialog_content = "...이 암귀들은 우리가 예상했던 것보다 수가 너무 많다.\n전황은 이미 통제 불능 상태가 돼 버렸다.",
  ui_story_5083_50831302_7_dialog_content = "방어선의 주요 지점 중 습격을 받고 놈들 손에 떨어진 지하성이 있을지도 모른다.\n그래서 이런 사태가 벌어진 거겠지.",
  ui_story_5083_50831302_8_dialog_content = "...아니면, 누군가 일루미나를...\n어쨌든, 빠져나가실 수 있게 제가 돌격대를 데리고 길을 뚫겠습니다.",
  ui_story_5083_50831302_9_dialog_content = "반드시 자난성에 이 정보를 가지고 돌아가서, 더 큰 피해를 막아야 합니다.",
  ui_story_5083_50831302_10_dialog_content = "그럴 순 없다. 이 주변엔 1군단의 외부 기지를 비롯해, 아직 회수하지 못한 설비가 많다.\n난 이대로 무책임하겐 못 떠난다.",
  ui_story_5083_50831302_11_dialog_content = "하지만...",
  ui_story_5083_50831302_12_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5083_50831302_13_dialog_content = "무슨 일이야? 암귀의 공격인가?!",
  ui_story_5083_50831302_14_dialog_content = "다들 괜찮냐?! 군단장님은? 군단장님은 어디 계시냐!",
  ui_story_5083_50831302_15_dialog_content = "이 자식아! 왜 멋대로 튀어나온 거냐!",
  ui_story_5083_50831302_16_dialog_content = "무사하셨군요... 아무튼 지금 그런 걸 따질 때가 아닙니다!",
  ui_story_5083_50831302_17_dialog_content = "뭐, 그래도 마침 잘 오긴 했다. 오면서 암귀는 봤냐?",
  ui_story_5083_50831302_18_dialog_content = "제 기계화부대가 이미 놈들의 전선을 돌파했습니다...\n오는 길에 1군단 경비부대가 있길래, 그쪽에도 상황을 전달해 뒀습니다.",
  ui_story_5083_50831302_19_dialog_content = "아직 회수하지 못한 설비들이 있어. 바튼, 운송 차량을 얼마나 나눠 줄 수 있어?\n최대한 신속하게 회수 임무를 수행해야 해!",
  ui_story_5083_50831302_20_dialog_content = "차량이야 문제없지... 근데 대체 어떻게 된 거야? 통신 신호도 전혀 안 잡힌다고.",
  ui_story_5083_50831302_21_dialog_content = "이미 구조 신호를 보내긴 했어.",
  ui_story_5083_50831302_22_dialog_content = "신호탄 가지고는 초소 쪽 병사들 정도밖에 못 볼 거야.\n초소에 자난성까지 신호를 보낼 만한 장비가 있을진 모르겠어.",
  ui_story_5083_50831302_23_dialog_content = "...괜찮아, 네가 1군단 경비부대에 알렸으니까.\n이젠 그쪽에서 지원 병력을 데려와 주길 바랄 수밖에.",
  ui_story_5083_50831302_24_dialog_content = "큰일입니다! 밖에 암귀들이 집결해 물량공세로 포격을 돌파하려고 합니다!",
  ui_story_5083_50831302_25_dialog_content = "그리고 <color=#FFB400>초대형 암귀</color>를 포착했습니다!\n현재 이곳을 향해 접근 중입니다. 지금 당장 이동해야 합니다!",
  ui_story_5083_50831302_26_dialog_content = "<color=#FFB400>초대형 암귀</color>? 소문으로 듣던 그 <color=#FFB400>공성 암귀</color>인가?",
  ui_story_5083_50831302_27_dialog_content = "중화기가 부족하면 그런 암귀는 처치하기 힘들 텐데...",
  ui_story_5083_50831302_28_dialog_content = "전차소대를 둘로 나눠라. 하나는 퇴로를 열고, 다른 하나는 전방을 막도록 해라!",
  ui_story_5083_50831302_29_dialog_content = "그리고 장갑차 10대를 차출해 차량마다 돌격병을 4명씩 태우도록.\n퇴로가 열리면 즉시 빠져나가 자난성 주변의 모든 지상 설비를 회수해라.",
  ui_story_5083_50831302_30_dialog_content = "예!",
  ui_story_5083_50831302_31_dialog_content = "<color=#e8d9bb>포화의 울림이 전투의 시작을 알렸다.\n그러나 연이은 폭격 속에서도 끊임없이 들려오는 기묘한 「종소리」는 다른 모든 소리를 압도했다.</color>",
  ui_story_5083_50831302_32_dialog_content = "더그, 따라와! 내가 널 태우고 돌진할 테니까, 우리가 저 초대형 암귀의 숨통을 끊는 거야!",
  ui_story_5083_50831302_33_dialog_content = "내 수송대가 19호 지하성에서 요새포를 뜯어 왔어. 위력이 굉장하다고!",
  ui_story_5083_50831302_34_dialog_content = "아서라!",
  ui_story_5083_50831302_35_dialog_content = "너희 둘은 가라. 나와 내 소대가 남겠다.",
  ui_story_5083_50831302_36_dialog_content = "이건 계획된 포위 공격이고, 놈들의 목표는 우리가 아니다...\n저 개자식들의 목표는 자난성이란 말이다!",
  ui_story_5083_50831302_37_dialog_content = "저 정도 규모는 너희같이 머리에 피도 안 마른 녀석들은 절대 감당 못 한다.",
  ui_story_5083_50831302_38_dialog_content = "지금 당장 퇴각하고, 자난성에 이 소식을 알려라! 빠르면 빠를수록 좋다!",
  ui_story_5083_50831302_39_dialog_content = "이 와중에 대체 뭔 소립니까 그게?! 저희가 이럴 때 군단장님을 내버려두고 갈 놈들입니까?!",
  ui_story_5083_50831302_40_dialog_content = "적의 규모가 클수록 더욱더 모두 함께 단결해서 돌파해야 합니다.",
  ui_story_5083_50831302_41_dialog_content = "난 갈 수가 없단 말이다! 저 <color=#FFB400>종소리</color>가 들리냐? 저놈이 13호 지하성을 파괴한 원흉이다.\n저게 바로 그 「어둠의 밑바닥의 악령」이라고.",
  ui_story_5083_50831302_42_dialog_content = "그림자 전투 때도 저 종소리가 암귀들을 이끌고 우리의 방어선을 무너트렸다.",
  ui_story_5083_50831302_43_dialog_content = "더 꾸물대다간 아무도 여길 빠져나가지 못해!",
  ui_story_5083_50831302_44_dialog_content = "하지만...!",
  ui_story_5083_50831302_45_dialog_content = "어서 가란 말이다!",
  ui_story_5083_50831302_46_dialog_content = "군단장님을 두고 갈 순 없습니다! 군단장님은 제게... 단순한 상관이 아니잖습니까...\n그러니 함께 있게 해 주십시오.",
  ui_story_5083_50831302_47_dialog_content = "...알고 있다.",
  ui_story_5083_50831302_48_dialog_content = "그러니까 하는 소리다... 부모보다 자식이 먼저 가는 일은 있어선 안 될 일이다.",
  ui_story_5083_50831302_49_dialog_content = "더그, 난 이미 자식을 하나 잃었다. 너희마저 잃을 순 없다.",
  ui_story_5083_50831302_50_dialog_content = "구, 군단장님...",
  ui_story_5083_50831302_51_dialog_content = "...망할...",
  ui_story_5083_50831302_52_dialog_content = "군단장님의 뜻은... 잘 알겠습니다.",
  ui_story_5083_50831302_53_dialog_content = "알았으면 얼른 꺼져! 쓸데없이 걱정 끼치지 말고 빨리 썩 꺼지란 말이다!",
  ui_story_5083_50831302_54_dialog_content = "너희 둘만 없으면, 나도 마음 놓고...",
  ui_story_5083_50831302_55_dialog_content = "더그! 너 이 자식 무슨 짓이야?!",
  ui_story_5083_50831302_56_dialog_content = "군단장님... 아니, 「아버지」는 너한테 맡길게. 돌격대대가 길을 열어 줄 테니까.",
  ui_story_5083_50831302_57_dialog_content = "그게 뭔 소리냐고! 이런 상황에서 되도 않는 폼이라도 잡겠다는 거야?!",
  ui_story_5083_50831302_58_dialog_content = "난 항상 널 질투했어, 바튼...",
  ui_story_5083_50831302_59_dialog_content = "같은 「첨예탄」이지만, 넌 나보다 늘 반 발짝 앞서고, 난 언제나 「만년 2인자」 같았거든.",
  ui_story_5083_50831302_60_dialog_content = "지금 그런 얘기 할 때가 아니잖아! 생각 없이 굴지 마!",
  ui_story_5083_50831302_61_dialog_content = "그냥 계속 들어 줘! 난 네가 늘 나보다 강한 걸 질투했고, 네가 늘 앞서 나가는 걸 질투했고,\n네가 군단장님한테 총애받는 걸 질투했어...",
  ui_story_5083_50831302_62_dialog_content = "하지만... 넌 언제나 주저하는 법 없이... 모두를 데리고 앞으로 나아갔어...",
  ui_story_5083_50831302_63_dialog_content = "그리고 난... 너한테서 진정한 「탄환」이 지녀야 할, 기나긴 밤을 헤쳐 나갈 힘을 봤어.",
  ui_story_5083_50831302_64_dialog_content = "넌 나보다 결단력 있는 녀석이야. 아마도 난 평생 네 부관밖에 못 되겠지.",
  ui_story_5083_50831302_65_dialog_content = "정말 다행이라고 생각해. 이렇게 열심히 노력해서... 너한테 겨우 반밖에 안 뒤처졌잖아...",
  ui_story_5083_50831302_66_dialog_content = "덕분에 나도 너처럼 이렇게 많은 암귀를 막고, 모두를 집으로 보낼 길을 열어 줄 수 있게 됐어.",
  ui_story_5083_50831302_67_dialog_content = "<color=#e8d9bb>「종소리」가 다가오자, 주변의 포화 소리는 점점 약해지기 시작했고,\n방어선은 규모를 줄이며 점점 뒤로 물러나, 퇴로를 뚫을 준비에 들어갔다.</color>",
  ui_story_5083_50831302_68_dialog_content = "빌어먹을... 이래서야 죽는 사람만 바뀐 꼴이잖아! 나도 남아서 널 도울게!",
  ui_story_5083_50831302_69_dialog_content = "사람은 누구나 다 죽어. 그건 우리가 총을 처음 쥐었을 때부터 각오하고 있던 거잖아?",
  ui_story_5083_50831302_70_dialog_content = "하지만 군단의 미래, 그리고 일루미나의 미래를 위해,\n너 같은 사람은 절대로 이딴 곳에서 죽어선 안 돼.",
  ui_story_5083_50831302_71_dialog_content = "내가 널 위해서 가장 멋진 지원 공세를 펼칠 테니까,\n내가 뚫어 준 길로 나가서 마음껏 네 역량을 발휘해 줘.",
  ui_story_5083_50831302_72_dialog_content = "일루미나의 미래는 너희한테 달렸어.",
  ui_story_5083_50831302_73_dialog_content = "...그런 멍청한 소리 좀 집어치워... 우린 아직 전차부대도 있잖아...",
  ui_story_5083_50831302_74_dialog_content = "내가 너한테 해 줬던 얘기 아직 기억해? 군단장님은 나 때문에 아내와 자식을 잃으셨어.",
  ui_story_5083_50831302_75_dialog_content = "그래서 난 늘 생각했어. 나한테 그 고귀한 희생을 치를 만큼의 가치가 있었을까 하고 말이야.",
  ui_story_5083_50831302_76_dialog_content = "예전의 난 항상 죄책감에 빠져 살았어.\n많은 순간마다 내가 이미 과거에 파묻혀 죽었다고 생각했고.",
  ui_story_5083_50831302_77_dialog_content = "이 등신아... 네가 그때 죽었으면... 누가 내 라이벌이 돼 주고...\n날 성장시켜 줬겠냐...",
  ui_story_5083_50831302_78_dialog_content = "맞아, 네가 네 새로운 꿈을 말해 줬을 때 난 느꼈어...\n그 순간, 내 심장은 네 꿈을 위해 다시 뛰기 시작했거든.",
  ui_story_5083_50831302_79_dialog_content = "비록 이성은 날 네 꿈에 반대하게 만들었고, 널 반박하고 싶게 만들었지만...\n난... 네가 그린 그 미래를 위해서라면 기꺼이 죽을 수 있어.",
  ui_story_5083_50831302_80_dialog_content = "그러니까 우리한테 기회를 줘, 바튼. 우린 그냥 죽으러 가는 게 아니라...\n일루미나의 대의를 위해 다시 태어나려는 거야.",
  ui_story_5083_50831302_81_dialog_content = "보고드립니다! 전차소대가 임무를 성공적으로 완수해 퇴로가 열렸습니다!",
  ui_story_5083_50831302_82_dialog_content = "하지만 초대형 암귀가 이미 도착해 진형 유지에 어려움이 있습니다!\n이대로라면 순조롭게 퇴각하기 어렵습니다!",
  ui_story_5083_50831302_83_dialog_content = "명령을 전달해라. 돌격대대 전원은 이곳에 남아서, 동포들을 위해 퇴로를 사수한다!",
  ui_story_5083_50831302_84_dialog_content = "...기계화부대는 들어라. 탄약은 최대한 돌격대대에 남겨 준다!\n그리고... 우리는 나머지 인원을 데리고 자난성으로 철수한다!",
  ui_story_5083_50831302_85_dialog_content = "바튼, 넌 내 형제이자 적이었고, 악몽이자... 내가 2인자로 남는 보람이었어.",
  ui_story_5083_50831302_86_dialog_content = "...그리고 난 네가 왕이 되어야 할 이유야!",
  ui_story_5083_50831302_87_dialog_content = "이거 받아. 그리고... 가.",
  ui_story_5083_50831302_88_dialog_content = "...내가 지원군을 데리고 돌아올 때까지 기다려! 전우들과 함께 살아남아!",
  ui_story_5083_50831302_89_dialog_content = "일루미나의 애송이, 날 막아설 생각은 마라!",
  ui_story_5083_50831302_90_dialog_content = "전우들은 들어라! 돌격대대 창설의 의미가 지금 우리의 눈앞에 있다! 우린 함께 싸울 것이다!\n<size=45>돌격하라!</size>",
  ui_story_5083_50831302_91_dialog_content = "<color=#e8d9bb>더그가 비장한 군가를 부르며 발걸음을 내딛자, 모든 돌격병도 목청껏 군가를 따라 부르며\n물밀듯 몰려오는 적을 향해 돌격했다.</color>",
  ui_story_5083_50831302_92_dialog_content = "<size=45>죽음을 자초하는구나.</size>",
  ui_story_5083_50831302_93_dialog_content = "신성이여! 힘껏 날아올라라! 꿈이 실현되기 전까지 멈추지 마라!",
  ui_story_5083_50831302_94_dialog_content = "가... 바튼, 더 위대한 모든 것들을 짊어지고 나아가 줘...",
  ui_story_5083_50831400_1_dialog_content = "<color=#e8d9bb>제1군단 경비부대가 제2군단 돌격대대의 전멸 소식을 가지고 돌아왔다.\n그들은 암귀 군단을 격퇴했지만, 자신들의 목숨을 평원에 남기고 말았다.</color>",
  ui_story_5083_50831400_2_dialog_content = "<color=#e8d9bb>최고 동원령의 선포와 함께 자난성에 경보음이 울려 퍼졌고,\n모든 전사가 동원되어 곧 다가올 암귀 군단에 맞설 준비를 갖추었다.</color>",
  ui_story_5083_50831400_3_dialog_content = "너무 늦었다고! 대대 하나가 허망하게 희생됐는데, 이제야 땜질을 하겠다는 거냐?!",
  ui_story_5083_50831400_4_dialog_content = "중령님, 여긴 수뇌부 회의실입니다. 물러서 주십시오.",
  ui_story_5083_50831400_5_dialog_content = "대원수님과 군 수뇌부가 후속 대책을 논의 중이십니다.\n계속 방해하려 하신다면, 저희도 가만히 있을 순 없습니다.",
  ui_story_5083_50831400_6_dialog_content = "쏴.",
  ui_story_5083_50831400_7_dialog_content = "중령님! 물러서십시오!",
  ui_story_5083_50831400_8_dialog_content = "방아쇠 당길 배짱도 없으면 나한테 그딴 거 겨누지 마라.",
  ui_story_5083_50831400_9_dialog_content = "야 임마, 왜 같은 편한테 소리를 지르고 앉았어?",
  ui_story_5083_50831400_10_dialog_content = "당장 이리 와! 대원수님 회의실 앞에서 쪽팔리게 설치지 말고!",
  ui_story_5083_50831400_11_dialog_content = "군단장님... 이, 일어나셨습니까...?",
  ui_story_5083_50831400_12_dialog_content = "대원수님, 충성!",
  ui_story_5083_50831400_13_dialog_content = "......",
  ui_story_5083_50831400_14_dialog_content = "아 좀! 막지 마십쇼! 이유라도 들어야겠으니까!",
  ui_story_5083_50831400_15_dialog_content = "대체 왜 처음부터 2개 대대를 보내지 않은 겁니까?\n왜 처음부터 기계화부대를 못 데려가게 했냔 말입니다!",
  ui_story_5083_50831400_16_dialog_content = "처음부터 차량만 있었으면 거기 발이 묶일 일도 없었잖습니까...!",
  ui_story_5083_50831400_17_dialog_content = "진정 좀 해라!",
  ui_story_5083_50831400_18_dialog_content = "더그랑 부하들이 전부 죽었는데... 지금 저보고 진정하란 말이 나옵니까?!",
  ui_story_5083_50831400_19_dialog_content = "군단장님이 사람을 잘못 믿으신 겁니다! 전략적인 안목? 저놈들은 그딴 거 하나도 없습니다!\n하나같이 뒤가 구린 놈들뿐이고, 저놈들 때문에 더그랑 그 많은 부하들이 개죽음을 당한 겁니다!",
  ui_story_5083_50831400_20_dialog_content = "놈들은 우릴 노리고 있습니다... 근데 왜 정작 절 내버려둔답니까?",
  ui_story_5083_50831400_21_dialog_content = "저 빌어먹을 놈들이 왜 절 내버려두냔 말입니다!",
  ui_story_5083_50831400_22_dialog_content = "그만 좀 설쳐라! 2군단 얼굴에 먹칠을 해도 정도가 있지.\n네가 이러면 무슨 낯짝으로 더그를 보겠다는 거냐!",
  ui_story_5083_50831400_23_dialog_content = "네가 멋대로 부대를 끌고 자난성을 나간 것도 벌써 두 번째다!\n징계 안 먹은 것만 해도 대원수님이 충분히 배려하신 거란 말이다.",
  ui_story_5083_50831400_24_dialog_content = "대원수님 때문에... 더그가 죽었습니다...!",
  ui_story_5083_50831400_25_dialog_content = "이게 다 누구 때문인데...!",
  ui_story_5083_50831400_26_dialog_content = "...더그는 대원수의 외아들이었다.",
  ui_story_5083_50831400_27_dialog_content = "...뭐요...? 지금... 저랑 장난하십니까?",
  ui_story_5083_50831400_28_dialog_content = "...따라와라.",
  ui_story_5083_50831400_29_dialog_content = "루거와 난 오랜 전우 사이였다. 루거가 대원수 취임을 앞두고 있을 때...\n당시 임신 중이었던 루거의 아내가 최전방의 지하성에 갇혀 버리고 말았다.",
  ui_story_5083_50831400_30_dialog_content = "난 병사들을 이끌고 지하성으로 향했지만, 이미 한발 늦었더군.\n지하성은 함락당한 상태였고, 공식적으로는 생존자가 없는 것으로 기록되었다.",
  ui_story_5083_50831400_31_dialog_content = "하지만 내가 시신을 수습할 때...\n루거의 아내 품에서 울지도 않고 조용히 안겨 있던 더그를 발견했지.",
  ui_story_5083_50831400_32_dialog_content = "그 처참한 환경에서 어떻게 아이를 낳고, 그 아이의 목숨을 지켰는지는 모르겠다.\n하지만... 그건 분명 기적이었다.",
  ui_story_5083_50831400_33_dialog_content = "난 아직도 더그를 데려왔을 때 루거가 지었던 비통한 표정을 잊을 수가 없다.\n루거는 아내를 정말로 사랑했지만, 군인으로서의 본분도 저버릴 수 없었지.",
  ui_story_5083_50831400_34_dialog_content = "아무도 그 아이의 탄생을 몰랐기 때문에, 루거는 그 아이를 나한테 맡겼다.\n루거는 이미 그때부터 뭔가 염려가 되었는지, 마음 쓰이는 일 없이 전투에 임하길 원했다.",
  ui_story_5083_50831400_35_dialog_content = "말도 안 돼...",
  ui_story_5083_50831400_36_dialog_content = "이건 사실이다. 그리고 6년 전, 내가 지키던 지하성이 적의 침입을 받았고,\n관례대로 인구 조사를 하던 중 더그의 존재가 위원회에 노출됐다.",
  ui_story_5083_50831400_37_dialog_content = "그 일과 관계가 있는진 모르겠지만, 루거는 그 뒤로 우유부단해졌고,\n우린 점차 다른 길을 걷게 됐지.",
  ui_story_5083_50831400_38_dialog_content = "대원수가 된 후로 루거는 굉장히 강해졌지만, 정작 결정을 내릴 땐 더 보수적으로 변했다.",
  ui_story_5083_50831400_39_dialog_content = "루거가 그렇게 변한 이유는 나도 모르겠다...\n하지만 적어도 일루미나를 위하는 그의 마음은 내 목숨을 걸 만큼 믿을 수 있다.",
  ui_story_5083_50831400_40_dialog_content = "설령... 루거의 마음속 여명의 빛이 이젠 정말 흐려졌다고 할지라도,\n자기 아들을 해칠 위인은 절대 아니야.",
  ui_story_5083_50831400_41_dialog_content = "...그 멍청한 놈한테도 자기 아버지가 누군지 말해 주셨습니까?",
  ui_story_5083_50831400_42_dialog_content = "물론이지.",
  ui_story_5083_50831400_43_dialog_content = "그때... 나랑 다른 비전투인원들을 대피시키기 위해 아내분과 아드님이 자신을 희생했어.",
  ui_story_5083_50831400_44_dialog_content = "그래서 난 늘 생각했어. 나한테 그 고귀한 희생을 치를 만큼의 가치가 있었을까 하고 말이야.",
  ui_story_5083_50831400_45_dialog_content = "그 멍청한 녀석은... 계속 자기 출신 때문에 죄책감을 느끼고 있었습니다...",
  ui_story_5083_50831400_46_dialog_content = "...그래서... 난 더그한테 그 이야기를 해 준 걸 진심으로 후회했다.",
  ui_story_5083_50831400_47_dialog_content = "......",
  ui_story_5083_50831400_48_dialog_content = "서둘러! 가져갈 수 있는 만큼 모래주머니를 전부 채워!\n뒤쪽 차량, 잠깐 멈춰! 우린 전선으로 향하는 1군단 부대다!",
  ui_story_5083_50831400_49_dialog_content = "라인하르트?",
  ui_story_5083_50831400_50_dialog_content = "다행이네, 퇴원한 거냐?",
  ui_story_5083_50831400_51_dialog_content = "하하, 퇴원한 지는 한참 됐어.\n그것보다, 일루미나가 위기에 처했는데, 넌 왜 여기서 빈둥대고 있어?",
  ui_story_5083_50831400_52_dialog_content = "중령님, 전부 다 실었습니다. 그럼 저희 먼저 출발하겠습니다.",
  ui_story_5083_50831400_53_dialog_content = "그래! 조심히 다녀와라.",
  ui_story_5083_50831400_54_dialog_content = "음... 인원이 아직 부족해. 이대로는 군단장님 쪽도 곤란해지겠어...",
  ui_story_5083_50831400_55_dialog_content = "너... 왠지 좀 변한 것 같은데...",
  ui_story_5083_50831400_56_dialog_content = "그래? 아무튼, 난 지금 동원 중이라, 중요한 일 아니면 이야기는 나중에 하자.",
  ui_story_5083_50831400_57_dialog_content = "어이, 아니, 라인하르트, 너...",
  ui_story_5083_50831400_58_dialog_content = "우리가 전에 얘기했던 일, 설마 잊은 건 아니겠지?",
  ui_story_5083_50831400_59_dialog_content = "위원회가 너한테 무슨 짓을 한 거야?",
  ui_story_5083_50831400_60_dialog_content = "내가 중령으로 진급한 일 말하는 건가?",
  ui_story_5083_50831400_61_dialog_content = "그게 아니잖아! 너, 어째서...",
  ui_story_5083_50831400_62_dialog_content = "네가 무슨 말을 하려는 건지는 나도 알아. 위원회에 대해 불만이 있더라도 일단은 참아.\n지금은 중요한 시기니까 모든 건 전황을 우선으로 생각해야 해.",
  ui_story_5083_50831400_63_dialog_content = "자, 난 군단장님께 보고드리러 가야 하니까 대화는 이쯤하자.\n지금 넌 조금 혼란스러울 수도 있겠지만, 그래도 기운 내라. 넌 일루미나의 영웅이잖아.",
  ui_story_5083_50831400_64_dialog_content = "하하하하하... 「일루미나의 영웅」? 그럼 돌아오지 못한 더그와 전우들은 뭐냔 말이다.",
  ui_story_5083_50831400_65_dialog_content = "...위원회는 누가 영웅인지 판단할 자격은 없어!",
  ui_story_5083_50831400_66_dialog_content = "라인하르트... 너...",
  ui_story_5083_50831400_67_dialog_content = "삐삑, 바튼 씨, 절 따라오세요...",
  ui_story_5083_50831400_68_dialog_content = "다행이야, 내 「조종사」... 적어도 넌 바뀐 게 없구나...",
  ui_story_5083_50831400_69_dialog_content = "그래, 가자... 네가 날 어디로 데려가든... 지금보다 더 나쁘진 않겠지...",
  ui_story_5083_50831400_70_dialog_content = "기념비잖아... 더그와 전우들의 이름이... 벌써 새겨진 건가.",
  ui_story_5083_50831400_71_dialog_content = "삐삑, 바튼 씨, 저길 보세요...",
  ui_story_5083_50831400_72_dialog_content = "<color=#e8d9bb>우뚝 솟은 기념비 아래, 한 구부정한 그림자 하나가 빛 속에 멍하니 서 있었다.\n남자는 무표정한 얼굴로 기념비에 새겨진 이름을 바라봤다.</color>",
  ui_story_5083_50831400_73_dialog_content = "(대원수...)",
  ui_story_5083_50831400_74_dialog_content = "(더그의 진짜 <color=#FFB400>아버지</color>...)",
  ui_story_5083_50831400_75_dialog_content = "<color=#e8d9bb>바튼은 한동안 그 자리에서 망설이며, 앞으로 나아가려다 말기를 몇 번이나 반복했지만,\n결국 제자리에 멈춰 섰다.</color>",
  ui_story_5083_50831400_76_dialog_content = "더글라스...",
  ui_story_5083_50831400_77_dialog_content = "<color=#e8d9bb>고개를 들고 소리 없이 눈물을 흘리는 대원수의 모습은 한층 더 초췌해 보였다.\n그곳에 서 있는 것은 군의 지도자가 아닌, 가슴이 무너져 내린 한 아버지였다.</color>",
  ui_story_5083_50831400_78_dialog_content = "<color=#e8d9bb>시간이 얼마나 흘렀을까. 대원수가 무거운 발걸음을 옮겨 자리를 떠나고 나서야,\n바튼은 마침내 그곳으로 향했다.</color>",
  ui_story_5083_50831400_79_dialog_content = "전우들의 이름이 새겨져 있어... 일루미나의 아이들은, 결국 모두 이 「집」으로 돌아오지...",
  ui_story_5083_50831400_80_dialog_content = "삐빅, 바튼 씨...",
  ui_story_5083_50831400_81_dialog_content = "너 말고 지금 내가 누굴 믿을 수 있을까...\n다들 비밀이 있고, 죄다 복잡한 인간들뿐이야...",
  ui_story_5083_50831400_82_dialog_content = "설령 대원수와 상부가 결백하다고 해도, 내가 어떻게 믿을 수 있겠냐고...",
  ui_story_5083_50831400_83_dialog_content = "바튼 씨, 이걸 보세요...",
  ui_story_5083_50831400_84_dialog_content = "이건... 그때 우릴 찍은 기념사진인가?",
  ui_story_5083_50831400_85_dialog_content = "네가 찍어줬던 거야? 고맙다.",
  ui_story_5083_50831400_86_dialog_content = "하지만 더그는 이제 없고, 라인하르트는 변했어. 다른 녀석들은 어디 갔는지도 모르겠어.",
  ui_story_5083_50831400_87_dialog_content = "사진 속의 모두가 왜 전부 흩어져 버린 거냐고...",
  ui_story_5083_50831400_88_dialog_content = "...그래도 난 이 모든 걸 짊어지고 계속 앞으로 나아가야 해... 그렇지?",
  ui_story_5083_50831400_89_dialog_content = "남은 게 나 하나뿐이라 해도, 난 반드시 「배의 키」를 잡아야 해.",
  ui_story_5083_50831500_1_dialog_content = "<color=#e8d9bb>자난성의 전황이 악화되자, 위원회는 마침내 제한을 풀었다.\n바튼은 병력이 보충된 부대를 이끌고 전선에 복귀하게 되었다.</color>",
  ui_story_5083_50831500_2_dialog_content = "<color=#e8d9bb>그러나 상황은 여전히 낙관할 수 없었다. 암귀 군단은 이미 자난성 외곽까지 밀고 들어온 뒤였다.\n대원수는 포위당하는 상황을 피하기 위해 미리 철수를 준비할 것을 명령했다.</color>",
  ui_story_5083_50831500_3_dialog_content = "보고드립니다! 대대장님, 암귀 군단이 잠시 퇴각했습니다. 이제 어떻게 하실 생각이십니까?",
  ui_story_5083_50831500_4_dialog_content = "방어선을 밀고 나가라. 대신 무모하게 전진하진 마라. 아니, 역시 자리를 지키는 게 좋겠군.\n지금 상태를 유지해라. 현재 방어선이 물자 운송엔 더 유리해.",
  ui_story_5083_50831500_5_dialog_content = "대대장님, 전차부대에서 반격 개시 시점을 묻고 있습니다.",
  ui_story_5083_50831500_6_dialog_content = "반격은 안 된다! 적의 섬멸만 생각할 게 아냐. 우린 지금 방어전을 치르고 있다고!\n사람들이 철수할 시간만 벌어 주면 돼...",
  ui_story_5083_50831500_7_dialog_content = "하지만 1군단 쪽은 아직 고전 중입니다... 지원하러 가지 않는 겁니까?",
  ui_story_5083_50831500_8_dialog_content = "...어쩔 수 없다. 우린 더는 위험을 감수할 수 없어...\n난 너흴 알 수 없는 길로 가게 만들 순 없다...",
  ui_story_5083_50831500_9_dialog_content = "너 이 자식 여기서 뭐 하고 있는 거냐!\n눈앞에 아직도 암귀가 한가득인데, 왜 기세를 몰아서 추격하지 않냔 말이다!",
  ui_story_5083_50831500_10_dialog_content = "그랬다간... 불필요한 희생을 하게 됩니다.",
  ui_story_5083_50831500_11_dialog_content = "희생자가 없는 전투는 없다! 중요한 건 왜 싸우고, 왜 죽는지란 말이다!",
  ui_story_5083_50831500_12_dialog_content = "한때는 그걸 잘 알고 있던 놈이 대체 왜 이제 와서 나사가 빠진 거냐...",
  ui_story_5083_50831500_13_dialog_content = "전... 이제 그 빛이 보이질 않습니다...",
  ui_story_5083_50831500_14_dialog_content = "?!",
  ui_story_5083_50831500_15_dialog_content = "전 줄곧 일루미나에서 준비해 둔 길을 달려왔고,\n영원히 꺼지지 않는 중앙 탑의 빛은 그 앞을 비춰 주었습니다.",
  ui_story_5083_50831500_16_dialog_content = "전 그 빛을 쫓으며 자랐고, 그 빛을 향해 앞으로 나아갔는데...\n이젠 그 빛이 보이질 않는단 말입니다.",
  ui_story_5083_50831500_17_dialog_content = "부하들이 절 위해 싸워야 할 이유도 못 찾겠고, 제 지휘 때문에 병사들이\n무의미하게 목숨을 잃게 만들고 싶지 않습니다.",
  ui_story_5083_50831500_18_dialog_content = "전 병사들을 이끌고 앞장서야 하지만... 저조차도 지금은 갈피를 못 잡겠습니다...",
  ui_story_5083_50831500_19_dialog_content = "망할 자식, 이젠 너까지 우물쭈물하려는 거냐?",
  ui_story_5083_50831500_20_dialog_content = "넌 네가 지금 가진 정보를 토대로 스스로 판단해서 명령을 내리고,\n마지막엔 목표를 달성하면 된다... 이 정도 지휘면 되는 거 아니냐?",
  ui_story_5083_50831500_21_dialog_content = "일루미나의 병사들은 바보가 아니다. 다들 자기가 뭘 위해 싸우는지 당연히 알고 있다!",
  ui_story_5083_50831500_22_dialog_content = "당장 말로 설명할 순 없더라도, 네가 가서 물어보기만 하면,\n저마다 죽고 싶진 않아도 목숨 걸고 싸우는 이유를 알 수 있을 거다!",
  ui_story_5083_50831500_23_dialog_content = "당장 지휘소에서 나가서 참호로 가라! 그럼 네가 나아가야 할 방향이 보일 거다!\n병사들의 의지가 네게 방향을 가르쳐 줄 테니 말이다!",
  ui_story_5083_50831500_24_dialog_content = "우리 일루미나의 군인은 누구나 그 빛 아래서 자랐다.\n그런데 네가 어떻게 저들의 빛을 잊을 수 있는 거냐!",
  ui_story_5083_50831500_25_dialog_content = "그들의... 빛...?",
  ui_story_5083_50831500_26_dialog_content = "사상자가 많으면 어떻게든 줄일 방법을 생각하고, 더 나은 전술을 수립해라!\n절대로 네 부하들을 저버려선 안 된다!",
  ui_story_5083_50831500_27_dialog_content = "구석에 숨어 자길 원망해 봐야 무슨 소용이 있겠냐!\n그러고 있으면 목숨을 잃은 병사들한테 미안하지도 않은 거냐!",
  ui_story_5083_50831500_28_dialog_content = "병사들이 지금 네 꼴을 보고 널 따를 마음이 들겠냔 말이다!",
  ui_story_5083_50831500_29_dialog_content = "네 곁엔 아직도 많은 전우들이 남아 있다. 왜 모든 일에 자신감을 잃어버린 거냐!",
  ui_story_5083_50831500_30_dialog_content = "영웅은 너 하나만이 아니다. 네가 모든 이를 대표할 자격이라도 있다고 생각하는 거냐?\n자기가 길을 못 찾겠다고 해서, 병사들에게도 기회를 주지 않을 작정이냐?",
  ui_story_5083_50831500_31_dialog_content = "...군단장님 말씀이 맞습니다. 제가 얼이 빠져 있었습니다.",
  ui_story_5083_50831500_32_dialog_content = "멈춰 서 있으면 미래는 없다! 짊어질 각오가 없다면 양심이 없는 거고!",
  ui_story_5083_50831500_33_dialog_content = "모두가 저 빛에 부끄럽지 않도록 노력하고 있다.\n병사들이 네가 나아가도록 밀어주고 있다면, 넌 저 빛이 흐려지지 않을 방법을 찾아야 한다.",
  ui_story_5083_50831500_34_dialog_content = "네가 병사들을 지휘하기만 하는 것이 아니다. 병사들도 널 선택한 거다.",
  ui_story_5083_50831500_35_dialog_content = "똑똑히 기억해 둬라, 바튼. 네 앞의 모든 걸 직시해라.\n군인의 소명과 의지는 전장에 있다. 넌 반드시 그걸 찾을 수 있을 거다.",
  ui_story_5083_50831500_36_dialog_content = "누굴 믿어야 좋을지 모르겠다면, 네 전우들을 믿어라.\n네가 어떤 「왕」이 되든, 전우들은 끝까지 네 손을 놓지 않을 테니까.",
  ui_story_5083_50831500_37_dialog_content = "보고드립니다! 1군단이 버티지 못하고 있습니다!\n초대형 암귀가 길을 뚫고, 암귀들이 자난성의 대형 엘리베이터에 진입했습니다!",
  ui_story_5083_50831500_38_dialog_content = "대원수님께서는 이미... <color=#FFB400>자난성을 포기하라</color>는 명령을 내리셨습니다!",
  ui_story_5083_50831500_39_dialog_content = "뭐야? 우리들의 집을 버리라고?",
  ui_story_5083_50831500_40_dialog_content = "정신이 나가기라도 한 거냐?! 여긴 일루미나의 중심이자 우리 모두의 터전이다!\n자난성은 꺼지지 않는 「등대」여야 한단 말이다!",
  ui_story_5083_50831500_41_dialog_content = "...죄송합니다! 하지만 대원수님께선 적어도 비전투인원은 모두 안전히 대피할 수 있도록,\n군단 하나가 최후미를 지켜 주길 바라고 계십니다.",
  ui_story_5083_50831500_42_dialog_content = "비전투인원이 대피를 마치면, 다른 군단도 태세를 정비한 후 최후미 군단을 구조하고,\n암귀 군단을 포위해 공격할 계획입니다.",
  ui_story_5083_50831500_43_dialog_content = "비전투인원들에게 모두 대피하라고 전해!\n우리 2군단이 대피용 엘리베이터 입구를 지킬 테니, 어서 떠나라고 해!",
  ui_story_5083_50831500_44_dialog_content = "군단장님... 싸우러 갑시다!",
  ui_story_5083_50831500_45_dialog_content = "<color=#e8d9bb>제2군단은 대피하기 시작한 인파를 거슬러 자난성으로 향했다.</color>",
  ui_story_5083_50831500_46_dialog_content = "<color=#e8d9bb>그 뒤로 며칠 동안 쉼 없이 전투가 계속됐다.\n제2군단의 병사들은 쓰러져 가면서도, 끝까지 대피용 엘리베이터 앞을 지켰다.</color>",
  ui_story_5083_50831500_47_dialog_content = "<color=#e8d9bb>그러나 수많은 암귀가 지키는 이 없는 대형 엘리베이터로 공격해 들어왔고...</color>\n<color=#FFB400>자난성은 공식적으로 함락되었다.</color>",
  ui_story_5083_50831500_48_dialog_content = "마지막 인원과 물자도 떠났으니, 바튼, 너도 당장 떠나라.",
  ui_story_5083_50831500_49_dialog_content = "차량 상태가 안 좋아서 많이는 못 탈 거다.",
  ui_story_5083_50831500_50_dialog_content = "...환장하겠네, 또 그렇게 나오시겠다 이겁니까?",
  ui_story_5083_50831500_51_dialog_content = "난 남은 병력과 아래로 내려갈 거다. 날 따르는 건 전부 백전노장들이다.\n너희 같은 젖비린내 나는 애새끼들이랑은 다르다고.",
  ui_story_5083_50831500_52_dialog_content = "멍청한 소리 좀 그만하십쇼! 아래는 이미...",
  ui_story_5083_50831500_53_dialog_content = "어쨌든 난 중앙 탑을 지켜야 한다!\n에너지원과 운송 중추만 지켜낼 수 있다면, 자난성의 심장을 지켜내는 셈이다!",
  ui_story_5083_50831500_54_dialog_content = "만약 그 중추가 13호 지하성처럼 파괴된다면, 자난성의 빛은 꺼지게 된다.\n그럼 모든 일루미나인들은 자신의 집을 찾지 못하게 되는 거다.",
  ui_story_5083_50831500_55_dialog_content = "방어선에서 분전하는 전우들이 돌아올 길을 잃게 만들 순 없단 말이다!",
  ui_story_5083_50831500_56_dialog_content = "그럼 저도 데려가십쇼!",
  ui_story_5083_50831500_57_dialog_content = "...바튼, 넌 더그처럼 세심한 성격은 아니라서 다행이야. 낯간지러운 말은 딱 한 번만 한다.",
  ui_story_5083_50831500_58_dialog_content = "난 언제나 널 믿었다. 넌 내가 직접 갈고 닦은 「첨예탄」이다.",
  ui_story_5083_50831500_59_dialog_content = "그러니 마지막 수업을 해 주마...",
  ui_story_5083_50831500_60_dialog_content = "필요할 땐 사령관 역시 모든 것을 짊어지고, 미래의 젊은이들을 위해 길을 열어야 하는 법이다!",
  ui_story_5083_50831500_61_dialog_content = "바튼, 넌 분명 2군단의 가장 훌륭한 새 왕이 될 수 있을 거다.\n2군단은 네게 맡길 테니, 이제 가라!",
  ui_story_5083_50831500_62_dialog_content = "뭔 소리를 하셔도 전 안 갑니다. 저까지 군단장님을 때려눕히게 만들지 마십쇼.",
  ui_story_5083_50831500_63_dialog_content = "병사! 이놈을 철수 차량에 태워라... 다리를 분질러서라도 태워!",
  ui_story_5083_50831500_64_dialog_content = "뭐야? 이 새끼들 이거 안 놔?!",
  ui_story_5083_50831500_65_dialog_content = "이 망할 꼰대가! 나한테 이러지 말라고! 제발!",
  ui_story_5083_50831500_66_dialog_content = "작별이다... 애물단지 같은 내 「자식」아...",
  ui_story_5083_50831601_1_dialog_content = "제군들, 나와 함께 남게 만들어서 미안하다.",
  ui_story_5083_50831601_2_dialog_content = "1대대장, 네 부대를 데리고 우릴 위해 에너지 중추로 향하는 길을 열어 줬으면 한다.\n어떤 대가를 치러서라도 말이다... 할 수 있겠나?",
  ui_story_5083_50831601_3_dialog_content = "문제없습니다, 군단장님!",
  ui_story_5083_50831601_4_dialog_content = "예상하는 병력 손실 규모는?",
  ui_story_5083_50831601_5_dialog_content = "전멸할 것으로 예상됩니다!",
  ui_story_5083_50831601_6_dialog_content = "......",
  ui_story_5083_50831601_7_dialog_content = "하지만 임무는 반드시 완수하겠습니다!",
  ui_story_5083_50831601_8_dialog_content = "훌륭하다... 저세상에 가면 내가 너희 부하가 되어 주마!",
  ui_story_5083_50831601_9_dialog_content = "되도록 다시 안 만났으면 좋겠습니다, 군단장님!",
  ui_story_5083_50831601_10_dialog_content = "1대대, 명령을 하달하겠다. 반격을 준비해라!",
  ui_story_5083_50831601_11_dialog_content = "두려워 마라... 어떻게든 버티면 날이 밝을 거다.\n그럼 대원수가 포위를 뚫고 우릴 구하러 올 거다.",
  ui_story_5083_50831601_12_dialog_content = "내 수중엔 아직 루맘버가 있다. 우리가 발사대에서 구조 신호를 보내기엔 충분하다.",
  ui_story_5083_50831601_13_dialog_content = "남은 건 여명이 밝아 오도록 우릴 불태우는 것뿐이다...",
  ui_story_5083_50831601_14_dialog_content = "...그래서 이게 결말이란 거냐.\n차를 타고 꽁무니 빠지게 도망치면서, 자난성이 불바다가 되는 걸 지켜보는 게...?",
  ui_story_5083_50831601_15_dialog_content = "삐빅, 바튼 씨...",
  ui_story_5083_50831601_16_dialog_content = "적이다! 적의 습격이다!",
  ui_story_5083_50831601_17_dialog_content = "뭐야? 내가 싸우겠다!",
  ui_story_5083_50831601_18_dialog_content = "바튼 씨, 어서 눈을 뜨세요.",
  ui_story_5083_50831601_19_dialog_content = "대체 무슨 일이 일어난 거야...?",
  ui_story_5083_50831601_20_dialog_content = "적이 철수 차량을 공격했어요. 어서 일어나서 싸워야 해요.",
  ui_story_5083_50831601_21_dialog_content = "<size=45>제기랄!</size>",
  ui_story_5083_50831601_22_dialog_content = "난 지금 기분이 최악이니까, 내가 두 손이 묶여 있다고 깝치지 마라!",
  ui_story_5083_50831601_23_dialog_content = "크오오!",
  ui_story_5083_50831601_24_dialog_content = "쳇, 또 턱을 맞았잖아.",
  ui_story_5083_50831601_25_dialog_content = "망할... 누가 와서 이 수갑 좀 풀어!",
  ui_story_5083_50831601_26_dialog_content = "...잠깐만... 내 턱... 분명히 맞았는데, 왜 하나도 안 아픈 거지?",
  ui_story_5083_50831601_27_dialog_content = "멍하지 있지 말고 계속 싸우세요!",
  ui_story_5083_50831601_28_dialog_content = "이거나 먹어라! 절대 못 지나간다!",
  ui_story_5083_50831601_29_dialog_content = "...역시... 이건 꿈이었나... 그래, 그 시절의 나한텐 이런 「강철 턱」 같은 건 없었어.",
  ui_story_5083_50831601_30_dialog_content = "전부 기억났다... 이건 바로 날 가두었던 악몽이다.",
  ui_story_5083_50831601_31_dialog_content = "삐삑, 바튼 씨... 드디어 기억난 거예요?",
  ui_story_5083_50831601_32_dialog_content = "바튼 씨를 가둔 건 대체 뭔가요?",
  ui_story_5083_50831601_33_dialog_content = "난... 방향을 잃었다... 하지만 그래도 계속 믿어 왔다...\n멈추지 않고 싸우다 보면 언젠가는 빛이 나타날 거라고 말이야.",
  ui_story_5083_50831601_34_dialog_content = "하지만 여전히 여기 갇혀 있잖아요.",
  ui_story_5083_50831601_35_dialog_content = "나도 모르겠다... 아무것도 기억나지 않아...\n그때 난 도망치진 않았던 것 같은데... 그 뒤로 내가 뭘 했었는지 모르겠다...",
  ui_story_5083_50831601_36_dialog_content = "기억나는 거라곤... 꼰대가 그 전투에서...",
  ui_story_5083_50831601_37_dialog_content = "...그 뒤에 난 결전에 참여해 필사적으로 싸우다 심각한 부상을 입었고,\n「강철 턱」을 달게 됐다.",
  ui_story_5083_50831601_38_dialog_content = "많은 사람들이 날 이해하지 못했고, 날 상관을 버린 겁쟁이로 여겼다.\n자기 상관과 생사를 함께한 이들에게 난 별종 취급을 받았다.",
  ui_story_5083_50831601_39_dialog_content = "나도 꼰대 곁에서 끝까지 함께 싸우고 싶었단 말이다... 뭐, 됐어. 꿈이면 뭐 어떠냐.",
  ui_story_5083_50831601_40_dialog_content = "고작 악몽 따위가 날 가둬 둘 순 없다. 내겐 또 기회가 올 테니 말이다!\n몇 번이라도 좋다. 언젠가는... 반드시 바꿔 주마...",
  ui_story_5083_50831601_41_dialog_content = "현실을 받아들이고, 기회를 다음번으로 미루면... 바튼 씨는 자신을 용서할 수 있나요?",
  ui_story_5083_50831601_42_dialog_content = "바튼 씨가 악몽에서 벗어날 수 있다면, 어째서 또다시 「여기로 오게」 된 건가요?",
  ui_story_5083_50831601_43_dialog_content = "기억하세요? 바튼 씨가 이 악몽을 이미 몇 번이나 겪었고...\n「다음 기회」를 몇 번이나 기대했는지 말이에요.",
  ui_story_5083_50831601_44_dialog_content = "너...",
  ui_story_5083_50831601_45_dialog_content = "새벽을 깨는 탄환에게 묻고 싶어요. 그 「다음 기회」가 올 때까진 얼마나 더 기다려야 하죠?",
  ui_story_5083_50831601_46_dialog_content = "...넌 대체 누구냐.",
  ui_story_5083_50831601_47_dialog_content = "그 질문은 이미 처음에 대답했잖아요. 바튼 씨, 전 바튼 씨의 영원한 「조종사」예요.",
  ui_story_5083_50831601_48_dialog_content = "빛을 볼 순 있지만, 만질 순 없는 제가 보기엔...\n그 길은 제가 처음 바튼 씨를 알았을 때부터 이미 바튼 씨 발아래에 있었어요.",
  ui_story_5083_50831601_49_dialog_content = "서, 설마... 너...!",
  ui_story_5083_50831601_50_dialog_content = "대대장님, 계속 철수해야 합니다...",
  ui_story_5083_50831601_51_dialog_content = "저흰 이제 어디로 가야 합니까? 19호 지하성입니까?",
  ui_story_5083_50831601_52_dialog_content = "자난성이 정말로 함락됐습니다... 저희가 앞으로 자난성을 되찾을 수 있을까요?",
  ui_story_5083_50831601_53_dialog_content = "<size=45>흐아압!</size>",
  ui_story_5083_50831601_54_dialog_content = "<color=#e8d9bb>바튼이 포효하며 손에 찬 수갑을 부서트렸다.</color>",
  ui_story_5083_50831601_55_dialog_content = "그래... 난 「반란분자」고, 굽힐 줄 모르는 「첨예탄」이다!",
  ui_story_5083_50831601_56_dialog_content = "내가 왜 이런 상황을 받아들여야 하지?",
  ui_story_5083_50831601_57_dialog_content = "난 내 자신에게 「혁명」을 일으키겠다. 그리고 지금이 바로 그 순간이다!",
  ui_story_5083_50831601_58_dialog_content = "2군단의 모든 병사들은 들어라!",
  ui_story_5083_50831601_59_dialog_content = "대대장님? 저희 임무는 대대장님을 안전한 철수 지점까지 모시는 겁니다!\n저희를 곤란하게 만들지 말아 주세요...",
  ui_story_5083_50831601_60_dialog_content = "아니! 우리에게 안전 따윈 없다!",
  ui_story_5083_50831601_61_dialog_content = "암귀들이 엉망으로 물어뜯어 놓은 이 아스트라에서,\n우리가 돌아갈 수 있는 고향은 단 한 곳뿐이다.",
  ui_story_5083_50831601_62_dialog_content = "너흰 모두 저기서 훈련을 받았으니까, 저 빛이 얼마나 뜨거웠는지 기억하고 있겠지!",
  ui_story_5083_50831601_63_dialog_content = "우린 떠돌이가 되려고 태어난 게 아니다!\n자난성이 없으면 우리가 또 어디로 돌아갈 수 있단 말이냐!",
  ui_story_5083_50831601_64_dialog_content = "너희의 지휘관이 지금 저기서 사투를 벌이고 있고, 너희의 도움이 필요하다!\n저 나팔 소리가 안 들리나? 자난성이 우리를 부르고 있다!",
  ui_story_5083_50831601_65_dialog_content = "만약 우리가 전장에서 죽을 운명이라면,\n난 너희를 지휘해서 함께 자난성을 탈환하는 전장에서 스러지고 싶다!",
  ui_story_5083_50831601_66_dialog_content = "난 반드시 너희를 집으로 데려갈 것이다.\n설령 마지막에 남는 것은 기념비에 새겨진 이름뿐일지라도──",
  ui_story_5083_50831601_67_dialog_content = "중앙 탑의 빛이 꺼지지 않는 한, 우리의 후대는 앞으로 나아갈 힘을 얻을 것이다!",
  ui_story_5083_50831601_68_dialog_content = "저, 전... 대대장님과 가겠습니다.\n자난성을 지키라는 게 대원수님의 명령이었으니... 이건 명령 불복종이 아닙니다.",
  ui_story_5083_50831601_69_dialog_content = "저도 데려가 주십쇼! 전 대대장님이 처음으로 지휘를 맡으셨을 때부터 대대장님을 따랐습니다!\n전 저희와 함께 적에게 돌격하시던 대대장님을 믿습니다!",
  ui_story_5083_50831601_70_dialog_content = "제 소대장과 동기들 모두 전사했지만, 그들은 절 지켜 줬습니다.\n자난성을 지켜낼 수만 있다면, 희생이 뭐가 두렵겠습니까.",
  ui_story_5083_50831601_71_dialog_content = "저도 가겠습니다. 누군가 대대장님을 잡아가려 한다면, 우선 저희부터 잡아야 할 겁니다.",
  ui_story_5083_50831601_72_dialog_content = "너희들...",
  ui_story_5083_50831601_73_dialog_content = "바튼 씨, 날이 밝으려고 해요.",
  ui_story_5083_50831601_74_dialog_content = "그래, 이제 그 길이 보인다... 모두의 빛이 내게 방향을 가르쳐 줬다.",
  ui_story_5083_50831601_75_dialog_content = "전군, 귀환한다! 우리가 이 밤을 끝내고... 자난성을 되찾는 거다!",
  ui_story_5083_50831601_76_dialog_content = "<color=#e8d9bb>모든 병사들이 불타오르는 자난성을 향해 진군했다.</color>",
  ui_story_5083_50831601_77_dialog_content = "<color=#e8d9bb>자신이 그곳에서 죽을 것임을 모두가 알고 있었다. 그러나 누구 하나 걸음을 멈추지 않았다.</color>",
  ui_story_5083_50831601_78_dialog_content = "<color=#e8d9bb>만약 그들이 스스로를 불사르지 않았다면, 아스트라의 하늘이 밝아오는 일은 없었을 것이다.</color>",
  ui_story_5083_50831601_79_dialog_content = "<color=#e8d9bb>8년간 아스트라를 휩쓸었던 어둠의 위기는 이 강인한 선열들 덕분에 종식될 수 있었다.\n그들이 전해 준 시대를 살아가는 자로서, 나는 이 모습을 반드시 끝까지 지켜보아야 했다.</color>",
  ui_story_5083_50831601_80_dialog_content = "보잘것없는 오로리안이여, 네 부하는 거의 다 죽었다.\n나 <color=#FFB400>파멸의 종</color> 앞에서, 모든 생명은 끝을 맞이할 것이다.",
  ui_story_5083_50831601_81_dialog_content = "퉷!",
  ui_story_5083_50831601_82_dialog_content = "<color=#e8d9bb>거대한 적이 중앙 탑 앞에 도착했다.\n불꽃이 흐르는 바위 피부 위로, 추악하지만 눈에 띄는 금속 파편들이 갑옷을 이루고 있었다.</color>",
  ui_story_5083_50831601_83_dialog_content = "<color=#e8d9bb>어느 지하성의 것인지 짐작할 수 있는 번호가 새겨진 금속들은,\n마치 훈장처럼 소리 없이 이 거대한 암귀의 전적을 드러냈다.</color>",
  ui_story_5083_50831601_84_dialog_content = "<color=#e8d9bb>보는 이로 하여금 소름이 끼치고, 참을 수 없는 분노가 치밀어 오르게 만드는 모습이었다.</color>",
  ui_story_5083_50831601_85_dialog_content = "<color=#e8d9bb>거대한 암귀가 전진하기 시작하자, 금속 갑옷들이 서로 부딪히며,\n생명을 증오하는 석양의 종소리가 되어 울려 퍼졌다.</color>",
  ui_story_5083_50831601_86_dialog_content = "흐하하, 쥐새끼 같은 놈, 떨고 있구나. 그래... 네 두려움의 냄새가 나는군.\n네가 쥐고 있는 깃발도 함께 떨리고 있지 않나.",
  ui_story_5083_50831601_87_dialog_content = "벌레들은 다 똑같다. 모두 강자를 두려워하지. 그것은 본능이다.\n무릎을 꿇도록 해라. 고통 없이 짓뭉개 주겠다.",
  ui_story_5083_50831601_88_dialog_content = "...그래... 난 떨고 있다... 이 나이가 돼서도 두려움에 몸을 떨게 될 줄은 몰랐다.",
  ui_story_5083_50831601_89_dialog_content = "어쩌면 네 녀석 말대로 이건 본능일지도 모르지...",
  ui_story_5083_50831601_90_dialog_content = "인정하는 것이냐? 그렇다면 무릎을 꿇고 내게 용서를 구걸해라...\n흐흐, 그것이 내 가장 큰 즐거움이다.",
  ui_story_5083_50831601_91_dialog_content = "역겨운 괴물 새끼가 뭔 헛소리냐! 망상에 빠져서 네 상대를 겁쟁이들이라 여기고 있는 거냐?!",
  ui_story_5083_50831601_92_dialog_content = "네놈은 우리의 차이를 전혀 이해하지 못하고 있다!",
  ui_story_5083_50831601_93_dialog_content = "넌 여기서 아무 재미도 못 볼 거다...\n네가 보게 될 건 우리 일루미나인들의 꺾이지 않는 마음뿐이다!",
  ui_story_5083_50831601_94_dialog_content = "오로리안은 두려움을 느끼지만, 암귀도 느낀다.\n그러나 너희는 우리처럼 그 두려움을 씹어 삼키는 법을 영원히 배우지 못하겠지.",
  ui_story_5083_50831601_95_dialog_content = "그러니 일루미나의 방어선을 넘을 생각은 꿈도 꾸지 마라!",
  ui_story_5083_50831601_96_dialog_content = "그렇다면 어디 해 볼까.",
  ui_story_5083_50831601_97_dialog_content = "군단장님... 죄송합니다... 저흰 이제 한계입니다... 지원군은 언제 도착할지...",
  ui_story_5083_50831601_98_dialog_content = "흐하하, 네 부하들을 기만할 시간이다. 자, 네 손에 있는 루맘버를 꺼내서,\n지원군이 올 거라고, 모든 게 괜찮아질 거라고 저들을 속여라.",
  ui_story_5083_50831601_99_dialog_content = "내가 지하성을 파괴할 때 본 모든 지휘관들이 다 그렇게 부하들을 속였다.",
  ui_story_5083_50831601_100_dialog_content = "내 손에서 그들의 생명의 불꽃이 꺼져갈 때까지도 지원은 오지 않았다.\n그게 바로 너희 일루미나의 가장 우스운 위선이다.",
  ui_story_5083_50831601_101_dialog_content = "...동포들이여, 미안하다.\n너흰 내게 목숨을 맡겼지만, 난 너희에게 그 무엇 하나 장담할 수 없다.",
  ui_story_5083_50831601_102_dialog_content = "하지만 부디 날 믿어다오. 일루미나는 결코 방어선을 버리지 않는다!",
  ui_story_5083_50831601_103_dialog_content = "<color=#e8d9bb>팡고가 루맘버를 발사기에 넣고, 기도하듯 손잡이를 잡아당기자,\n순식간에 빛이 어둠을 가르며 함락된 자난성을 넘어 하늘로 날아갔다.</color>",
  ui_story_5083_50831601_104_dialog_content = "<color=#e8d9bb>자난성 안에서 필사적으로 싸우던 군인들이 서로 약속이라도 한 듯 일제히 그 빛을 바라봤다.\n그들의 눈동자에는 </color><color=#FFB400>희망</color><color=#e8d9bb>이라는 찬란함이 반짝이고 있었다.</color>",
  ui_story_5083_50831601_105_dialog_content = "이제 남은 건 네놈뿐인 것을 알면서도 여전히 자신을 속이는군. 그게 바로 신념이란 것이지.\n그 신념을 지닌 전사를 짓밟는 것은 평범한 벌레를 죽이는 것보다 더 즐거운 법이다!",
  ui_story_5083_50831601_106_dialog_content = "빌어먹을 암귀 새끼, 그러니까 넌 영원히 이해할 수 없는 거다...\n우리 일루미나인들이 왜 아스트라의 「방어선」이라고 불리는지 말이다!",
  ui_story_5083_50831601_107_dialog_content = "나는 「슈르톤」이다! 너를 파멸시킬 이의 이름을 기억해 두어라!",
  ui_story_5083_50831601_108_dialog_content = "놈들을 모두 죽이고, 중앙 탑을 무너트려라.\n자난성이 심연으로 가라앉는 모습을 내가 지켜봐 주마.",
  ui_story_5083_50831601_109_dialog_content = "제2군단에 후퇴란 말은 없다!",
  ui_story_5083_50831601_110_dialog_content = "<color=#e8d9bb>하늘로 쏘아 올려진 구조 신호가 점점 희미해지더니 힘없이 땅으로 떨어져 내렸다.\n심연 속으로 가라앉고 있는 별들이 새벽을 여는 것은 불가능해 보였다...</color>",
  ui_story_5083_50831601_111_dialog_content = "「2군단」? 며칠 전에도 그렇게 외치며 내 몸에 칼자국을 남긴 놈이 있었지.",
  ui_story_5083_50831601_112_dialog_content = "유감스럽게도 놈과 그 병사들은 너무나도 나약했지만 말이다. 대신 놈의 칼은 아직 가지고 있다.\n보이나? 여기 내 가슴에 있다. 나쁘지 않은 기념품이지.",
  ui_story_5083_50831601_113_dialog_content = "더그...! 미안하다...",
  ui_story_5083_50831601_114_dialog_content = "<color=#e8d9bb>절망이 가슴을 뒤덮었지만, 노병은 무기를 힘껏 그러쥔 채,\n가장 거대한 어둠에 맞설 준비를 했다.</color>",
  ui_story_5083_50831601_115_dialog_content = "<color=#e8d9bb>그러나... 가장 어두운 밤은, 가장 밝은 별을 돋보이게 만들었다.</color>",
  ui_story_5083_50831601_116_dialog_content = "<size=45>웃기지 마!</size>",
  ui_story_5083_50831601_117_dialog_content = "<size=45>이거나 처먹어!</size>",
  ui_story_5083_50831601_118_dialog_content = "심연으로 떨어지는 건 바로 네놈이다! 이 돼지 새끼야!",
  ui_story_5083_50831601_119_dialog_content = "<color=#e8d9bb>하늘에서 떨어져 내린 장갑차가 거침없이 돌진해, 초대형 암귀의 허리를 들이받았다.\n그 거리는 차량의 근접 방어포가 최대 위력을 발휘할 수 있는 정도였다.</color>",
  ui_story_5083_50831601_120_dialog_content = "으아아아──!",
  ui_story_5083_50831601_121_dialog_content = "제가 받아 줄게요! 읏차!",
  ui_story_5083_50831601_122_dialog_content = "고맙다, 전우!",
  ui_story_5083_50831601_123_dialog_content = "너무 무모했어요. 차도 폭발했잖아요. 하마터면 바튼 씨까지...",
  ui_story_5083_50831601_124_dialog_content = "이 정도는 미쳐줘야 나 아니냐?",
  ui_story_5083_50831601_125_dialog_content = "지금 이 순간이야말로 진정한 나란 말이다!",
  ui_story_5083_50831601_126_dialog_content = "야 이 새끼야! 왜 또 돌아왔어?!",
  ui_story_5083_50831601_127_dialog_content = "거 신호 쏜 건 군단장님 아니십니까? 전 엄연한 지원군인뎁쇼.",
  ui_story_5083_50831601_128_dialog_content = "위층은 전부 함락돼서, 제가 차를 끌고 내려왔습니다.\n이젠 저보고 꺼지라고 하셔봤자 갈 방법도 없습니다.",
  ui_story_5083_50831601_129_dialog_content = "이...!",
  ui_story_5083_50831601_130_dialog_content = "이번으로 세 번째입니다! 군단장님! 세 번째란 말입니다...\n이제 꺼지라는 소리는 그만 좀 하십쇼!",
  ui_story_5083_50831601_131_dialog_content = "제가 저 암귀 놈들한테 알려 줄 겁니다.\n하루도 태양을 볼 수 없는 지하라고 해도, 저 새끼들이 설칠 자리는 없다고 말입니다!",
  ui_story_5083_50831601_132_dialog_content = "자난성엔 반드시... 다시 빛이 떠오를 겁니다!",
  ui_story_5083_50831601_133_dialog_content = "멍청한 녀석아... 지원 병력이 오기 전에 우린 다 죽을지도 모른단 말이다.",
  ui_story_5083_50831601_134_dialog_content = "그럼 중앙 탑의 빛이 우리 시체를 비춰 주길 빌겠습니다.",
  ui_story_5083_50831601_135_dialog_content = "...벌레 녀석, 네놈 덕에 절벽으로 떨어질 뻔했군.",
  ui_story_5083_50831601_136_dialog_content = "반으로 갈라지고도 안 죽었다고?",
  ui_story_5083_50831601_137_dialog_content = "내가 그 많은 지하성을 어떻게 파괴했다고 생각하는 거지?\n고작 화포 따위로 날 죽일 수 있을 것 같나? 나는 <color=#FFB400>모든 생명의 적</color>...",
  ui_story_5083_50831601_138_dialog_content = "놀고 자빠졌네! 「모든 생명의 적」이라는 새끼가 지 목숨은 용을 써서 아끼고 있으면서.",
  ui_story_5083_50831601_139_dialog_content = "개소리 집어치우고 덤벼!",
  ui_story_5083_50831601_140_dialog_content = "내가 여기 모든 전우들과 함께 널 심연으로 떨어트려 주마!",
  ui_story_5083_50831602_1_dialog_content = "날 죽일 수 있으리라 생각하나!",
  ui_story_5083_50831602_2_dialog_content = "흐하하, 그대로 쓰러져서 일어서지도 못하는 주제에, 뭐가 「꺾이지 않는 마음」이란 거냐.",
  ui_story_5083_50831602_3_dialog_content = "이 새끼! 죽여버리겠어!",
  ui_story_5083_50831602_4_dialog_content = "너도 놈의 길동무나 되어라!",
  ui_story_5083_50831602_5_dialog_content = "<color=#e8d9bb>바튼은 주먹을 피하고 암귀의 팔을 타고 올라갔다.</color>",
  ui_story_5083_50831602_6_dialog_content = "<color=#e8d9bb>그리고 슈르톤이 미처 반응하기 전에, 바튼은 암귀가 가지고 있던 더그의 검을 되찾았다.</color>",
  ui_story_5083_50831602_7_dialog_content = "<color=#e8d9bb>두 검은 바튼의 손에서 하나가 되어 그의 힘이 되었고,\n바튼은 빠르게 움직이며 슈르톤에게 맹렬한 공격을 퍼부었다.</color>",
  ui_story_5083_50831602_8_dialog_content = "<color=#e8d9bb>칼날이 번득이며 슈르톤의 목을 베었고, 암귀는 고통에 차 주먹을 휘두르며 불꽃을 내뿜었다.</color>",
  ui_story_5083_50831602_9_dialog_content = "<color=#e8d9bb>그러나 바튼은 불꽃을 피하는 대신, 칼을 휘둘러 화염을 갈랐다.\n병영에서 수많은 </color><color=#FFB400>연습</color><color=#e8d9bb>을 통해 만들어 낸 빈틈 없는 검무였다.</color>",
  ui_story_5083_50831602_10_dialog_content = "<color=#e8d9bb>게다가 칼날보다도 훨씬 날카로운 것은 바로 살기 어린 바튼의 눈빛이었다.</color>",
  ui_story_5083_50831602_11_dialog_content = "<color=#e8d9bb>바튼은 도약하여 화염을 뚫고, 어둠을 가르며, 슈르톤의 목에 깊숙이 검을 꽂아 넣었다.</color>",
  ui_story_5083_50831602_12_dialog_content = "...저리 꺼져!",
  ui_story_5083_50831602_13_dialog_content = "대대장님을 지키자! 놈의 눈을 공격해!",
  ui_story_5083_50831602_14_dialog_content = "이제 마지막이다!\n군단장님, 잘 보십쇼! 총은 저처럼 쏘는 겁니다!",
  ui_story_5083_50831602_15_dialog_content = "<color=#e8d9bb>바튼은 재빨리 총을 뽑아 정확히 쌍날검의 끝을 맞혔고,\n칼날은 슈르톤의 몸속에 완전히 박혀버렸다.</color>",
  ui_story_5083_50831602_16_dialog_content = "<color=#e8d9bb>곧이어 바튼이 품에서 리모컨을 꺼내 누르자,\n그가 미리 자신의 칼자루에 설치해 뒀던 폭약도 폭발했다.</color>",
  ui_story_5083_50831602_17_dialog_content = "<color=#e8d9bb>바튼이 승리를 위해 자신과 친구의 무기조차 버릴 것이라 예상한 사람은 아무도 없었다.</color>",
  ui_story_5083_50831602_18_dialog_content = "안...돼...! <color=#FFB400>어머니</color>시여...",
  ui_story_5083_50831602_19_dialog_content = "심연에서 영원히 경멸받아라, 돼지 새끼야.",
  ui_story_5083_50831602_20_dialog_content = "...그래도 괜찮은 건가요?",
  ui_story_5083_50831602_21_dialog_content = "더그는 우리 마음에, 그리고 기념비에 계속 남을 거다.",
  ui_story_5083_50831602_22_dialog_content = "유품 따위를 남길 필요는 없어. 녀석의 의지는 이미 우리와 함께 나아가고 있으니까.",
  ui_story_5083_50831602_23_dialog_content = "...아 참! 군단장님! 괜찮으십니까?!",
  ui_story_5083_50831602_24_dialog_content = "건드리면 안 돼요. 아까 공격으로 척추가 부러지셨어요.",
  ui_story_5083_50831602_25_dialog_content = "대대장님, 조심하십시오! 소형 암귀들이 아직도 접근 중입니다!",
  ui_story_5083_50831602_26_dialog_content = "받아라... 우리 2군단의 군기다... 바튼, 이제부터는 네가 군단장이다...\n동포들을 데리고... 끝까지 싸워라...",
  ui_story_5083_50831602_27_dialog_content = "일루미나의 동료를... 믿어라... 지원은 반드시 온다...",
  ui_story_5083_50831602_28_dialog_content = "정신을 잃으셨어요!",
  ui_story_5083_50831602_29_dialog_content = "...이런 망할! 젠장할!",
  ui_story_5083_50831602_30_dialog_content = "제2군단에 타협이란 없다!",
  ui_story_5083_50831602_31_dialog_content = "제2군단에 타협이란 없다!",
  ui_story_5083_50831602_32_dialog_content = "<color=#e8d9bb>초대형 암귀는 쓰러졌지만, 전쟁은 아직 끝나지 않았다.\n더 많은 소형 암귀들이 이 유일한 입구로 밀려 들어와 병사들과 교전을 펼쳤다.</color>",
  ui_story_5083_50831602_33_dialog_content = "<color=#e8d9bb>바튼은 군기를 손에 쥐고, 전우들과 함께 싸우며 퇴각했고,\n결국 그들은 에너지 센터 입구까지 몰리게 됐다.</color>",
  ui_story_5083_50831602_34_dialog_content = "<color=#e8d9bb>문득 주변을 돌아본 바튼은 곁에 서 있는 병사들이 이미 몇 명밖에 남지 않은 것을 발견했다.</color>",
  ui_story_5083_50831602_35_dialog_content = "어딜 기어들어 와!",
  ui_story_5083_50831602_36_dialog_content = "남은 건 우리뿐이지만... 그래도 우린 절대 타협하지 않는다... 절대로...",
  ui_story_5083_50831602_37_dialog_content = "바튼 씨, 전 끝까지... 함께 싸울게요.",
  ui_story_5083_50831602_38_dialog_content = "저흰 숨이 끊어지는 순간까지 대대장님을 따르겠습니다.",
  ui_story_5083_50831602_39_dialog_content = "목숨을 잃는 한이 있어도, 저희가 이 길을 막아낼 겁니다!",
  ui_story_5083_50831602_40_dialog_content = "바보가 따로 없군... 내가 뭘 하고 있는 거냐...\n어째서 이제야 생각이 난 거냔 말이다...",
  ui_story_5083_50831602_41_dialog_content = "...난 애초에 이 결말을 알고 있었다.",
  ui_story_5083_50831602_42_dialog_content = "그때... 간신히 저 돼지 놈을 쓰러트리고 나서, 우린 공세에 떠밀려 퇴각했다.\n하지만... 꼰대는 노병들을 데리고 끝까지 맞서 싸웠지.",
  ui_story_5083_50831602_43_dialog_content = "결국, 이전 세대의 전사들은 대부분 목숨을 잃었고,\n군단장님도 중상을 입어 10년 동안 혼수 상태로 병상에 누운 영감 신세가 됐다.",
  ui_story_5083_50831602_44_dialog_content = "......",
  ui_story_5083_50831602_45_dialog_content = "PlayerName, 난 너 같은 눈이 없다. 그래서 네가 빛을 항상 볼 수 있다는 게 정말 부러웠다.",
  ui_story_5083_50831602_46_dialog_content = "하지만 난 방황하지 않는다. 끝까지 적과 맞서 싸우다 보면...\n결국엔 빛이 보일 거라고 진심으로 믿고 있기 때문이다.",
  ui_story_5083_50831602_47_dialog_content = "제가 바튼 씨를 알게 됐을 때부터, 바튼 씨는 확실히 희망의 길을 걷고 있었어요.",
  ui_story_5083_50831602_48_dialog_content = "바튼 씨를 알게 돼서 영광이에요. 바튼 씨는 언제나 흔들림 없이 우릴 수없이 구해 줬잖아요.",
  ui_story_5083_50831602_49_dialog_content = "바튼 씨는 영웅인데, 오히려 악몽에 시달리고 있어서...\n그래서 저도 바튼 씨를 위해서 방향을 인도하고 싶었어요.",
  ui_story_5083_50831602_50_dialog_content = "네가 내 옆에 있다면, 나도 길을 잃을 걱정은 없다. 악몽 따윈 별거 아니라고.",
  ui_story_5083_50831602_51_dialog_content = "하지만... 도저히 떨쳐버릴 수가 없는 생각이 있다...",
  ui_story_5083_50831602_52_dialog_content = "꼰대와 저들은 그때 정말 지원 병력이 와 주길 기다렸을까.",
  ui_story_5083_50831602_53_dialog_content = "...그래, 내가 어떻게 이걸 잊어버린 거지...",
  ui_story_5083_50831602_54_dialog_content = "꼰대가... 날 가둬 둔 진짜 「악몽」이었어...",
  ui_story_5083_50831602_55_dialog_content = "일루미나의 미래는 희망으로 가득 차 있다. 하지만 과거의 우리는...\n노병들을 새벽의 끝자락에 버려둔 채, 그들을 잊어버렸던 건 아닌지 모르겠어.",
  ui_story_5083_50831602_56_dialog_content = "생각만 해도 두려워진다...\n난 노병들이 회한과 절망을 품은 채로 눈을 감은 것은 아니었으면 한다.",
  ui_story_5083_50831602_57_dialog_content = "아니에요, 바튼 씨. 일루미나는 절대로 방어선을 저버리지 않잖아요.",
  ui_story_5083_50831602_58_dialog_content = "다행히 바튼 씨도 이번엔 드디어 여기까지 도달했잖아요. 고개를 들어 보세요...",
  ui_story_5083_50831602_59_dialog_content = "선봉 부대는 전원 나를 따르라! 서둘러라! 절대로 노병들을 실망시키지 마라!",
  ui_story_5083_50831602_60_dialog_content = "비전투인원은 이제 모두 안전해졌다! 모든 형제자매들은 들어라! 함께 자난성을 탈환하자!",
  ui_story_5083_50831602_61_dialog_content = "<color=#e8d9bb>라인하르트가 화염처럼 붉은 장창을 휘둘러, 암귀들의 방어를 돌파하며 전진하고 있었다.\n그녀의 불꽃은 마치 아침 해처럼 자난성을 밝게 비추었다.</color>",
  ui_story_5083_50831602_62_dialog_content = "빛이다...",
  ui_story_5083_50831602_63_dialog_content = "다들 저길 봐! 빛이야! 지원군이 왔어! 전우들이 돌아왔다고!",
  ui_story_5083_50831602_64_dialog_content = "우린 버려지지 않았어! 어서 눈을 떠서 보라고!",
  ui_story_5083_50831602_65_dialog_content = "<color=#e8d9bb>큰 종소리가 자난성에 울려 퍼졌다.\n지원군의 도착을 알리고, 자난성의 주인들이 돌아왔음을 알리는 종소리였다.</color>",
  ui_story_5083_50831602_66_dialog_content = "<size=45>군단장님──!</size>",
  ui_story_5083_50831602_67_dialog_content = "시끄럽다... 이 자식아... 나 아직 안 죽었다...",
  ui_story_5083_50831602_68_dialog_content = "귀가 먹은 것도 아닌데... 당연히 들리지...",
  ui_story_5083_50831602_69_dialog_content = "하하... 생각보다 빨리 와 줬군... 볼 수 있으려나 했는데...",
  ui_story_5083_50831602_70_dialog_content = "다행입니다... 정말... 다행이라고요...",
  ui_story_5083_50831602_71_dialog_content = "이놈아... 군단과 일루미나의 미래는 이제 너한테 맡긴다...\n성질 좀 죽이고... 네 그 껄렁껄렁한 버릇도 좀 고쳐라...",
  ui_story_5083_50831602_72_dialog_content = "네, 군단장님... 실망시키지 않겠습니다.",
  ui_story_5083_50831602_73_dialog_content = "바튼 씨, 군단장님은 저 사람들한테 맡기세요. 우린 이제 가야 해요...",
  ui_story_5083_50831602_74_dialog_content = "저 빛을 따라가세요... 바튼 씨 마음속에서 비롯된 빛이자... 신념을요.",
  ui_story_5083_50831602_75_dialog_content = "이건 마지막 <color=#FFB400>길 안내</color>예요. 이제 악몽을 떠날 시간이 됐어요.",
  ui_story_5083_50831602_76_dialog_content = "그래... 물론이지. 이제 다시는 그 무엇에도 갇히지 않을 거다!",
  ui_story_5083_50831602_77_dialog_content = "영감... 다시 만나자고.",
  ui_story_5083_50831602_78_dialog_content = "...?!",
  ui_story_5083_50831602_79_dialog_content = "꿈이 현실의 광경으로 변하고 있어요... 이건... 바튼 씨의 기억인가요?",
  ui_story_5083_50831602_80_dialog_content = "군단장님과 그 노병들은 마지막까지 굴복하지 않았다.\n심지어는 깃발조차 쓰러지지 않고 곧게 서 있었지.",
  ui_story_5083_50831602_81_dialog_content = "그들은 자난성은 물론, 우리의 빛을 지켜 냈다.",
  ui_story_5083_50831602_82_dialog_content = "이제 잠들 시간이에요... 바튼 씨. 날이 밝았어요... 마음 편히 쉬세요...\n이미 집으로 돌아왔으니까요.",
  ui_story_5083_50831602_83_dialog_content = "팡고 영감... PlayerName... 전우들...\n우리가 이 길을 제대로 보고 걸어올 수 있게 해 줘서... 정말 고맙다...",
  ui_story_5083_50831602_84_dialog_content = "<color=#e8d9bb>나는 한 때 땅에서 솟아올라 밤하늘을 밝히는 별의 강인함을 보았다.</color>",
  ui_story_5083_50831602_85_dialog_content = "<color=#e8d9bb>그리고 죽음을 앞두고서도 생명의 가장 찬란한 빛을 보여 준 오로리안들의 용기를 보았다.</color>",
  ui_story_5083_50831602_86_dialog_content = "<color=#e8d9bb>영웅들은 불씨를 지켜 냈다.\n그리고 불씨는 맹렬한 불길이 되어 암귀 군단을 불태우고, 아침 해를 맞이했다.</color>",
  ui_story_5083_50831602_87_dialog_content = "<color=#e8d9bb>비록 별들이 잠시 떨어져, 그 빛이 흐려질지라도, 그 별빛 속을 걸었던 이들은\n여전히 그 길을 나아가 탐색을 멈추지 않고, 마침내 여명을 맞이할 것이다.</color>",
  ui_story_5083_50831602_88_dialog_content = "<color=#e8d9bb>「이거면 된 거겠지...」</color>",
  ui_story_5083_50831602_89_dialog_content = "<color=#e8d9bb>「지난날의 별들... 고마워요.」</color>"
}
return config
